/**
 * Второй этаж справки: раздел команды, если он есть, иначе первый этаж.
 *
 * Раздела нет — печатается краткий перечень. Это не заглушка: команда без своих
 * ключей объяснена в перечне целиком, и пустой раздел был бы обещанием
 * подробностей, которых нет.
 */
static void human_help(const char *topic) {
  if (topic == NULL) {
    printf("%s%s\n", FLANG_HELP, FLANG_HELP_2);
  } else if (strcmp(topic, "check") == 0) {
    printf("%s%s\n", HELP_CHECK, HELP_CHECK_2);
  } else if (strcmp(topic, "test") == 0) {
    printf("%s\n", HELP_TEST);
  } else if (strcmp(topic, "run") == 0) {
    printf("%s\n", HELP_RUN);
  } else if (strcmp(topic, "emit") == 0) {
    printf("%s\n%s%s%s%s\n", HELP_EMIT, HELP_EMIT_2, HELP_EMIT_3, HELP_EMIT_POST, HELP_EMIT_4);
  } else if (strcmp(topic, "repl") == 0) {
    printf("%s\n", HELP_REPL);
  } else if (strcmp(topic, "lsp") == 0) {
    printf("%s\n", HELP_LSP);
  } else if (strcmp(topic, "--mcp-mode") == 0 || strcmp(topic, "mcp") == 0) {
    printf("%s\n", HELP_MCP);
  } else if (strcmp(topic, "--машина") == 0 || strcmp(topic, "--machine") == 0) {
    printf("%s\n", HELP_MACHINE);
  } else if (strcmp(topic, "ast") == 0) {
    printf("%s\n", HELP_AST);
  } else if (strcmp(topic, "tokens") == 0) {
    printf("%s\n", HELP_TOKENS);
  } else if (strcmp(topic, "facts") == 0) {
    printf("%s\n", HELP_FACTS);
  } else if (strcmp(topic, "io") == 0) {
    printf("%s\n", HELP_IO);
  } else if (strcmp(topic, "lock") == 0) {
    printf("%s\n", HELP_LOCK);
  } else if (strcmp(topic, "package") == 0) {
    printf("%s\n", HELP_PACKAGE);
  } else if (strcmp(topic, "new") == 0) {
    printf("%s\n", HELP_NEW);
  } else {
    printf("%s%s\n", FLANG_HELP, FLANG_HELP_2);
  }
}

