/** Ключи командной строки печати — одни на все цели. */
typedef struct {
  const char *own;
  const char *steps;
  const char *depth;
  int base_index;
  bool cli;
  bool shell;
} emit_wish;

/**
 * Каталог с ИСХОДНИКАМИ рантайма — не с напечатанными.
 *
 * Разница видна первой строкой: напечатанный `flang_runtime.h` начинается
 * шапкой «Сгенерировано flang», исходник — строкой SPDX. Каталог рядом с
 * бинарником (`bootstrap/`) полон именно напечатанных, и подсунуть их печати
 * значило бы приписать шапку второй раз. Поэтому каталог самого бинарника здесь
 * НЕ пробуется — в отличие от поиска заголовков для оболочки.
 */
static bool emit_probe_here(const char *directory, const char *probe_name) {
  char *probe = repl_join(directory, probe_name);
  size_t bytes = 0;
  char *text = repl_read_file(probe, &bytes);
  bool ok = false;
  free(probe);
  if (text == NULL) {
    return false;
  }
  /* «Сгенерировано» стоит в первых двухстах байтах шапки и только там. */
  ok = strstr(text, "Сгенерировано flang") == NULL;
  free(text);
  return ok;
}

/**
 * Каталог исходников рантайма ОДНОЙ цели: три места в одном порядке у всех.
 *
 * Цель отличается двумя вещами — пробным файлом, по которому каталог узнаётся,
 * и последним сегментом пути (`flang/src/emit/go`, `share/flang/go`). Всё
 * остальное — порядок «--runtime», $FLANG_RUNTIME_DIR, рядом с установленным —
 * общее, и восемь копий этого порядка разъехались бы на первой же правке.
 */
static char *emit_target_dir(const char *self_dir, const char *given, const char *probe_name,
                             const char *const *places) {
  size_t index = 0;
  if (given != NULL && given[0] != '\0') {
    return emit_probe_here(given, probe_name) ? repl_say(given) : NULL;
  }
  {
    const char *set = getenv("FLANG_RUNTIME_DIR");
    if (set != NULL && set[0] != '\0') {
      return emit_probe_here(set, probe_name) ? repl_say(set) : NULL;
    }
  }
  if (self_dir == NULL) {
    return NULL;
  }
  for (index = 0; index < 2; index += 1) {
    char *parent = repl_dirname(self_dir);
    char *directory = repl_join(parent, places[index]);
    free(parent);
    if (emit_probe_here(directory, probe_name)) {
      return directory;
    }
    free(directory);
  }
  return NULL;
}

/** Вид типа границы — обратный перевод к «Виду типа входа» из emit-c.flang. */
static const char *emit_kind_word(fl_type_kind kind) {
  switch (kind) {
    case FL_TYPE_NUMBER:
      return "число";
    case FL_TYPE_STRING:
      return "строка";
    case FL_TYPE_FLAG:
      return "признак";
    case FL_TYPE_NULL:
      return "ничто";
    case FL_TYPE_LIST:
      return "список";
    case FL_TYPE_RECORD:
      return "запись";
    case FL_TYPE_SUM:
      return "сумма";
    case FL_TYPE_UNKNOWN:
    default:
      return "неизвестно";
  }
}

/**
 * Впечатанная граница входа — обратно в значения flang.
 *
 * Порядок полей здесь не свободный: это объекты «Тип входа», «Поле входа»,
 * «Вариант входа» и «Параметр входа» из `flang/self/emit-c.flang`, и разойдись
 * имена — печать получила бы записи не тех форм.
 */
static fl_value emit_entry_types(const fl_entry_table *table) {
  static const char *const names[13] = {"вид",  "имя",     "владелец", "ничто",  "целое",
                                        "отрезок", "низ",  "верх",     "элемент", "поле с",
                                        "полей", "вариант с", "вариантов"};
  fl_value *items = NULL;
  fl_value out = fl_nothing();
  size_t index = 0;
  if (table->type_count == 0) {
    return fl_list(NULL, 0);
  }
  items = (fl_value *)repl_alloc(sizeof(fl_value) * table->type_count);
  for (index = 0; index < table->type_count; index += 1) {
    const fl_type *type = &table->types[index];
    fl_value values[13];
    values[0] = repl_value_say(emit_kind_word(type->kind));
    values[1] = repl_value_say(type->name == NULL ? "" : type->name);
    values[2] = repl_value_say(type->owner == NULL ? "" : type->owner);
    values[3] = fl_flag(type->optional);
    values[4] = fl_flag(type->integral);
    values[5] = fl_flag(type->bounded);
    values[6] = fl_number(type->low);
    values[7] = fl_number(type->high);
    values[8] = fl_number((double)type->of);
    values[9] = fl_number((double)type->field_from);
    values[10] = fl_number((double)type->field_count);
    values[11] = fl_number((double)type->variant_from);
    values[12] = fl_number((double)type->variant_count);
    items[index] = repl_value_record(names, values, 13);
  }
  out = repl_value_list(items, table->type_count);
  free(items);
  return out;
}

static fl_value emit_entry_fields(const fl_entry_table *table) {
  static const char *const names[2] = {"имя", "тип"};
  fl_value *items = NULL;
  fl_value out = fl_nothing();
  size_t index = 0;
  if (table->field_count == 0) {
    return fl_list(NULL, 0);
  }
  items = (fl_value *)repl_alloc(sizeof(fl_value) * table->field_count);
  for (index = 0; index < table->field_count; index += 1) {
    fl_value values[2];
    values[0] = repl_value_say(table->fields[index].name == NULL ? "" : table->fields[index].name);
    values[1] = fl_number((double)table->fields[index].type);
    items[index] = repl_value_record(names, values, 2);
  }
  out = repl_value_list(items, table->field_count);
  free(items);
  return out;
}

static fl_value emit_entry_variants(const fl_entry_table *table) {
  static const char *const names[3] = {"имя", "поле с", "полей"};
  fl_value *items = NULL;
  fl_value out = fl_nothing();
  size_t index = 0;
  if (table->variant_count == 0) {
    return fl_list(NULL, 0);
  }
  items = (fl_value *)repl_alloc(sizeof(fl_value) * table->variant_count);
  for (index = 0; index < table->variant_count; index += 1) {
    fl_value values[3];
    values[0] = repl_value_say(table->variants[index].name == NULL ? "" : table->variants[index].name);
    values[1] = fl_number((double)table->variants[index].field_from);
    values[2] = fl_number((double)table->variants[index].field_count);
    items[index] = repl_value_record(names, values, 3);
  }
  out = repl_value_list(items, table->variant_count);
  free(items);
  return out;
}

static fl_value emit_entry_params(const fl_entry_table *table) {
  static const char *const names[3] = {"функция", "параметр", "тип"};
  fl_value *items = NULL;
  fl_value out = fl_nothing();
  size_t index = 0;
  if (table->param_count == 0) {
    return fl_list(NULL, 0);
  }
  items = (fl_value *)repl_alloc(sizeof(fl_value) * table->param_count);
  for (index = 0; index < table->param_count; index += 1) {
    fl_value values[3];
    values[0] = repl_value_say(table->params[index].function == NULL ? "" : table->params[index].function);
    values[1] = repl_value_say(table->params[index].name == NULL ? "" : table->params[index].name);
    values[2] = fl_number((double)table->params[index].type);
    items[index] = repl_value_record(names, values, 3);
  }
  out = repl_value_list(items, table->param_count);
  free(items);
  return out;
}

/*
 * ═══════════ ПЕЧАТЬ БЕЗ ПРОВЕРКИ ПОСТУСЛОВИЙ: «--no-postconditions» ═══════════
 *
 * ЧТО КЛЮЧ СНИМАЕТ. Ровно сторожа `fl_post` в НАПЕЧАТАННОМ коде — все, а не
 * только доказанные. Постусловие остаётся в исходнике, остаётся обещанием и
 * остаётся под судом: разбор, типы, завершаемость и ядро доказательств судят
 * его этой же командой и при этом ключе, и замечание по-прежнему ОТМЕНЯЕТ
 * печать кодом 1. «flang check» и «flang test» ключа не знают вовсе — они
 * считают постусловия всегда и от печати не зависят.
 *
 * ЗАЧЕМ. Постусловие пересчитывается на КАЖДОМ возврате, и на горячем пути это
 * не проценты. Замер 2 сентября 2026 на разведочной раскладке терминального
 * экрана (19 функций, 25 обещаний, цель go; `go test -benchtime 200x -count 5`,
 * медиана пяти, AMD EPYC 7742): кадр 80×24 — 42,6 мс со сторожами против 6,00 мс
 * без них, кадр 200×50 — 100,0 мс против 14,6 мс. В 7,1 и в 6,9 раза; выделений
 * на кадре 200×50 — 151 226 против 29 354. Кадр перерисовывается не только по
 * такту, но и на каждое нажатие клавиши и на каждый SIGWINCH; 15 мс не видно,
 * 100 мс видно.
 *
 * ПОЧЕМУ КЛЮЧ ПЕЧАТИ, А НЕ ПРАВКА ИСХОДНИКА. Потому что иначе обещания вырезают
 * скриптом: рабочему, которому нужен был быстрый кадр, пришлось снять 25 строк
 * «обеспечивает» из исходника — и получить ВТОРОЙ исходник, который уже ни с
 * чем не сверяется. Ключ оставляет один исходник и один суд над ним.
 *
 * ЧЕГО КЛЮЧ НЕ ДЕЛАЕТ МОЛЧА. Всякий напечатанный файл говорит о нём сам —
 * заметкой в шапке (`emit_notice_put` ниже). Отдать облегчённый код молча
 * нельзя: тот, кто взял его в руки, обязан узнать из НЕГО, а не из истории
 * вызова, что сторожей в нём нет.
 *
 * ЧЕГО КЛЮЧ НЕ СНИМАЕТ. Предусловия, сторожа убывания у тотальных функций,
 * пределы шагов и глубины, разбор отказов надзора. Снимается ровно то, что
 * названо его именем.
 */

/** Потолок полей записи, которую этот файл копирует с подменой одного поля. */
#define EMIT_RECORD_MAX 16

/**
 * Программа без единого постусловия — и сколько их снято.
 *
 * По узлам ходит не этот файл: узел AST — это «Значение» компилятора, и все три
 * нужных шага на flang уже написаны и проверены примерами — «Элементы поля»
 * (`flang/self/emit-c.flang`), «Узел без ключа» и «Заменить поле ядра»
 * (`flang/self/bootstrap/compiler.flang`, `flang/self/proof-kernel.flang`).
 * Здесь они только зовутся по именам, ровно как рядом зовётся «Программа без
 * снятых постусловий», которой ядро отдаёт список ДОКАЗАННЫХ. Напиши C свой
 * обход AST — и две копии разошлись бы молча, по тому же доводу, который уже
 * записан у `repl_check_sources` и у «Чего печать не судила».
 *
 * Узел списка собирается ЗДЕСЬ, а не вызовом «Список как узел»: это имя в
 * замыкании не одно — три модуля объявляют его порознь, — и какое из них
 * уцелело при связывании, C знать не обязан.
 */
static bool emit_drop_postconditions(fl_value program, fl_value *out, size_t *dropped) {
  fl_value functions = fl_nothing();
  fl_value args[3];
  fl_value *thinner = NULL;
  size_t index = 0;
  bool ok = true;

  *out = program;
  args[0] = program;
  args[1] = repl_value_say("functions");
  if (repl_call("Элементы поля", args, 2, &functions) != FL_OK || functions.tag != FL_LIST) {
    return false;
  }
  if (functions.as.list.count == 0) {
    return true;
  }
  thinner = (fl_value *)malloc(functions.as.list.count * sizeof(fl_value));
  if (thinner == NULL) {
    repl_oom();
  }
  for (index = 0; ok && index < functions.as.list.count; index += 1) {
    fl_value had = fl_nothing();
    fl_value bare = fl_nothing();
    args[0] = functions.as.list.items[index];
    args[1] = repl_value_say("postconditions");
    if (repl_call("Элементы поля", args, 2, &had) == FL_OK && had.tag == FL_LIST) {
      *dropped += had.as.list.count;
    }
    args[0] = functions.as.list.items[index];
    args[1] = repl_value_say("postconditions");
    if (repl_call("Узел без ключа", args, 2, &bare) != FL_OK) {
      ok = false;
    } else {
      thinner[index] = bare;
    }
  }
  if (ok) {
    fl_value node = repl_value_variant_fields("Значение списка", "элементы",
                                              repl_value_list(thinner, functions.as.list.count));
    args[0] = program;
    args[1] = repl_value_say("functions");
    args[2] = node;
    ok = repl_call("Заменить поле ядра", args, 3, out) == FL_OK;
  }
  free(thinner);
  return ok;
}

/**
 * Копия записи, у которой одно поле заменено; имена и порядок берутся у самой
 * записи. Так «Программа с бедами» переживает подмену программы, не требуя от
 * этого файла знать её поля наизусть: прибавится поле — копия его донесёт.
 */
static bool emit_record_with(fl_value record, const char *name, fl_value value, fl_value *out) {
  const char *names[EMIT_RECORD_MAX];
  fl_value values[EMIT_RECORD_MAX];
  size_t index = 0;
  if (record.tag != FL_RECORD || record.as.record->count > EMIT_RECORD_MAX) {
    return false;
  }
  for (index = 0; index < record.as.record->count; index += 1) {
    names[index] = record.as.record->fields[index].name;
    values[index] = strcmp(record.as.record->fields[index].name, name) == 0
                        ? value
                        : record.as.record->fields[index].value;
  }
  *out = repl_value_record(names, values, record.as.record->count);
  return true;
}

/**
 * Заметка в шапку напечатанного файла — та самая, без которой ключ был бы
 * молчаливым. Возвращает новый текст или NULL, если помечать нечего.
 *
 * ГДЕ ИМЕННО. Перед строкой «Сгенерировано flang» и ТЕМ ЖЕ зачином, каким
 * написана она сама: у Go, Rust, Java, C# и JS это «// », у Python, Elixir и
 * Makefile «# », у C — « * » внутри уже открытого блока. Зачин не угадывается
 * по цели, а берётся из самой строки: девятая цель добавится строкой таблицы, и
 * заметка поедет с ней, ничего здесь не требуя.
 *
 * КОГО ПРОПУСКАЕТ. Файл без этой строки (`go.mod`) — там нечего пометить, это
 * не код программы. И описание проекта C# (`flang.csproj`): его шапка —
 * XML-комментарий, а в XML-комментарии не бывает двух дефисов подряд, тогда как
 * имя ключа их содержит. Написать имя ключа неправдой хуже, чем не написать в
 * описании проекта ничего: заметку рядом несут все восемь `.cs`, а `.csproj` —
 * не код программы.
 */
static char *emit_notice_put(const char *body, size_t bytes, size_t dropped, size_t *out_bytes) {
  static const char *const MARK = "Сгенерировано flang";
  static const char *const REST[3] = {
      "В этом коде обещание на возврате НЕ проверяется ни разу. Проверка не отменена,",
      "а осталась на воротах: «flang check» и «flang test» судят постусловия всегда и",
      "этим ключом не управляются. Правишь исходник — прогоняй их: тут нарушение молчит."};
  const size_t mark_bytes = strlen(MARK);
  repl_buf whole;
  size_t at = 0;
  size_t line = 0;
  size_t tail = 0;
  size_t lead = 0;
  size_t index = 0;
  bool found = false;

  *out_bytes = bytes;
  for (at = 0; !found && at + mark_bytes <= bytes; at += 1) {
    found = memcmp(body + at, MARK, mark_bytes) == 0;
  }
  if (!found) {
    return NULL;
  }
  at -= 1;
  for (line = at; line > 0 && body[line - 1] != '\n'; line -= 1) {
  }
  lead = at - line;
  for (tail = at; tail < bytes && body[tail] != '\n'; tail += 1) {
  }
  if (tail >= 3 && memcmp(body + tail - 3, "-->", 3) == 0) {
    return NULL;
  }

  buf_init(&whole);
  buf_add(&whole, body, line);
  buf_add(&whole, body + line, lead);
  buf_put(&whole, "ПЕЧАТАНО БЕЗ ПРОВЕРКИ ПОСТУСЛОВИЙ — ключ «flang emit --no-postconditions».");
  buf_char(&whole, '\n');
  buf_add(&whole, body + line, lead);
  buf_put(&whole, "Снято постусловий: ");
  buf_number(&whole, dropped);
  buf_put(&whole, " — ВСЕ обещания «обеспечивает» этой программы.");
  buf_char(&whole, '\n');
  for (index = 0; index < 3; index += 1) {
    buf_add(&whole, body + line, lead);
    buf_put(&whole, REST[index]);
    buf_char(&whole, '\n');
  }
  buf_add(&whole, body + line, lead);
  buf_add(&whole, body + at, bytes - at);
  *out_bytes = whole.used;
  return whole.data;
}

/**
 * Годится ли впечатанная граница связанной программе.
 *
 * Сверяются ПАРЫ «функция, параметр» по порядку, числу и именам — то же
 * перечисление, каким строит список `таблицаВхода` (по функциям программы, по
 * параметрам каждой). Совпало всё до последней пары — программа та же, и её
 * таблица годится. Разошлось хоть в одном месте — таблица чужая, и печатать по
 * ней значило бы соврать о типах напечатанного.
 *
 * Проверка НЕ доказывает совпадения типов: имена сошлись, а объявления могли
 * разойтись. Именно поэтому неподвижная точка сверяется отдельно и байтами
 * (`flang/test/self-bootstrap.test.mjs`): здесь дешёвый сторож, там приговор.
 */
static bool emit_entry_fits(fl_value program, const fl_entry_table *table) {
  const fl_value *functions = NULL;
  size_t count = 0;
  size_t index = 0;
  size_t seen = 0;
  zn_field_items(program, "functions", &functions, &count);
  for (index = 0; index < count; index += 1) {
    const char *function = NULL;
    size_t function_bytes = 0;
    const fl_value *params = NULL;
    size_t params_count = 0;
    size_t at = 0;
    if (!zn_field_text(functions[index], "name", &function, &function_bytes)) {
      return false;
    }
    zn_field_items(functions[index], "params", &params, &params_count);
    for (at = 0; at < params_count; at += 1) {
      const char *name = NULL;
      size_t name_bytes = 0;
      if (seen >= table->param_count) {
        return false;
      }
      if (!zn_field_text(params[at], "name", &name, &name_bytes)) {
        return false;
      }
      if (table->params[seen].function == NULL || table->params[seen].name == NULL) {
        return false;
      }
      if (strlen(table->params[seen].function) != function_bytes ||
          memcmp(table->params[seen].function, function, function_bytes) != 0) {
        return false;
      }
      if (strlen(table->params[seen].name) != name_bytes ||
          memcmp(table->params[seen].name, name, name_bytes) != 0) {
        return false;
      }
      seen += 1;
    }
  }
  return seen == table->param_count && seen > 0;
}

/**
 * Каталог вывода заводится САМ, вместе с промежуточными, — ровно как это делает
 * `flang emit` на Node (`mkdir(dirname(путь), { recursive: true })` в
 * `flang/bin/flang.mjs`).
 *
 * Прежде каталог не заводился, и объяснено это было тем, что `mkdir` живёт в
 * <sys/stat.h>, а этому файлу хватало стандартной библиотеки. Цена оказалась не
 * та, что называли: человек, набравший `flang emit … --out каталог/которого/нет`,
 * получал отказ про ПЕРВЫЙ ФАЙЛ рантайма — «не открыт для записи
 * …/flang_runtime.h», — и читал его как «сломан рантайм», потому что для такого
 * текста это и есть правильное чтение. Заголовок к тому же уже нужен хозяину
 * `flang io` ниже, так что нового у оболочки не прибавилось ничего.
 *
 * Неудача называет КАТАЛОГ и причину словами системы (`strerror`), а не первый
 * файл, который не открылся.
 */
static bool emit_make_dir(const char *path) {
  char *copy = NULL;
  size_t at = 0;
  bool ok = true;
  /* Пустое имя каталога — не «текущий», а недосмотр вызывающего (`--out ""`), и
     обход ниже начинается со второго знака, потому что первый может быть
     корневой косой чертой. На пустой строке второго знака нет вовсе. */
  if (path == NULL || path[0] == '\0') {
    fputs("flang emit: «--out» назван пустым именем каталога — назовите, куда печатать\n", stderr);
    return false;
  }
  copy = repl_say(path);
  if (copy == NULL) {
    fputs("flang emit: не хватило памяти под путь каталога вывода\n", stderr);
    return false;
  }
  for (at = 1; ok && copy[at] != '\0'; at += 1) {
    if (copy[at] == '/') {
      copy[at] = '\0';
      if (copy[at - 1] != '/' && mkdir(copy, 0777) != 0 && errno != EEXIST) {
        ok = false;
      }
      copy[at] = '/';
    }
  }
  if (ok && mkdir(copy, 0777) != 0 && errno != EEXIST) {
    ok = false;
  }
  if (ok) {
    /* EEXIST мог прийти и от ФАЙЛА с этим именем: тогда запись всё равно не
       выйдет, и сказать об этом надо здесь, а не первым непонятным отказом. */
    struct stat info;
    if (stat(copy, &info) == 0 && !S_ISDIR(info.st_mode)) {
      fprintf(stderr, "flang emit: «%s» — не каталог, а файл; выберите другое место для --out\n", copy);
      ok = false;
    }
  } else {
    fprintf(stderr, "flang emit: не удалось завести каталог «%s»: %s\n", copy, strerror(errno));
  }
  free(copy);
  return ok;
}

/** Запись одного напечатанного файла на диск; путь уже разрешён. */
static bool emit_write(const char *full, const char *text, size_t bytes) {
  FILE *stream = fopen(full, "wb");
  if (stream == NULL) {
    fprintf(stderr, "flang emit: не открыт для записи %s: %s\n", full, strerror(errno));
    return false;
  }
  if (bytes > 0 && fwrite(text, 1, bytes, stream) != bytes) {
    fprintf(stderr, "flang emit: не записан %s\n", full);
    fclose(stream);
    return false;
  }
  if (fclose(stream) != 0) {
    fprintf(stderr, "flang emit: не закрыт %s\n", full);
    return false;
  }
  return true;
}

/**
 * Раскладка напечатанного по диску — одна на все цели.
 *
 * Что здесь общего у восьми целей: имя файла приходит полем «путь», содержимое —
 * полем «содержимое», при «--file имя» ровно один файл уходит на стандартный
 * вывод, а не названный печатью файл — отказ со списком того, что печать даёт.
 *
 * ПОДКАТАЛОГИ ЗАВОДЯТСЯ ПО ПУТИ ФАЙЛА. У цели `c` все файлы лежат плоско, и для
 * неё не меняется ничего; у Go путь — это имя пакета (`flangrt/flang_runtime.go`),
 * человек его не выбирал и знать не обязан. Сам `--out` заведён выше.
 */
/* `dropped` больше нуля — печать шла с «--no-postconditions», и каждый файл
   обязан сказать об этом сам: заметку кладёт `emit_notice_put`. Ноль — печать
   обычная, и ни один байт вывода не меняется. */
static int emit_files_out(fl_value files, const char *out, const char *one, size_t *written,
                          size_t dropped) {
  size_t index = 0;
  int code = 0;
  bool found = false;
  for (index = 0; index < files.as.list.count && code == 0; index += 1) {
    fl_value where = fl_nothing();
    fl_value content = fl_nothing();
    const char *body = NULL;
    size_t body_bytes = 0;
    char *name = NULL;
    char *marked = NULL;
    if (!val_field(files.as.list.items[index], "путь", &where) ||
        !val_field(files.as.list.items[index], "содержимое", &content) ||
        !val_text(content, &body, &body_bytes)) {
      continue;
    }
    if (dropped > 0) {
      size_t marked_bytes = 0;
      marked = emit_notice_put(body, body_bytes, dropped, &marked_bytes);
      if (marked != NULL) {
        body = marked;
        body_bytes = marked_bytes;
      }
    }
    name = val_copy(where);
    if (one != NULL) {
      if (strcmp(name, one) == 0) {
        found = true;
        if (body_bytes > 0 && fwrite(body, 1, body_bytes, stdout) != body_bytes) {
          fputs("flang emit: вывод оборван\n", stderr);
          code = 1;
        }
        *written += body_bytes;
      }
      free(name);
      free(marked);
      continue;
    }
    {
      char *destination = repl_join(out, name);
      char *holder = strchr(name, '/') == NULL ? NULL : repl_dirname(destination);
      if (holder != NULL && !emit_make_dir(holder)) {
        code = 1;
      } else if (!emit_write(destination, body, body_bytes)) {
        code = 1;
      }
      *written += body_bytes;
      free(holder);
      free(destination);
    }
    free(name);
    free(marked);
  }
  fflush(stdout);
  if (one != NULL && !found && code == 0) {
    fprintf(stderr, "flang emit: файла «%s» печать не даёт. Что даёт:", one);
    for (index = 0; index < files.as.list.count; index += 1) {
      fl_value where = fl_nothing();
      if (val_field(files.as.list.items[index], "путь", &where)) {
        char *name = val_copy(where);
        fprintf(stderr, " %s", name);
        free(name);
      }
    }
    fputc('\n', stderr);
    code = 2;
  }
  return code;
}

/**
 * Настройки печати собираются ПО ИМЕНАМ ПОЛЕЙ, а не по счёту рук.
 *
 * У восьми целей запись настроек одна и та же в главном — путь, три предела,
 * признак прогонщика и четыре списка границы входа, — и разная в ТЕКСТАХ
 * РАНТАЙМА: у «c» их четыре, у Go два, у Java и C# шесть, у Elixir три. Поэтому
 * здесь один обход по именам полей цели: поле, чьё имя известно, заполняется
 * известным; всякое ДРУГОЕ поле — текст рантайма, и он берётся из списка файлов
 * цели по порядку. Пустое имя файла означает поле, которого у цели нет по
 * существу (у Go нет ни заголовка, ни человеческого входа), — оно приезжает
 * пустой строкой, потому что печать этих полей не читает, а пустой указатель
 * уронил бы `repl_value_text`.
 *
 * Восьми копий этой сборки настроек не будет: цель добавляется СТРОКОЙ ТАБЛИЦЫ.
 */
static int emit_call(const emit_target *target, fl_value subject, bool fits, const fl_entry_table *table,
                     const char *runtime, const emit_wish *wish, fl_value *files) {
  fl_value values[EMIT_FIELD_MAX];
  fl_value args[2];
  fl_value result = fl_nothing();
  fl_value failure = fl_nothing();
  char *texts[EMIT_RUNTIME_MAX];
  size_t sizes[EMIT_RUNTIME_MAX];
  size_t index = 0;
  size_t taken = 0;
  int code = 0;

  for (index = 0; index < EMIT_RUNTIME_MAX; index += 1) {
    texts[index] = NULL;
    sizes[index] = 0;
  }

  for (index = 0; index < target->runtime_count; index += 1) {
    if (target->runtime_files[index][0] == '\0') {
      texts[index] = repl_say("");
      continue;
    }
    {
      char *where = repl_join(runtime, target->runtime_files[index]);
      texts[index] = repl_read_file(where, &sizes[index]);
      free(where);
      if (texts[index] == NULL) {
        fprintf(stderr, "flang emit: в %s не хватает %s\n", runtime, target->runtime_files[index]);
        code = 2;
      }
    }
  }

  for (index = 0; code == 0 && index < target->field_count; index += 1) {
    const char *name = target->fields[index];
    if (strcmp(name, "путь") == 0) {
      values[index] = repl_value_say(wish->own);
    } else if (strcmp(name, "есть путь") == 0) {
      values[index] = fl_flag(wish->own[0] != '\0');
    } else if (strcmp(name, "база") == 0) {
      values[index] = fl_number((double)wish->base_index);
    } else if (strcmp(name, "предел глубины") == 0) {
      values[index] = fl_number(strtod(wish->depth, NULL));
    } else if (strcmp(name, "предел шагов") == 0) {
      values[index] = fl_number(strtod(wish->steps, NULL));
    } else if (strcmp(name, "прогонщик") == 0) {
      values[index] = fl_flag(wish->cli);
    } else if (strcmp(name, "оболочка") == 0) {
      values[index] = fl_flag(wish->shell);
    } else if (strcmp(name, "типы входа") == 0) {
      values[index] = fits ? emit_entry_types(table) : fl_list(NULL, 0);
    } else if (strcmp(name, "поля входа") == 0) {
      values[index] = fits ? emit_entry_fields(table) : fl_list(NULL, 0);
    } else if (strcmp(name, "варианты входа") == 0) {
      values[index] = fits ? emit_entry_variants(table) : fl_list(NULL, 0);
    } else if (strcmp(name, "параметры входа") == 0) {
      values[index] = fits ? emit_entry_params(table) : fl_list(NULL, 0);
    } else if (taken < target->runtime_count) {
      values[index] = repl_value_text(texts[taken], sizes[taken]);
      taken += 1;
    } else {
      /* Полей рантайма у цели больше, чем названо файлов, — это опечатка в
         таблице целей, а не положение дел. Молча подставить пустую строку
         значило бы напечатать программу без рантайма и промолчать. */
      fprintf(stderr, "flang emit: у цели «%s» поле «%s» без файла рантайма\n", target->word, name);
      code = 1;
    }
  }

  if (code == 0) {
    args[0] = subject;
    args[1] = repl_value_record(target->fields, values, target->field_count);
    if (repl_call(target->entry, args, 2, &result) != FL_OK) {
      code = 1;
    } else if (val_field(result, "ошибка", &failure) && !val_same(failure, "")) {
      char *say = val_copy(failure);
      fprintf(stderr, "flang emit: печать отказала — %s\n", say);
      free(say);
      code = 1;
    } else if (!val_field(result, "файлы", files) || files->tag != FL_LIST) {
      fputs("flang emit: печать не вернула файлов\n", stderr);
      code = 1;
    }
  }

  for (index = 0; index < EMIT_RUNTIME_MAX; index += 1) {
    free(texts[index]);
  }
  return code;
}

static int emit_file(int argc, char **argv, const char *self) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  emit_wish wish;
  fl_value sources = fl_nothing();
  fl_value files = fl_nothing();
  const fl_entry_table *table = FL_PROGRAM_ENTRY();
  const char *path = NULL;
  const char *target = NULL;
  const char *out = NULL;
  const char *one = NULL;
  const char *given_runtime = NULL;
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  char *self_dir = NULL;
  char *runtime = NULL;
  /* Слова о непосуждённой поверхности считаются РЯДОМ С ПРОВЕРКОЙ (там жива
     связанная запись), а говорятся в самом конце — вместе с остальными
     строками о том, что проверено перед печатью. Между этими двумя точками
     лежит сама печать, поэтому строку приходится нести с собой. */
  char *unjudged = NULL;
  size_t bytes = 0;
  size_t index = 0;
  size_t written = 0;
  int argument = 0;
  int code = 0;
  int chosen = -1;
  bool fits = false;
  bool opened = false;
  /*
   * ЯДРО ДОКАЗАТЕЛЬСТВ — ЕДИНСТВЕННОЕ, ЧТО СНИМАЕТ ЗДЕСЬ «--no-check».
   *
   * Разбор, связывание, типы и завершаемость остаются на месте и при ключе:
   * они и есть то, из-за чего печать ОТМЕНЯЕТСЯ.
   *
   * СКОЛЬКО ЭТО ЭКОНОМИТ — ЧИСЛО НЕ ОДНО, и разброс его больше самой экономии.
   * Замер 30 августа 2026 этим двоичным, круг «печать + сборка»:
   * `flang/self/builtins.flang` 148,8 → 18,9 с (в 7,9 раза), `cli.flang`
   * 13,1 → 7,5 с (в 1,8), а `lexer.flang` 6,5 → 6,9 с — то есть ХУЖЕ.
   *
   * Цена ядра растёт с числом ДОКАЗЫВАЕМЫХ постусловий, а не с размером файла:
   * у `lexer.flang` ядро стоит 4 % печати, у `builtins.flang` — 95 %. Сборка
   * же с ключом идёт ДОЛЬШЕ: сторожей в напечатанном больше. Где ядро дёшево,
   * ключ проигрывает, и справка об этом говорит прямо.
   *
   * Отдельный случай — где ядру не хватает миллиарда шагов:
   * `flang/self/distributed.flang` и `flang/self/bounded.flang` без ключа не
   * печатаются ВОВСЕ, с ключом печатаются за 4,4 с.
   *
   * ИМЯ КЛЮЧА ШИРЕ ЕГО ДЕЛА, и это выбранная цена. Написание `--no-check` уже
   * занято у `flang test` этого же двоичного и у свидетеля на Node; завести для
   * печати второе значило бы развести две привычки на одну работу. Раз имя
   * шире дела, дело названо словами — в справке и после КАЖДОЙ печати с ключом.
   */
  bool kernel = true;
  /*
   * ВТОРОЙ КЛЮЧ, И ОН НЕ ПРО ПРОВЕРКУ, А ПРО НАПЕЧАТАННОЕ.
   *
   * «--no-check» снимает СУД перед печатью; «--no-postconditions» суд оставляет
   * весь и снимает СТОРОЖЕЙ в напечатанном коде. Ключи независимы и сочетаются:
   * довод у каждого свой, и подменять один другим нельзя.
   *
   * Ноль здесь значит «печать обычная», и тогда ни один байт вывода не
   * отличается от прежнего — довод тот же, по которому «Программа без снятых
   * постусловий» возвращает ту же программу, когда снимать нечего.
   */
  bool postconditions = true;
  size_t dropped_by_key = 0;

  wish.own = "";
  wish.steps = "1000000";
  wish.depth = "10000";
  wish.base_index = 1;
  wish.cli = true;
  wish.shell = false;

  for (argument = 2; argument < argc; argument += 1) {
    if (strcmp(argv[argument], "--target") == 0 && argument + 1 < argc) {
      argument += 1;
      target = argv[argument];
    } else if (strcmp(argv[argument], "--out") == 0 && argument + 1 < argc) {
      argument += 1;
      out = argv[argument];
    } else if (strcmp(argv[argument], "--file") == 0 && argument + 1 < argc) {
      argument += 1;
      one = argv[argument];
    } else if (strcmp(argv[argument], "--runtime") == 0 && argument + 1 < argc) {
      argument += 1;
      given_runtime = argv[argument];
    } else if (strcmp(argv[argument], "--max-steps") == 0 && argument + 1 < argc) {
      argument += 1;
      wish.steps = argv[argument];
    } else if (strcmp(argv[argument], "--max-depth") == 0 && argument + 1 < argc) {
      argument += 1;
      wish.depth = argv[argument];
    } else if (strcmp(argv[argument], "--index-base") == 0 && argument + 1 < argc) {
      argument += 1;
      wish.base_index = strcmp(argv[argument], "0") == 0 ? 0 : 1;
    } else if (strcmp(argv[argument], "--path") == 0 && argument + 1 < argc) {
      argument += 1;
      wish.own = argv[argument];
    } else if (strcmp(argv[argument], "--cli") == 0) {
      wish.cli = true;
    } else if (strcmp(argv[argument], "--no-cli") == 0) {
      wish.cli = false;
    } else if (strcmp(argv[argument], "--repl") == 0) {
      wish.shell = true;
    } else if (strcmp(argv[argument], "--no-check") == 0) {
      kernel = false;
    } else if (strcmp(argv[argument], "--no-postconditions") == 0) {
      postconditions = false;
    } else if (argv[argument][0] != '-' && path == NULL) {
      path = argv[argument];
    } else {
      fprintf(stderr, "flang emit: непонятный ключ «%s»\n", argv[argument]);
      return 2;
    }
  }

  if (path == NULL) {
    fputs("flang emit: не назван файл. Пример: flang emit м.flang --target c --out каталог\n", stderr);
    return 2;
  }
  if (target == NULL) {
    fprintf(stderr, "flang emit требует «--target»: %s\n", EMIT_TARGETS_SAY);
    return 2;
  }
  for (index = 0; index < EMIT_TARGET_COUNT; index += 1) {
    if (strcmp(target, EMIT_TARGET_TABLE[index].word) == 0) {
      chosen = (int)index;
    }
  }
  if (chosen < 0) {
    fprintf(stderr,
            "flang emit: цели «%s» у этой сборки flang нет — %s.\n"
            "%s\n",
            target, EMIT_TARGETS_SAY, EMIT_TARGETS_REST);
    return 2;
  }
  /* Человеческий вход — это `flang_repl.c`, то есть C и только C. Молча
     проглотить ключ значило бы напечатать цель, у которой такого файла нет
     вовсе, и промолчать об этом. */
  if (wish.shell && chosen != EMIT_TARGET_C) {
    fputs("flang emit: «--repl» есть только у цели «c»: человеческий вход написан на C\n", stderr);
    return 2;
  }
  if (out == NULL && one == NULL) {
    fputs("flang emit: назовите, куда печатать: «--out каталог» (все файлы) или «--file имя»\n"
          "(один файл на стандартный вывод, например «--file compiler_flang.c»).\n",
          stderr);
    return 2;
  }

  self_dir = repl_self_dir(self);
  runtime = emit_target_dir(self_dir, given_runtime, EMIT_TARGET_TABLE[chosen].probe,
                            EMIT_TARGET_TABLE[chosen].places);
  free(self_dir);
  if (runtime == NULL) {
    fprintf(stderr,
            "flang emit: не найдены исходники рантайма %s — они уезжают в вывод ДОСЛОВНО, и\n"
            "без них печать соврала бы. Узнаются они по %s без шапки «Сгенерировано flang».\n"
            "Искали в «--runtime», в $FLANG_RUNTIME_DIR и рядом с установленным flang (%s).\n"
            "Что делать: назвать каталог с ними ключом «--runtime каталог» или переменной\n"
            "FLANG_RUNTIME_DIR; в дереве исходников это %s.\n",
            EMIT_TARGET_TABLE[chosen].title, EMIT_TARGET_TABLE[chosen].probe,
            EMIT_TARGET_TABLE[chosen].places[1], EMIT_TARGET_TABLE[chosen].places[0]);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(full);
    free(runtime);
    return 2;
  }

  /* Замок рядом со входом — та же подмена, что у остальных команд: печатается
     программа, собранная ИЗ ЗАМКА, а не из того, что случайно лежит на диске. */
  if (!lock_beside(full)) {
    code = 1;
  }

  if (code == 0) {
    repl_cycle();
    strings_init(&paths);
    strings_init(&texts);
    strings_init(&queue);
    opened = true;
    strings_say(&paths, full);
    strings_add(&texts, text, bytes);
    repl_imports_of(text, bytes, full, &queue);
    sources = repl_closure(&paths, &texts, &queue);

    {
      /*
       * ПЕЧАТЬ СПРАШИВАЕТ У ПРОВЕРКИ — И ЭТО НЕ ДОБАВКА К ОТЧЁТУ.
       *
       * До этой правки здесь стоял голый вызов «Связать исходники», и печать
       * смотрела ровно диагностики СВЯЗЫВАНИЯ: ни типов, ни завершаемости, ни
       * ядра.
       *
       * Улика, снятая прогоном 20 августа 2026 настоящими командами на
       * программах дерева: свидетель на Node отказался печатать 59 программ, и
       * ВСЕ 59 двоичный печатал — кодом 0 и шестью файлами C на каждую. Почти
       * половина этих 59 — ложные ДОКАЗАТЕЛЬСТВА: 26 отказов
       * `FLANG_PROOF_INDUCTION_*`. Это и есть довод, по которому ядро стоит в
       * подмножестве печати, а не отброшено вместе с примерами: доказанное
       * постусловие в напечатанный код НЕ едет проверкой при работе, а
       * недоказанное — едет, то есть ложное доказательство СНИМАЕТ проверку из
       * собранной программы.
       *
       * Двоичный, печатающий то, что свидетель отвергает, опаснее двоичного,
       * который чего-то не умеет: неумение видно, расхождение — нет.
       *
       * Дорога взята ТА ЖЕ, что у `flang check` (`repl_check_sources`), а не
       * своя: собери печать проверку из тех же кусков рядом — и два входа
       * одного бинарника разошлись бы молча в первую же правку. Заодно уходит
       * второе связывание: проверка связывает сама и отдаёт связанную
       * программу, а связывание на компиляторе стоит дороже всего остального
       * вместе взятого.
       *
       * `examples` равно false — граница подмножества, названная и измеренная;
       * довод записан над `repl_check_sources`, а человеку он говорится словами
       * после печати.
       */
      fl_value program = fl_nothing();
      fl_value linked = fl_nothing();
      fl_value dropped = fl_nothing();
      fl_value own = fl_nothing();
      repl_bads list;
      bool has_program = false;
      bads_init(&list);
      if (!repl_check_sources(sources, full, &list, &program, &has_program, NULL, kernel, false, true,
                              EMIT_TARGET_TABLE[chosen].collision, &linked, &dropped, &own)) {
        check_print_bads(&list, path, paths.count);
        fprintf(stderr,
                "flang emit: печать отменена — программа не проходит проверку, замечаний %lu.\n"
                "Разбор, типы, завершаемость и ядро доказательств смотрит «flang check» этого же\n"
                "бинарника: он назовёт то же самое и полнее.\n",
                (unsigned long)list.count);
        bads_free(&list);
        code = 1;
      } else if (!has_program) {
        bads_free(&list);
        fputs("flang emit: связывание не вернуло программы\n", stderr);
        code = 1;
      } else {
        /*
         * ДОКАЗАННОЕ ПОСТУСЛОВИЕ СНИМАЕТСЯ ЗДЕСЬ, ПЕРЕД ПЕЧАТЬЮ, И НИГДЕ БОЛЬШЕ.
         *
         * До этой правки печать ставила сторожа `fl_post` на КАЖДОЕ постусловие,
         * включая те, о которых ядро в этой же команде сказало «доказано обо
         * ВСЕХ входах»: `flang emit flang/stdlib/result.flang --target c` давал
         * десять сторожей на десять постусловий, из них четыре доказанных.
         * Доказательство выходило наказанием — чем больше докажешь, тем
         * медленнее станет собранная программа.
         *
         * Список снимаемых считает ядро (`Суд ядра о программе`), и условий у
         * него два: вердикт «доказано» И хотя бы один `пример` у функции. Здесь
         * он только применяется: C ничего не решает и в узлы не заглядывает —
         * список уезжает обратно в flang нетронутым.
         *
         * Вычислителя это не касается: `flang run`, `flang test` и прогон
         * примеров при `flang check` считают все постусловия по-прежнему.
         */
        size_t drop_count = dropped.tag == FL_LIST ? dropped.as.list.count : 0;
        bads_free(&list);
        /*
         * ЧЕГО ПЕЧАТЬ НЕ СУДИЛА — СПРАШИВАЕТСЯ ЗДЕСЬ, ОТВЕЧАЕТСЯ В КОНЦЕ.
         *
         * Проверка научилась говорить о непосуждённом кодом 2 («я не судила»),
         * печать научилась не выпускать не прошедшее проверку кодом 1. Вместе
         * эти две правки дыру не закрывали: код 2 печать не останавливал, и
         * программа с категорной поверхностью выходила из печати кодом 0 со
         * словами «проверено перед печатью — разбор, типы, завершаемость и
         * ядро», то есть с прямой неправдой.
         *
         * Улика ДО, снятая прогоном на дереве 20 августа 2026: 41 программа из
         * 951 получает у `flang check` код 2, и ВСЕ 41 печатались кодом 0 —
         * шестью файлами C на каждую. В корпусе ведомости — 26 из 294.
         *
         * Список имён считает СЛОЙ НА FLANG («Чего печать не судила» в
         * `flang/self/bootstrap/compiler.flang`), а не этот файл, и по тому же
         * доводу, что у `check`: назови его C сам — и две копии разошлись бы
         * молча. Фраза у печати СВОЯ, третья: ведомость не печатается вовсе,
         * проверка не заканчивается словами «замечаний нет», а печать печатает
         * — и сказать ей надо не «я не берусь», а «вот файлы, и вот чего за
         * ними не проверено».
         *
         * ВХОДНОЙ ФАЙЛ РАЗБИРАЕТСЯ ОТДЕЛЬНО ОТ СВЯЗАННОГО по той же причине,
         * что у `check`: связывание теряет свойства и преобразования, и по
         * одной связанной записи бинарник промолчал бы ровно о двух
         * поверхностях из четырнадцати.
         *
         * РАЗБОР БЕРЁТСЯ У ПРОВЕРКИ, А НЕ ДЕЛАЕТСЯ ЗАНОВО. Проверка выше уже
         * разобрала этот же текст с этим же пустым списком ввозов ради законов
         * категории и отдала разбор через `own`. Прежде здесь стоял свой
         * разбор, и цена его была названа в разборах — «один разбор входного
         * файла», — а в секундах вышла вдесятеро дороже того, ради чего
         * платится: замер 27 августа 2026 дал 21,66 с при 0,00 с у самого шага
         * «Чего печать не судила».
         *
         * Ничто в `own` значит «разбор не дошёл» — тогда спрашивают связанную,
         * ровно как спрашивали при отказе своего разбора.
         */
        {
          fl_value obstacle = fl_nothing();
          fl_value obstacle_args[2];
          const char *utf8 = NULL;
          size_t obstacle_bytes = 0;
          obstacle_args[0] = linked;
          obstacle_args[1] = own.tag == FL_NOTHING ? program : own;
          if (repl_call("Чего печать не судила", obstacle_args, 2, &obstacle) == FL_OK
              && val_text(obstacle, &utf8, &obstacle_bytes) && obstacle_bytes > 0) {
            unjudged = val_copy(obstacle);
          }
        }
        /*
         * «--no-postconditions» СНИМАЕТ ВСЕ, И ПОТОМУ ИДЁТ ВМЕСТО СНЯТИЯ ЯДРОМ,
         * А НЕ ПОСЛЕ НЕГО. Список ядра — подмножество снимаемого ключом, и звать
         * оба значило бы дважды пройти по тем же узлам ради того же итога, а
         * потом ещё и объяснять человеку два числа вместо одного.
         *
         * Восемь целей ведут себя ОДИНАКОВО, и это не старание: постусловия
         * снимаются с AST здесь, до `emit_call`, — то есть до того места, где
         * цели вообще расходятся. Печатнику незачем знать про ключ, и девятая
         * цель получит его тем, что появится строкой таблицы.
         *
         * Пять целей из восьми читают СВЯЗАННУЮ запись, а не голую программу
         * (`from_linked`), поэтому подменяются обе: правь одну — печать
         * разошлась бы между целями молча.
         */
        if (!postconditions) {
          fl_value thinner = fl_nothing();
          if (!emit_drop_postconditions(program, &thinner, &dropped_by_key)) {
            fputs("flang emit: не вышло снять постусловия — печать отменена\n", stderr);
            code = 1;
          } else {
            program = thinner;
          }
          if (code == 0 && EMIT_TARGET_TABLE[chosen].from_linked) {
            fl_value inner = fl_nothing();
            fl_value bare = fl_nothing();
            fl_value shaved = fl_nothing();
            size_t again = 0;
            if (!val_field(linked, "программа", &inner)
                || !emit_drop_postconditions(inner, &bare, &again)
                || !emit_record_with(linked, "программа", bare, &shaved)) {
              fputs("flang emit: не вышло снять постусловия у связанного — печать отменена\n", stderr);
              code = 1;
            } else {
              linked = shaved;
            }
          }
        } else if (drop_count > 0) {
          fl_value drop_args[2];
          fl_value thinner = fl_nothing();
          drop_args[0] = program;
          drop_args[1] = dropped;
          if (repl_call("Программа без снятых постусловий", drop_args, 2, &thinner) == FL_OK) {
            program = thinner;
          }
          if (EMIT_TARGET_TABLE[chosen].from_linked) {
            fl_value thinner_linked = fl_nothing();
            drop_args[0] = linked;
            drop_args[1] = dropped;
            if (repl_call("Связанное без снятых постусловий", drop_args, 2, &thinner_linked) == FL_OK) {
              linked = thinner_linked;
            }
          }
          fprintf(stderr,
                  "проверок при работе снято %lu: постусловие доказано ядром обо всех входах и\n"
                  "проверено примерами функции — в напечатанный код оно не едет.\n",
                  (unsigned long)drop_count);
        }
        if (code == 0) {
          fits = emit_entry_fits(program, table);
          code = emit_call(&EMIT_TARGET_TABLE[chosen],
                           EMIT_TARGET_TABLE[chosen].from_linked ? linked : program, fits, table,
                           runtime, &wish, &files);
        }
      }
    }
  }

  if (code == 0 && one == NULL && !emit_make_dir(out)) {
    code = 2;
  }

  if (code == 0) {
    code = emit_files_out(files, out, one, &written, dropped_by_key);
    if (code == 0) {
      /* Число файлов и байт — на stderr, потому что stdout занят печатью:
         `flang emit … --file x.c > x.c` обязан дать РОВНО файл. */
      if (one == NULL) {
        fprintf(stderr, "напечатано файлов %lu, байт %lu, в %s\n", (unsigned long)files.as.list.count,
                (unsigned long)written, out);
      }
      /*
       * ЧТО ЗДЕСЬ СКАЗАНО ЧЕЛОВЕКУ, А ЧТО — НЕТ.
       *
       * Прежде здесь стояли четыре строки про устройство инструмента: про слой
       * типов, про имя нашей функции и про число параметров ЧУЖОЙ программы,
       * впечатанной в двоичный. Человеку, попросившему код на C, ни одно из
       * трёх не говорит ничего и делать ему с этим нечего.
       *
       * Остаётся ровно то, что меняет его работу: у напечатанного прогонщика
       * аргументы по типам не проверяются, и где взять проверку.
       */
      if (!fits) {
        fputs("аргументы напечатанной программы по типам не проверяются: это ограничение "
              "двоичного flang, полная проверка есть в версии для Node\n",
              stderr);
      }
      /*
       * ЧТО ПРОВЕРЕНО ПЕРЕД ПЕЧАТЬЮ, А ЧТО НЕТ — СЛОВАМИ И ВСЕГДА.
       *
       * Правило шире этого места и записано соседней работой: урезанная сборка
       * вправе чего-то не уметь, но не вправе отвечать на непроверенное тем же
       * молчанием, что на проверенное. `flang check` этого бинарника называет
       * своё подмножество прямо («проверено — разбор, типы, завершаемость, ядро
       * и примеры»); печать до сих пор не называла ничего, потому что и не
       * проверяла ничего.
       *
       * Строка идёт НА stderr и НЕ меняет кода возврата, и это решение, а не
       * недосмотр. Ответ `check` — это ВЕРДИКТ, и код обязан его нести; ответ
       * `emit` — это ФАЙЛЫ, и код говорит, напечатались ли они. Отдай здесь
       * код 2 при напечатанных файлах — и всякий `make`, всякий сценарий сборки
       * и сама пересборка компилятора без Node прочли бы успешную печать как
       * отказ. Рядом уже стоит строка того же рода и с тем же кодом 0 — про
       * непроверяемые аргументы напечатанной программы.
       *
       * ── ПОЧЕМУ ФРАЗ ДВЕ, А НЕ ОДНА С ОГОВОРКОЙ ────────────────────────────
       * С ключом «--no-check» первая половина этой строки стала бы прямой
       * неправдой: ядро не прогонялось, а строка утверждала бы, что прогонялось.
       * Проверка, которая врёт о том, что она проверила, хуже отсутствующей —
       * отсутствующую видно, совравшую нет.
       *
       * И названо здесь НЕ ТОЛЬКО то, чего не смотрели, но и то, что от этого
       * стало с напечатанным: постусловия уехали в код ВСЕ, потому что список
       * снимаемых считает ядро (см. «ДОКАЗАННОЕ ПОСТУСЛОВИЕ СНИМАЕТСЯ ЗДЕСЬ»
       * выше), а его не было. Числа этих сторожей здесь не назвать, и это не
       * недосмотр: считать их умеет ровно тот, кого сняли.
       *
       * ── ПОЧЕМУ КОД ВОЗВРАТА ПРИ ЭТОМ НЕ МЕНЯЕТСЯ ─────────────────────────
       * По доводу, уже записанному выше: код 3 несёт новость о КОНКРЕТНОЙ
       * программе — у 41 файла дерева из 951 пробел есть, у остальных 910 нет.
       * Пробел от «--no-check» не про программу, а про вызов: он одинаков на
       * всякой программе этого прогона, и человек, набравший ключ, узнал о нём
       * раньше двоичного. Код, меняющийся всегда, новости не несёт. Код 3 при
       * этом остаётся живым и здесь: несуждённую поверхность ключ не отменяет.
       */
      if (kernel) {
        fputs("проверено перед печатью — разбор, типы, завершаемость и ядро доказательств.\n",
              stderr);
      } else {
        fputs("проверено перед печатью — разбор, типы, завершаемость. ЯДРО ДОКАЗАТЕЛЬСТВ НЕ\n"
              "ПРОГНАНО: его снял ключ «--no-check». Проверено, стало быть, не то же, что\n"
              "обычно, и напечатано не то же:\n"
              "  * ложного доказательства здесь никто не ловил. «flang check» этого же\n"
              "    бинарника поймал бы — прогоните его, прежде чем верить напечатанному;\n"
              "  * СТОРОЖА ОСТАЛИСЬ ВСЕ. Постусловия уехали в напечатанный код до одного,\n"
              "    включая те, что печать с ядром сняла бы. Сколько их — этой печатью не\n"
              "    сказать: считает снимаемых ядро, а ядра не было. Напечатанное поэтому\n"
              "    толще и на работе медленнее, но не слабее: лишний сторож стережёт то,\n"
              "    что и так верно.\n"
              "ЭТИМ НЕ ПЕРЕПЕЧАТЫВАЮТ СЕМЯ: отпечаток не сойдётся, а толстый двоичный поведёт\n"
              "следующую печать медленнее. Ключ — средство правки, а не замена перепечатке.\n",
              stderr);
      }
      /*
       * ВСЛУХ И ПОСЛЕ ПЕЧАТИ — по тому же доводу, что у «--no-check»: ключ,
       * уехавший в скопированный рецепт, иначе становится привычкой за день.
       * Число здесь настоящее — считано на этой программе, а не взято из
       * справки; сказать его умеет ровно тот, кто сторожей и снял.
       */
      if (!postconditions) {
        fprintf(stderr,
                "ПОСТУСЛОВИЯ СНЯТЫ КЛЮЧОМ «--no-postconditions»: %lu, то есть ВСЕ обещания этой\n"
                "программы. Сторожей в напечатанном станет меньше на столько же за вычетом тех,\n"
                "что стоят у функций, до которых от входа не дойти: их печать отбрасывает и без\n"
                "ключа. Проверены обещания при этом были — судом выше, в этой же команде, и\n"
                "замечание отменило бы печать. Не проверяются они только в напечатанном коде, и\n"
                "каждый напечатанный файл говорит об этом своей шапкой. Меняете исходник —\n"
                "прогоняйте «flang check» и «flang test»: там постусловия судятся всегда.\n",
                (unsigned long)dropped_by_key);
      }
      fputs("ПРИМЕРЫ НЕ ПРОГНАНЫ: их считает вычислитель на самом языке, и на самых больших\n"
            "программах он в предел шагов этого бинарника не укладывается — свяжи с ними\n"
            "печать, и компилятор перестал бы печатать сам себя. Прогоните их отдельно:\n"
            "flang test <файл>\n",
            stderr);
      /*
       * КОД 3: НАПЕЧАТАНО, НО ПРОВЕРЕНО НЕ ВСЁ.
       *
       * Строкой выше печать говорит, ЧТО она проверила. Если в программе
       * объявлено то, чего этот бинарник не судит вовсе, — та строка одна была
       * бы полуправдой: перечисленное действительно проверено, а про остальное
       * не сказано ничего. Здесь названо остальное, поимённо.
       *
       * ── ПОЧЕМУ КОД МЕНЯЕТСЯ, ХОТЯ РЯДОМ НАПИСАНО «НЕ МЕНЯЕТ КОДА» ─────────
       * Довод выше («ответ emit — это ФАЙЛЫ, и код говорит, напечатались ли
       * они») остаётся верным для строк о том, что печать УМЕЕТ, но не проверяет
       * — про типы аргументов прогонщика и про непрогнанные примеры. Там нечего
       * различать: так печать ведёт себя на КАЖДОЙ программе, и код, меняющийся
       * всегда, не несёт новости.
       *
       * Здесь новость есть, и она про конкретную программу: у 41 файла дерева
       * из 951 она приходит, у остальных 910 — нет. Молчание кодом означало бы,
       * что сценарий сборки, ждущий нуля, узнаёт о пробеле ровно никогда.
       *
       * ── ПОЧЕМУ 3, А НЕ 2 ─────────────────────────────────────────────────
       * Код 2 у печати занят ошибкой ВЫЗОВА (FLANG_CLI: непонятный ключ, не
       * назван файл, нет «--target», не завёлся каталог вывода) — восемь мест
       * выше, и все означают «файлов нет вовсе». Отдай его же при напечатанных
       * файлах — и по коду стало бы не отличить «ты неправильно позвал,
       * собирать нечего» от «файлы есть, но за них не ручаются». Это два
       * противоположных исхода, и одно число на оба — та же молчаливая подмена,
       * ради устранения которой правка и написана.
       *
       * ── ЧТО ЭТО СТОИТ РАСКРУТКЕ ──────────────────────────────────────────
       * `scripts/raskrutka.sh` стоит под `set -e`, и любой ненулевой код печати
       * её останавливает. Замерено на этом дереве: ни один модуль замыкания
       * `flang/self/bootstrap/compiler.flang` не объявляет ни одной из
       * четырнадцати поверхностей, поэтому компилятор получает здесь 0 и
       * печатает себя как прежде. Появится поверхность в его замыкании —
       * раскрутка встанет, и это правильно: собирать компилятор из
       * непроверенного нельзя молча.
       */
      if (unjudged != NULL) {
        fprintf(stderr, "%s\n", unjudged);
        code = 3;
      }
      if (EMIT_TARGET_TABLE[chosen].build_say != NULL && one == NULL) {
        fprintf(stderr, "%s\n", EMIT_TARGET_TABLE[chosen].build_say);
      }
    }
  }

  if (opened) {
    strings_free(&paths);
    strings_free(&texts);
    strings_free(&queue);
  }
  free(runtime);
  free(unjudged);
  free(text);
  free(full);
  return code;
}

static const char REPL_PROMPT[] = "» ";
static const char REPL_CONTINUATION[] = "… ";

/**
 * Терминал вокруг сессии: приглашения, склейка многострочного ввода и выбор
 * потока для печати. Всё, что решает, чем является строка и что с ней делать,
 * живёт выше — там же, где и в Node-версии.
 *
 * Многострочность собирается ровно одним правилом: строки копятся, пока
 * `repl_needs_more` говорит «объявление не закончено», и пустая строка
 * заканчивает ввод всегда. Остаток буфера отправляется при конце ввода — иначе
 * `flang repl < сценарий.flang` терял бы последнее объявление файла, если автор
 * не оставил в конце пустую строку.
 */
static int repl_loop(int argc, char **argv, const char *self) {
  repl_session session;
  repl_buf buffer;
  repl_buf line;
  struct sigaction action;
  const char *file = NULL;
  const bool interactive = isatty(0) == 1;
  bool failed = false;
  bool quit = false;
  int index = 0;

  repl_open_session(&session, self);
  repl_open = &session;
  atexit(repl_sweep);

  for (index = 1; index < argc; index += 1) {
    if (strcmp(argv[index], "--max-steps") == 0 && index + 1 < argc) {
      index += 1;
      free(session.steps);
      session.steps = repl_say(argv[index]);
    } else if (strcmp(argv[index], "--max-depth") == 0 && index + 1 < argc) {
      index += 1;
      free(session.depth);
      session.depth = repl_say(argv[index]);
    } else if (argv[index][0] != '-') {
      file = argv[index];
    }
  }

  action.sa_handler = repl_on_interrupt;
  sigemptyset(&action.sa_mask);
  action.sa_flags = 0;
  sigaction(SIGINT, &action, NULL);

  /* Приглашения печатаются только человеку: под конвейером они попали бы в
     вывод и испортили его тому, кто читает результат сценария. Приветствие
     выбирается по тому, чем оболочка на самом деле располагает: обещать
     вычисление, а следующей строкой признаваться, что вычислять нечем, значит
     соврать первой строкой — её и прочтут. */
  if (interactive) {
    printf("%s\n", session.why_no_eval == NULL ? REPL_GREETING : REPL_GREETING_NO_EVAL);
  }
  /* Про отсутствие вычислителя — один раз и в stderr: stdout принадлежит
     результату сценария. */
  if (session.why_no_eval != NULL) {
    fprintf(stderr, "%s\n", session.why_no_eval);
  }
  if (file != NULL && !repl_command_load(&session, file)) {
    failed = true;
  }

  buf_init(&buffer);
  buf_init(&line);
  if (interactive) {
    fputs(REPL_PROMPT, stdout);
    fflush(stdout);
  }
  for (;;) {
    const repl_read got = repl_read_line(&line);
    if (got == REPL_INTERRUPT) {
      buf_reset(&buffer);
      if (interactive) {
        printf("\n%s", REPL_PROMPT);
        fflush(stdout);
      }
      continue;
    }
    if (got == REPL_EOF) {
      break;
    }
    if (buffer.used > 0) {
      buf_char(&buffer, '\n');
    }
    buf_add(&buffer, line.data, line.used);
    if (repl_needs_more(&session, buffer.data)) {
      if (interactive) {
        fputs(REPL_CONTINUATION, stdout);
        fflush(stdout);
      }
      continue;
    }
    {
      char *own = repl_dup(buffer.data, buffer.used);
      buf_reset(&buffer);
      if (!repl_submit(&session, own, &quit)) {
        failed = true;
      }
      free(own);
    }
    fflush(stdout);
    if (quit) {
      break;
    }
    if (interactive) {
      fputs(REPL_PROMPT, stdout);
      fflush(stdout);
    }
  }
  if (!quit && buffer.used > 0 && !repl_submit(&session, buffer.data, &quit)) {
    failed = true;
  }
  fflush(stdout);

  buf_free(&buffer);
  buf_free(&line);
  repl_close_session(&session);
  /* Человеку код возврата не нужен — он видел ошибку и продолжил работать.
     Конвейеру нужен: `flang repl < сценарий.flang` — это прогон сценария, и
     молча отдать 0 после диагностики значило бы соврать вызывающему. */
  return interactive || !failed ? 0 : 1;
}

/**
 * `flang check` с ключами. `--json` осмыслен только рядом с `--proof`: без него
 * `check` и так печатает человеку, и молча принять ключ, который ничего не
 * меняет, значило бы пообещать работу и её не сделать.
 */
/*
 * `--предел-шагов N` — ЕДИНСТВЕННЫЙ разбор числа предела, и он строгий.
 *
 * Строгий потому, что эталон на flang (`flang/self/cli.flang`) числа ключей
 * читает своим разбором, а он «1e3» не принимает вовсе. `strtod` здесь дал бы
 * 1000 там, где эталон отказывает, — и свидетель разошёлся бы с эталоном молча,
 * на ключе, который поднимает защиту от зависания. Поэтому только цифры.
 *
 * Ноль не принимается: `ctx->max_steps == 0` в рантайме выключает счёт совсем,
 * а этот ключ — про «поднять предел осознанно», а не про «снять его».
 */
static bool human_steps(const char *text, size_t *out) {
  size_t value = 0;
  size_t at = 0;
  if (text == NULL || text[0] == 0) {
    return false;
  }
  for (at = 0; text[at] != 0; at += 1) {
    if (text[at] < '0' || text[at] > '9') {
      return false;
    }
    if (value > ((size_t)-1 - (size_t)(text[at] - '0')) / 10) {
      return false;
    }
    value = value * 10 + (size_t)(text[at] - '0');
  }
  if (value == 0) {
    return false;
  }
  *out = value;
  return true;
}

static int check_command(int argc, char **argv) {
  const char *path = NULL;
  const char *record = NULL;
  bool proof = false;
  bool json = false;
  bool fast = false;
  bool strict = false;
  int index = 0;
  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--proof") == 0) {
      proof = true;
    } else if (strcmp(argv[index], "--json") == 0) {
      json = true;
    } else if (strcmp(argv[index], "--строго") == 0 || strcmp(argv[index], "--strict") == 0) {
      strict = true;
    } else if (strcmp(argv[index], "--быстро") == 0 || strcmp(argv[index], "--fast") == 0) {
      fast = true;
    } else if (strcmp(argv[index], "--предел-шагов") == 0 || strcmp(argv[index], "--step-limit") == 0) {
      size_t steps = 0;
      index += 1;
      if (index >= argc) {
        fputs("flang check --предел-шагов: не названо число шагов\n", stderr);
        return 2;
      }
      if (!human_steps(argv[index], &steps)) {
        fprintf(stderr,
                "flang check --предел-шагов: «%s» — не целое число шагов больше нуля\n",
                argv[index]);
        return 2;
      }
      /* Ложится в умолчание рантайма, а не в текущий контекст: контекст
         заводится заново на каждый вызов компилятора (`repl_cycle`). */
      fl_max_steps_default_set(steps);
      repl_ctx.max_steps = steps;
    } else if (strcmp(argv[index], "--записать") == 0 || strcmp(argv[index], "--record") == 0) {
      index += 1;
      if (index >= argc) {
        fputs("flang check --записать: не назван файл, куда класть доказательство\n", stderr);
        return 2;
      }
      record = argv[index];
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang check: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang check: не назван файл. Пример: flang check модуль.flang\n", stderr);
    return 2;
  }
  if (json && !proof) {
    fputs("flang check --json осмыслен только рядом с «--proof»: без ведомости печатать в JSON нечего\n", stderr);
    return 2;
  }
  if (record != NULL && !proof) {
    fputs("flang check --записать осмыслен только рядом с «--proof»: без ведомости доказательства нет\n", stderr);
    return 2;
  }
  /* Ведомость — это ОТВЕТ ЯДРА, а «--быстро» ядра как раз не зовёт. Ведомость,
     напечатанная без ядра, была бы ведомостью, где не сказано ни одного слова о
     доказательстве, — и пустой её раздел читался бы как «доказывать нечего».
     Молча принять ключ, который ничего не меняет, здесь тоже нельзя: это тот же
     довод, по которому отвергается «--json» без «--proof». */
  if (fast && proof) {
    fputs("flang check --быстро и --proof вместе не имеют смысла: ведомость доказательства — это "
          "ответ ядра, а «--быстро» ядро не зовёт. Ведомость без ядра была бы пустой, и её пустота "
          "читалась бы как «доказывать нечего»\n",
          stderr);
    return 2;
  }
  if (strict && !proof) {
    fputs("flang check --строго осмыслен только рядом с «--proof»: без ведомости приговаривать нечего\n",
          stderr);
    return 2;
  }
  return proof ? proof_file(path, json, record, strict) : check_file(path, fast);
}

/* ═══════════════════════════════ flang ast ═══════════════════════════════ */

/*
 * ОТСТУП В JSON СЧИТАЕТСЯ ЗДЕСЬ, А САМ JSON — НЕТ.
 *
 * Байты дерева печатает слой на flang («Печать значения» из `core/json.flang`),
 * и печатает их ровно так, как `JSON.stringify` без отступа: порядок ключей,
 * запись чисел, экранирование — всё оттуда. Заводить второй печатник в C
 * значило бы завести второй способ разойтись со свидетелем на первом же
 * непечатном символе.
 *
 * `--pretty` — не второй печатник, а перекладка пробелов в уже готовой строке,
 * и правило у неё одно: пустые `{}` и `[]` `JSON.stringify` оставляет в одну
 * строку, а непустые раскрывает. Строковые литералы проходят насквозь: скобка
 * внутри строки — это буква, а не структура.
 */
static void ast_newline(FILE *stream, size_t depth) {
  size_t at = 0;
  fputc('\n', stream);
  for (at = 0; at < depth * 2; at += 1) {
    fputc(' ', stream);
  }
}

/* Поток параметром — ради `flang io`: у него отказ уезжает в stderr, и печатать
   его вторым способом значило бы завести второй способ разойтись. */
static void ast_pretty_to(FILE *stdout_or_stderr, const char *utf8, size_t bytes) {
  FILE *const поток = stdout_or_stderr;
  size_t at = 0;
  size_t depth = 0;
  bool in_string = false;
  bool escaped = false;
  for (at = 0; at < bytes; at += 1) {
    const char ch = utf8[at];
    if (in_string) {
      fputc(ch, поток);
      if (escaped) {
        escaped = false;
      } else if (ch == '\\') {
        escaped = true;
      } else if (ch == '"') {
        in_string = false;
      }
      continue;
    }
    if (ch == '"') {
      in_string = true;
      fputc(ch, поток);
    } else if (ch == '{' || ch == '[') {
      const char next = at + 1 < bytes ? utf8[at + 1] : '\0';
      fputc(ch, поток);
      if (next != '}' && next != ']') {
        depth += 1;
        ast_newline(поток, depth);
      }
    } else if (ch == '}' || ch == ']') {
      const char prev = at > 0 ? utf8[at - 1] : '\0';
      if (prev == '{' || prev == '[') {
        fputc(ch, поток);
      } else {
        depth -= 1;
        ast_newline(поток, depth);
        fputc(ch, поток);
      }
    } else if (ch == ',') {
      fputc(ch, поток);
      ast_newline(поток, depth);
    } else if (ch == ':') {
      fputs(": ", поток);
    } else {
      fputc(ch, поток);
    }
  }
}

static void ast_pretty(const char *utf8, size_t bytes) { ast_pretty_to(stdout, utf8, bytes); }


/**
 * `flang tokens <файл> [--json] [--pretty]` — поток токенов, как его прочитал
 * лексер, и ответ «ключевое ли это слово».
 *
 * ── Зачем команда есть ──────────────────────────────────────────────────────
 *
 * Проверки, живущие снаружи языка, спрашивают о программе одно и то же: чем
 * будет это слово, если его написать. Ответ знает только лексер, и до этой
 * команды достать его было нечем — приходилось писать второй разбор `.flang`
 * рядом с настоящим. Второй разбор разъезжается с первым на первой же правке
 * языка, и разъезжается молча.
 *
 * Грепом вопрос не решается, и это замерено на заведении слова `убывает`:
 * текста «убывает» в дереве было 58 вхождений, а голым именем — НИ ОДНОГО.
 * Ломает программу не текст, а токен: слово в комментарии, слово внутри
 * литерала и имя в ёлочках ключевым не становятся никогда.
 *
 * ── Три вида вывода ─────────────────────────────────────────────────────────
 *
 *   flang tokens <файл>                    человеку: место и вид каждого токена
 *   flang tokens <файл> --json             машине: тот же JSON-вид, что у `ast`
 *   flang tokens --keyword «код символа»   ключевое ли это слово
 *
 * `--pretty` включает машинный вид сам: расставлять отступы в человеческом
 * выводе нечему.
 *
 * ЛЕКСЕР ЗДЕСЬ ОДИН И ТОТ ЖЕ во всех трёх видах, и «ключевое ли это слово»
 * отвечается ПРОГОНОМ, а не заглядыванием в таблицу: таблица — ещё одно место,
 * которое может разъехаться с языком.
 *
 * Связывания здесь нет, в отличие от `flang ast`, и это не недоделка: токены
 * файла от его подключений не зависят вовсе, а чтение чужих файлов сделало бы
 * ответ про этот файл зависящим от того, лежат ли рядом его соседи.
 *
 * Отказ бывает ровно там, где лексер отказал сам: незакрытый литерал, рваный
 * отступ. Тогда код 1, беды идут в stderr, а машинный вид всё равно печатается
 * — с пустым `tokens` и заполненным `diagnostics`.
 */
static int tokens_file(int argc, char **argv) {
  fl_value args[2];
  fl_value view = fl_nothing();
  fl_value field = fl_nothing();
  const char *path = NULL;
  const char *phrase = NULL;
  bool machine = false;
  bool pretty = false;
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  const char *utf8 = NULL;
  size_t bytes = 0;
  size_t at = 0;
  int index = 0;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--json") == 0) {
      machine = true;
    } else if (strcmp(argv[index], "--pretty") == 0) {
      machine = true;
      pretty = true;
    } else if (strcmp(argv[index], "--keyword") == 0) {
      index += 1;
      if (index >= argc) {
        fputs("flang tokens: у «--keyword» не названа фраза. Пример: flang tokens --keyword «код символа»\n", stderr);
        return 2;
      }
      phrase = argv[index];
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang tokens: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }

  if (phrase != NULL) {
    if (path != NULL) {
      fprintf(stderr, "flang tokens: «--keyword» спрашивает про фразу, и файл «%s» при нём лишний\n", path);
      return 2;
    }
    repl_cycle();
    args[0] = repl_value_say(phrase);
    if (repl_call(machine ? "Печать ключевого слова" : "Ключевое слово фразы", args, 1, &view) != FL_OK ||
        !val_text(view, &utf8, &bytes)) {
      fputs("flang tokens: лексер не ответил про фразу\n", stderr);
      return 1;
    }
    if (machine) {
      if (pretty) {
        ast_pretty(utf8, bytes);
      } else {
        fwrite(utf8, 1, bytes, stdout);
      }
      fputc('\n', stdout);
    } else if (bytes == 0) {
      /* «Не ключевое» — это и «лексер отдал имя», и «отдал несколько токенов»:
         `элемент или беда` — три ключевых слова подряд, а формы такой нет
         вовсе. Обе причины ведут к одному ответу, и называть одну из них
         значило бы соврать про вторую. */
      printf("«%s» — не ключевое слово языка: одним ключевым токеном лексер это не отдаёт\n", phrase);
    } else {
      printf("«%s» — ключевое слово, конструкция «%.*s»\n", phrase, (int)bytes, utf8);
    }
    fflush(stdout);
    return 0;
  }

  if (path == NULL) {
    fputs("flang tokens: не назван файл. Пример: flang tokens модуль.flang --json\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(full);
    return 2;
  }

  repl_cycle();
  args[0] = repl_value_text(text, bytes);
  /* Путь едет в ответ ТЕМ ЖЕ, каким его набрали: ключ `file` машинного вида
     обязан совпадать с тем, о чём спрашивали, иначе зовущий не узнает свой
     файл в ответе. */
  args[1] = repl_value_say(path);

  if (repl_call(machine ? "Токены машинно" : "Токены словами", args, 2, &view) != FL_OK) {
    code = 1;
  } else if (machine && (!val_field(view, "машинно", &field) || !val_text(field, &utf8, &bytes))) {
    fputs("flang tokens: поток токенов не напечатался\n", stderr);
    code = 1;
  } else {
    if (machine) {
      if (pretty) {
        ast_pretty(utf8, bytes);
      } else {
        fwrite(utf8, 1, bytes, stdout);
      }
      fputc('\n', stdout);
    } else if (val_field(view, "словами", &field) && field.tag == FL_LIST) {
      for (at = 0; at < field.as.list.count; at += 1) {
        if (val_text(field.as.list.items[at], &utf8, &bytes)) {
          fwrite(utf8, 1, bytes, stdout);
          fputc('\n', stdout);
        }
      }
    }
    fflush(stdout);
    if (val_field(view, "беды", &field) && field.tag == FL_LIST && field.as.list.count > 0) {
      for (at = 0; at < field.as.list.count; at += 1) {
        if (val_text(field.as.list.items[at], &utf8, &bytes)) {
          fprintf(stderr, "%.*s\n", (int)bytes, utf8);
        }
      }
      code = 1;
    }
  }

  free(text);
  free(full);
  return code;
}

/**
 * `flang ast <файл> [--pretty]` — дерево разбора в JSON, без Node.
 *
 * Дорога та же, что у `flang emit`: замыкание «использует» → «Связать
 * исходники» → печать. Разбор БЕЗ связывания сюда не годится, и это уже
 * стоило один раз: команда, печатающая дерево одного файла, на ядре,
 * разложенном по модулям, отдаёт дерево, в котором нет половины функций, —
 * и человек, скормивший его дальше, узнаёт об этом от компилятора C.
 *
 * Проверок типов и завершаемости здесь нет, и это не недоделка, а тот же
 * договор, что у свидетеля: `ast` показывает ПРОЧИТАННОЕ. Отказ бывает ровно
 * там, где дерева не выходит вовсе, — на разборе и на связывании, код 1.
 *
 * ДВЕ ОТМЕТКИ АНАЛИЗА СТАВЯТСЯ, И ПОРЯДОК МЕЖДУ НИМИ ОБЯЗАТЕЛЕН. Свидетель
 * кладёт их в `loadProgram` («Отметить меры», затем «Отметить доказанные»), и
 * без них дерево расходится с ним побайтово: на трёхстрочном модуле разница
 * вышла в один ключ `"числовая":true` и 24 байта. Отметка меры ПЕРЕСТРАИВАЕТ
 * дерево, а доказанное привязано к узлам уже перестроенного, — поменяй
 * порядок, и отметка легла бы на выброшенные узлы, молча и без единой
 * диагностики.
 */
static int ast_file(int argc, char **argv) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  fl_value args[2];
  fl_value linked = fl_nothing();
  fl_value program = fl_nothing();
  fl_value measured = fl_nothing();
  fl_value proven = fl_nothing();
  fl_value bads = fl_nothing();
  fl_value printed = fl_nothing();
  const char *path = NULL;
  bool pretty = false;
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  const char *utf8 = NULL;
  size_t bytes = 0;
  int index = 0;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--pretty") == 0) {
      pretty = true;
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang ast: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang ast: не назван файл. Пример: flang ast модуль.flang\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(full);
    return 2;
  }

  /* ЗАМОК РЯДОМ СО ВХОДОМ подменяет чтение исходников зависимостей: их может не
     быть на диске вовсе. Испорченный замок — отказ, а не откат к чтению файлов:
     откат означал бы сборку не из замка. Стоит ДО `repl_cycle`, чтобы разборы
     проверки груза не пережили её ни одним байтом арены. */
  if (!lock_beside(full)) {
    free(text);
    free(full);
    return 1;
  }

  repl_cycle();
  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, full);
  strings_add(&texts, text, bytes);
  repl_imports_of(text, bytes, full, &queue);
  args[0] = repl_closure(&paths, &texts, &queue);
  args[1] = repl_value_say(full);

  if (repl_call("Связать исходники", args, 2, &linked) != FL_OK) {
    code = 1;
  } else if (val_field(linked, "диагностики", &bads) && bads.tag == FL_LIST && bads.as.list.count > 0) {
    repl_bads list;
    size_t at = 0;
    bads_init(&list);
    for (at = 0; at < bads.as.list.count; at += 1) {
      bads_take(&list, bads.as.list.items[at]);
    }
    check_print_bads(&list, path, paths.count);
    bads_free(&list);
    code = 1;
  } else if (!val_field(linked, "программа", &program)) {
    fputs("flang ast: связывание не вернуло программы\n", stderr);
    code = 1;
  } else if (repl_call("Отметить меры", &program, 1, &measured) != FL_OK ||
             repl_call("Отметить доказанные", &measured, 1, &proven) != FL_OK) {
    fputs("flang ast: отметки анализа не легли\n", stderr);
    code = 1;
  } else if (repl_call("Печать значения", &proven, 1, &printed) != FL_OK ||
             !val_text(printed, &utf8, &bytes)) {
    fputs("flang ast: прочитанное не напечаталось\n", stderr);
    code = 1;
  } else {
    if (pretty) {
      ast_pretty(utf8, bytes);
    } else {
      fwrite(utf8, 1, bytes, stdout);
    }
    fputc('\n', stdout);
    fflush(stdout);
  }

  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  free(text);
  free(full);
  return code;
}

/* ═════════════════════ проверка суждений: `flang facts` ══════════════════ */

/*
 * ФАКТЫ ПРИЕЗЖАЮТ ПОЛНЫМ JSON, а не набором скаляров, и разбирает их отдельная
 * функция, а не `run_value`. Причина не в аккуратности: утверждение умеет
 * говорить `поле «x» факта «y»`, то есть факт бывает записью, — а разбор
 * `--args` объектов и списков не знает намеренно (см. его шапку) и знать не
 * должен: аргумент вызова у `flang run` скаляр по контракту.
 */
static bool facts_json(const char *text, size_t *at, fl_value *out);

static bool facts_json_items(const char *text, size_t *at, fl_value *out) {
  size_t count = 0;
  size_t capacity = 8;
  fl_value *items = (fl_value *)malloc(capacity * sizeof(fl_value));
  bool ok = true;
  if (items == NULL) {
    repl_oom();
  }
  *at += 1;
  run_spaces(text, at);
  if (text[*at] == ']') {
    *at += 1;
    *out = repl_value_variant_fields("Значение списка", "элементы", repl_value_list(NULL, 0));
    free(items);
    return true;
  }
  while (ok) {
    fl_value item = fl_nothing();
    if (!facts_json(text, at, &item)) {
      ok = false;
      break;
    }
    if (count == capacity) {
      capacity *= 2;
      items = (fl_value *)repl_grow(items, capacity * sizeof(fl_value));
    }
    items[count] = item;
    count += 1;
    run_spaces(text, at);
    if (text[*at] == ',') {
      *at += 1;
      continue;
    }
    if (text[*at] == ']') {
      *at += 1;
      break;
    }
    ok = false;
  }
  if (ok) {
    *out = repl_value_variant_fields("Значение списка", "элементы", repl_value_list(items, count));
  }
  free(items);
  return ok;
}

static bool facts_json_fields(const char *text, size_t *at, fl_value *out) {
  size_t count = 0;
  size_t capacity = 8;
  fl_value *fields = (fl_value *)malloc(capacity * sizeof(fl_value));
  bool ok = true;
  if (fields == NULL) {
    repl_oom();
  }
  *at += 1;
  run_spaces(text, at);
  if (text[*at] == '}') {
    *at += 1;
    *out = repl_value_variant_fields("Значение записи", "поля", repl_value_list(NULL, 0));
    free(fields);
    return true;
  }
  while (ok) {
    char *key = NULL;
    size_t bytes = 0;
    fl_value item = fl_nothing();
    run_spaces(text, at);
    if (text[*at] != '"' || !run_text(text, at, &key, &bytes)) {
      ok = false;
      break;
    }
    run_spaces(text, at);
    if (text[*at] != ':') {
      free(key);
      ok = false;
      break;
    }
    *at += 1;
    if (!facts_json(text, at, &item)) {
      free(key);
      ok = false;
      break;
    }
    {
      const char *names[2];
      fl_value values[2];
      names[0] = "ключ";
      values[0] = repl_value_text(key, bytes);
      names[1] = "значение";
      values[1] = item;
      if (count == capacity) {
        capacity *= 2;
        fields = (fl_value *)repl_grow(fields, capacity * sizeof(fl_value));
      }
      fields[count] = repl_value_record(names, values, 2);
      count += 1;
    }
    free(key);
    run_spaces(text, at);
    if (text[*at] == ',') {
      *at += 1;
      continue;
    }
    if (text[*at] == '}') {
      *at += 1;
      break;
    }
    ok = false;
  }
  if (ok) {
    *out = repl_value_variant_fields("Значение записи", "поля", repl_value_list(fields, count));
  }
  free(fields);
  return ok;
}

static bool facts_json(const char *text, size_t *at, fl_value *out) {
  run_spaces(text, at);
  if (text[*at] == '[') {
    return facts_json_items(text, at, out);
  }
  if (text[*at] == '{') {
    return facts_json_fields(text, at, out);
  }
  return run_value(text, at, out);
}

/* Утверждения приезжают JSON-массивом строк — ровно тем же ключом и в том же
   виде, что у свидетеля: `--claims '["…"]'`. */
static bool facts_claims(const char *text, repl_strings *out) {
  size_t at = 0;
  run_spaces(text, &at);
  if (text[at] != '[') {
    return false;
  }
  at += 1;
  run_spaces(text, &at);
  if (text[at] == ']') {
    return true;
  }
  for (;;) {
    char *claim = NULL;
    size_t bytes = 0;
    run_spaces(text, &at);
    if (text[at] != '"' || !run_text(text, &at, &claim, &bytes)) {
      return false;
    }
    strings_add(out, claim, bytes);
    free(claim);
    run_spaces(text, &at);
    if (text[at] == ',') {
      at += 1;
      continue;
    }
    if (text[at] == ']') {
      at += 1;
      break;
    }
    return false;
  }
  run_spaces(text, &at);
  return text[at] == '\0';
}

/*
 * `flang facts` — то, ради чего язык написан (`flang/SPEC.md`, раздел 1).
 *
 * КОД ВОЗВРАТА ЗДЕСЬ ГОВОРИТ О ВЕРДИКТЕ, А НЕ О РАБОТЕ ИНСТРУМЕНТА, и это
 * контракт свидетеля, перенесённый дословно: опровергнутое утверждение — это
 * РЕЗУЛЬТАТ, вердикт уходит в stdout, а код 1 нужен, чтобы на нём падал CI.
 * Кода 3 у этой команды нет: «сам сломался» здесь неотличимо от «не разобрал
 * вызов» и отвечает двойкой, как у всех остальных команд бинарника.
 */
static int facts_file(int argc, char **argv) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  repl_strings claims;
  fl_value args[6];
  fl_value verdict = fl_nothing();
  fl_value facts = fl_nothing();
  fl_value bads = fl_nothing();
  fl_value field = fl_nothing();
  const char *path = NULL;
  const char *claims_text = NULL;
  const char *facts_path = NULL;
  double steps = 10000;
  bool pretty = false;
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  char *facts_text = NULL;
  const char *utf8 = NULL;
  size_t bytes = 0;
  size_t at = 0;
  int index = 0;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--pretty") == 0) {
      pretty = true;
    } else if (strcmp(argv[index], "--claims") == 0 && index + 1 < argc) {
      index += 1;
      claims_text = argv[index];
    } else if (strcmp(argv[index], "--facts") == 0 && index + 1 < argc) {
      index += 1;
      facts_path = argv[index];
    } else if (strcmp(argv[index], "--steps") == 0 && index + 1 < argc) {
      index += 1;
      steps = strtod(argv[index], NULL);
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang facts: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang facts: не назван файл. Пример: flang facts модуль.flang --facts ф.json --claims '[\"…\"]'\n",
          stderr);
    return 2;
  }
  if (claims_text == NULL) {
    fputs("flang facts: требует --claims '[\"…\"]'\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(base);
    free(full);
    return 2;
  }
  if (!lock_beside(full)) {
    free(base);
    free(text);
    free(full);
    return 1;
  }
  if (facts_path != NULL) {
    char *facts_full = repl_resolve(base, facts_path);
    size_t facts_bytes = 0;
    facts_text = repl_read_file(facts_full, &facts_bytes);
    free(facts_full);
    if (facts_text == NULL) {
      fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", facts_path);
      free(base);
      free(full);
      free(text);
      return 2;
    }
  }
  free(base);

  repl_cycle();
  strings_init(&claims);
  if (!facts_claims(claims_text, &claims)) {
    fputs("flang facts: --claims должен быть JSON-массивом строк\n", stderr);
    strings_free(&claims);
    free(text);
    free(facts_text);
    free(full);
    return 2;
  }
  if (facts_text == NULL) {
    facts = repl_value_variant_fields("Значение записи", "поля", repl_value_list(NULL, 0));
  } else if (!facts_json(facts_text, &at, &facts)) {
    fprintf(stderr, "flang facts: не разобран JSON фактов (%s)\n", facts_path);
    strings_free(&claims);
    free(text);
    free(facts_text);
    free(full);
    return 2;
  }

  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, full);
  strings_add(&texts, text, bytes);
  repl_imports_of(text, bytes, full, &queue);
  args[0] = repl_closure(&paths, &texts, &queue);
  args[1] = repl_value_say(full);
  args[2] = facts;
  args[3] = repl_value_strings(&claims);
  args[4] = fl_number(steps);
  args[5] = fl_number(100);

  if (repl_call("Проверка фактов исходников", args, 6, &verdict) != FL_OK) {
    fputs("flang facts: проверка не отработала\n", stderr);
    code = 2;
  } else if (val_field(verdict, "диагностики", &bads) && bads.tag == FL_LIST && bads.as.list.count > 0) {
    repl_bads list;
    size_t item = 0;
    bads_init(&list);
    for (item = 0; item < bads.as.list.count; item += 1) {
      bads_take(&list, bads.as.list.items[item]);
    }
    check_print_bads(&list, path, paths.count);
    bads_free(&list);
    code = 2;
  } else if (!val_field(verdict, "вывод", &field) || !val_text(field, &utf8, &bytes)) {
    fputs("flang facts: вердикт не напечатался\n", stderr);
    code = 2;
  } else {
    bool ok = false;
    if (pretty) {
      ast_pretty(utf8, bytes);
    } else {
      fwrite(utf8, 1, bytes, stdout);
    }
    fputc('\n', stdout);
    fflush(stdout);
    if (val_field(verdict, "годно", &field) && field.tag == FL_FLAG) {
      ok = field.as.flag;
    }
    code = ok ? 0 : 1;
  }

  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  strings_free(&claims);
  free(text);
  free(facts_text);
  free(full);
  return code;
}

/* ═════════════════════ исполнение плана: `flang io` ══════════════════════ */

/*
 * ХОЗЯИН С ЭФФЕКТАМИ. Всё, что здесь есть, — POSIX, и потому всё это живёт в
 * этом файле, а не в переносимом `flang_cli.c`: процессы
 * (`fork`/`execvp`/`waitpid`), сокеты, часы. Программа на flang ни одного из
 * этих вызовов не делает и делать не может — она СТРОИТ ОПИСАНИЕ действия, а
 * исполняет его тот, кто снаружи.
 *
 * Правило, которому здесь подчинено всё: НЕУДАЧА — ЭТО ОТКЛИК, А НЕ ПОЛОМКА.
 * «Файла нет», «связь закрыта», «программа вернула 3» — обычные значения
 * обычной суммы, и программа разбирает их своим `разбор`ом. Поломкой остаётся
 * только то, из-за чего не наступает НИКАКОЙ отклик.
 *
 * Отсюда же различение, стоившее свидетелю отдельной прозы: «процесс вернул
 * ненулевой код» и «процесс убит сигналом» — РАЗНЫЕ отклики («Процесс
 * завершён» и «Процесс убит»), потому что слить их значило бы поручить автору
 * программы догадываться, что означает ноль.
 */

#include <fcntl.h>
#include <netdb.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

/* ═══════════ прогон примеров ПО КОРПУСУ: `flang test <каталог|маска>` ═══════ */

/*
 * ЗДЕСЬ НЕТ НИ ОДНОГО РЕШЕНИЯ, и это главное про этот кусок.
 *
 * Что считать корпусом, куда идти обходу, в какие каталоги не заходить, какие
 * пути брать, в каком порядке, какими словами отчитаться, что печатать машине и
 * с каким кодом выйти — всё это решает `flang/self/bootstrap/corpus.flang`, то
 * есть сам язык. Здесь остаются ровно те три вещи, которых в языке нет и быть не
 * может: перечислить каталог (`opendir`), прочитать файл (`fopen`) и спросить
 * часы. Всё остальное — перевозка значений туда и обратно.
 *
 * Граница названа числом в шапке `corpus.flang`, и она не оценка: снимите
 * отсюда обход и чтение — не останется ничего, что стоило бы переносить.
 *
 * ── Почему итоги копятся в C, а не списком на flang ─────────────────────────
 * Область памяти не отдаёт ничего до конца вызова (`docs/zettel/arena-never-
 * releases.md`), а один файл корпуса стоит 20—70 МиБ разбора, типов и прогона.
 * Триста файлов в одной области — это десятки гигабайт, и прогонщик умер бы на
 * первом же настоящем корпусе. Поэтому область сбрасывается на КАЖДОМ файле, а
 * итог по файлу снимается с неё простыми копиями строк и чисел; список на flang
 * собирается один раз в конце, из уже снятого.
 */

typedef struct {
  char *function;
  char *example;
  char *code;
  char *message;
} corpus_fail;

typedef struct {
  corpus_fail *items;
  size_t count;
  size_t capacity;
} corpus_fails;

typedef struct {
  char *path;
  bool taken;
  char *code;
  char *message;
  double total;
  double own;
  double passed;
  double failed;
  corpus_fails fails;
} corpus_row;

typedef struct {
  corpus_row *items;
  size_t count;
  size_t capacity;
} corpus_rows;

static void corpus_fails_init(corpus_fails *list) {
  list->items = NULL;
  list->count = 0;
  list->capacity = 0;
}

static void corpus_fails_push(corpus_fails *list, char *function, char *example, char *code, char *message) {
  corpus_fail item;
  if (list->count == list->capacity) {
    list->capacity = list->capacity == 0 ? 4 : list->capacity * 2;
    list->items = (corpus_fail *)repl_grow(list->items, list->capacity * sizeof(corpus_fail));
  }
  item.function = function;
  item.example = example;
  item.code = code;
  item.message = message;
  list->items[list->count] = item;
  list->count += 1;
}

static void corpus_fails_free(corpus_fails *list) {
  size_t index = 0;
  for (index = 0; index < list->count; index += 1) {
    free(list->items[index].function);
    free(list->items[index].example);
    free(list->items[index].code);
    free(list->items[index].message);
  }
  free(list->items);
  corpus_fails_init(list);
}

static void corpus_rows_init(corpus_rows *list) {
  list->items = NULL;
  list->count = 0;
  list->capacity = 0;
}

static corpus_row *corpus_rows_open(corpus_rows *list, const char *path) {
  corpus_row *row = NULL;
  if (list->count == list->capacity) {
    list->capacity = list->capacity == 0 ? 16 : list->capacity * 2;
    list->items = (corpus_row *)repl_grow(list->items, list->capacity * sizeof(corpus_row));
  }
  row = &list->items[list->count];
  list->count += 1;
  row->path = repl_say(path);
  row->taken = false;
  row->code = repl_say("");
  row->message = repl_say("");
  row->total = 0;
  row->own = 0;
  row->passed = 0;
  row->failed = 0;
  corpus_fails_init(&row->fails);
  return row;
}

static void corpus_rows_free(corpus_rows *list) {
  size_t index = 0;
  for (index = 0; index < list->count; index += 1) {
    free(list->items[index].path);
    free(list->items[index].code);
    free(list->items[index].message);
    corpus_fails_free(&list->items[index].fails);
  }
  free(list->items);
  corpus_rows_init(list);
}

/** Отказ по файлу: код и слова вместо цифр. Строки берутся во владение. */
static void corpus_row_refuse(corpus_row *row, const char *code, const char *message) {
  free(row->code);
  free(row->message);
  row->taken = false;
  row->code = repl_say(code);
  row->message = repl_say(message);
}

static char *corpus_join(const char *root, const char *name) {
  const size_t root_bytes = strlen(root);
  const size_t name_bytes = strlen(name);
  char *out = NULL;
  if (root_bytes == 0) {
    return repl_say(name);
  }
  out = (char *)repl_alloc(root_bytes + name_bytes + 2);
  memcpy(out, root, root_bytes);
  out[root_bytes] = '/';
  memcpy(out + root_bytes + 1, name, name_bytes);
  out[root_bytes + name_bytes + 1] = 0;
  return out;
}

/*
 * Обход каталога вглубь. Единственное место всего прогонщика, которого на flang
 * написать нельзя: в языке нет эффектов вовсе, а перечисление каталога — эффект.
 * Ни отбора, ни порядка здесь нет намеренно — и то и другое считает flang по
 * полученному списку.
 */
static void corpus_walk(const char *root, const repl_strings *skip, repl_strings *out) {
  DIR *directory = opendir(root[0] == 0 ? "." : root);
  if (directory == NULL) {
    return;
  }
  for (;;) {
    const struct dirent *entry = readdir(directory);
    char *child = NULL;
    struct stat state;
    if (entry == NULL) {
      break;
    }
    if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
      continue;
    }
    if (strings_has(skip, entry->d_name, strlen(entry->d_name))) {
      continue;
    }
    child = corpus_join(root, entry->d_name);
    /* `lstat`, а не `stat`, и это не придирка: символьная ссылка на
       родительский каталог увела бы обход в бесконечную рекурсию, а прогонщик
       корпуса ходит по ЧУЖИМ деревьям. Ссылки поэтому не берутся вовсе — ни как
       каталог, ни как файл; настоящий файл на диске лежит один раз, и брать его
       дважды под двумя именами прогонщику незачем. */
    if (lstat(child, &state) != 0) {
      free(child);
      continue;
    }
    if (S_ISDIR(state.st_mode)) {
      corpus_walk(child, skip, out);
    } else if (S_ISREG(state.st_mode)) {
      strings_say(out, child);
    }
    free(child);
  }
  closedir(directory);
}

/** Список строк с той стороны: ответ flang снимается копиями в C. */
static void corpus_take_strings(fl_value list, repl_strings *out) {
  size_t index = 0;
  if (list.tag != FL_LIST) {
    return;
  }
  for (index = 0; index < list.as.list.count; index += 1) {
    char *text = val_copy(list.as.list.items[index]);
    strings_say(out, text);
    free(text);
  }
}

/*
 * Один файл корпуса: то же самое, что делает `flang test` с одним файлом, но
 * без единой печати — всё, что нашлось, переезжает в `row`.
 *
 * Область сбрасывается ЗДЕСЬ, на входе, и потому всё, что уносится наружу,
 * скопировано (`val_copy`): к следующему файлу от этих значений не останется ни
 * байта.
 */
static void corpus_one(const char *shown, bool check, const char *steps, const char *depth, corpus_row *row) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  fl_value result = fl_nothing();
  fl_value args[5];
  fl_value field = fl_nothing();
  fl_value rows = fl_nothing();
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  size_t bytes = 0;
  size_t index = 0;

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, shown);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    corpus_row_refuse(row, "FLANG_CLI", "файл не прочитан");
    free(full);
    return;
  }

  /* Замок рядом со входом — тот же порядок, что у прогона одного файла: он
     подменяет чтение исходников зависимостей, и стоять обязан ДО сброса
     области. */
  repl_call_quiet = true;
  if (!lock_beside(full)) {
    repl_call_quiet = false;
    corpus_row_refuse(row, "FLANG_LOCK", "замок рядом со входом не принят");
    free(text);
    free(full);
    return;
  }

  repl_cycle();

  /* СВОИ примеры считаются ПЕРВЫМИ и по одному файлу, без замыкания.
     Иначе отчёт врёт: `flang test` гоняет примеры всей связанной программы, и
     слой без единого своего примера отчитывается чужими — `carriers.flang`
     печатает «примеров 91, прошло 91», а все девяносто одна приехали из
     `totality.flang`. Считает это «Своих примеров в исходнике» на flang; здесь
     только вопрос и ответ числом. */
  {
    fl_value alone = repl_value_text(text, bytes);
    fl_value own = fl_nothing();
    if (repl_call("Своих примеров в исходнике", &alone, 1, &own) == FL_OK && own.tag == FL_NUMBER) {
      row->own = own.as.number;
    }
  }

  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, full);
  strings_add(&texts, text, bytes);
  repl_imports_of(text, bytes, full, &queue);
  args[0] = repl_closure(&paths, &texts, &queue);
  args[1] = repl_value_say(full);
  args[2] = fl_flag(check);
  args[3] = fl_number(strtod(steps, NULL));
  args[4] = fl_number(strtod(depth, NULL));

  if (repl_call("Прогон примеров исходников", args, 5, &result) != FL_OK) {
    corpus_row_refuse(row, repl_call_code, repl_call_message);
  } else if (val_field(result, "диагностики", &rows) && rows.tag == FL_LIST && rows.as.list.count > 0) {
    /* Программа не прошла проверку: примеры не запускались вовсе. Наружу едет
       ПЕРВОЕ замечание — остальные человек увидит, позвав `flang check` на этот
       файл; выкладывать в свод корпуса все замечания всех файлов значило бы
       топить отчёт в том, ради чего у `check` есть свой вывод. */
    fl_value bad = rows.as.list.items[0];
    fl_value code = fl_nothing();
    fl_value message = fl_nothing();
    char *code_text = NULL;
    char *say_text = NULL;
    val_field(bad, "код", &code);
    val_field(bad, "сообщение", &message);
    code_text = val_copy(code);
    say_text = val_copy(message);
    corpus_row_refuse(row, code_text, say_text);
    free(code_text);
    free(say_text);
  } else {
    row->taken = true;
    if (val_field(result, "всего", &field) && field.tag == FL_NUMBER) {
      row->total = field.as.number;
    }
    if (val_field(result, "прошло", &field) && field.tag == FL_NUMBER) {
      row->passed = field.as.number;
    }
    if (val_field(result, "сорвалось", &field) && field.tag == FL_NUMBER) {
      row->failed = field.as.number;
    }
    if (val_field(result, "строки", &rows) && rows.tag == FL_LIST) {
      for (index = 0; index < rows.as.list.count; index += 1) {
        fl_value line = rows.as.list.items[index];
        fl_value hold = fl_nothing();
        char *function = NULL;
        char *example = NULL;
        char *code = NULL;
        char *message = NULL;
        if (val_field(line, "прошёл", &hold) && hold.tag == FL_FLAG && hold.as.flag) {
          continue;
        }
        function = val_field(line, "функция", &hold) ? val_copy(hold) : repl_say("");
        example = val_field(line, "пример", &hold) ? val_copy(hold) : repl_say("");
        code = val_field(line, "код", &hold) ? val_copy(hold) : repl_say("");
        message = val_field(line, "сообщение", &hold) ? val_copy(hold) : repl_say("");
        corpus_fails_push(&row->fails, function, example, code, message);
      }
    }
  }
  repl_call_quiet = false;

  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  free(text);
  free(full);
}

static fl_value corpus_fail_value(const corpus_fail *item) {
  static const char *const names[4] = {"функция", "пример", "код", "сообщение"};
  fl_value values[4];
  values[0] = repl_value_say(item->function);
  values[1] = repl_value_say(item->example);
  values[2] = repl_value_say(item->code);
  values[3] = repl_value_say(item->message);
  return repl_value_record(names, values, 4);
}

static fl_value corpus_row_value(const corpus_row *row) {
  static const char *const names[9] = {"путь",  "взят",  "код",    "сообщение", "всего",
                                       "своих", "прошло", "сорвалось", "сорванные"};
  fl_value values[9];
  fl_value *items = NULL;
  fl_error error;
  size_t index = 0;
  error.code = NULL;
  error.message = NULL;
  if (fl_list_alloc(&repl_ctx, row->fails.count, &items, &error) != FL_OK) {
    repl_oom();
  }
  for (index = 0; index < row->fails.count; index += 1) {
    items[index] = corpus_fail_value(&row->fails.items[index]);
  }
  values[0] = repl_value_say(row->path);
  values[1] = fl_flag(row->taken);
  values[2] = repl_value_say(row->code);
  values[3] = repl_value_say(row->message);
  values[4] = fl_number(row->total);
  values[5] = fl_number(row->own);
  values[6] = fl_number(row->passed);
  values[7] = fl_number(row->failed);
  values[8] = fl_list(items, row->fails.count);
  return repl_value_record(names, values, 9);
}

/** Настенное время прогона в миллисекундах: часы — тоже эффект. */
static double corpus_now(void) {
  struct timeval now;
  if (gettimeofday(&now, NULL) != 0) {
    return 0;
  }
  return (double)now.tv_sec * 1000.0 + (double)now.tv_usec / 1000.0;
}

/*
 * `flang test <каталог|маска>` целиком.
 *
 * `many` равное `нет` — это один названный файл, попросивший машиночитаемый
 * вывод: обхода тогда нет, а свод и его форма те же самые. Второго формата для
 * одного файла не заводится намеренно — тот, кто разбирает вывод прогонщика,
 * обязан разбирать одну форму, а не две.
 */
static int test_corpus(const char *given, bool check, const char *steps, const char *depth, bool json,
                       bool ledger, bool many) {
  repl_strings skip;
  repl_strings found;
  repl_strings chosen;
  corpus_rows rows;
  fl_value result = fl_nothing();
  fl_value args[3];
  fl_value field = fl_nothing();
  fl_value *items = NULL;
  fl_error error;
  double started = 0;
  size_t index = 0;
  int code = 0;
  char *root = NULL;

  strings_init(&skip);
  strings_init(&found);
  strings_init(&chosen);
  corpus_rows_init(&rows);
  error.code = NULL;
  error.message = NULL;

  /* Куда идти обходу и куда не заходить — спрашивается у flang, а не решается
     здесь. Ответ снимается копиями: следующий сброс области его сотрёт. */
  repl_cycle();
  {
    fl_value arg = repl_value_say(given);
    fl_value answer = fl_nothing();
    if (repl_call("Корень обхода", &arg, 1, &answer) != FL_OK) {
      strings_free(&skip);
      return 1;
    }
    root = val_copy(answer);
    if (repl_call("Каталоги мимо корпуса", NULL, 0, &answer) != FL_OK) {
      free(root);
      strings_free(&skip);
      return 1;
    }
    corpus_take_strings(answer, &skip);
  }

  started = corpus_now();
  if (!many) {
    /* Один названный файл: обходить нечего, отбирать нечего. */
    strings_say(&chosen, given);
    free(root);
  } else {
    corpus_walk(root, &skip, &found);
    free(root);

    /* Отбор и порядок — тоже там. Сюда возвращается готовый список путей. */
    repl_cycle();
    {
      fl_value answer = fl_nothing();
      fl_value pair[2];
      if (fl_list_alloc(&repl_ctx, found.count, &items, &error) != FL_OK) {
        repl_oom();
      }
      for (index = 0; index < found.count; index += 1) {
        items[index] = repl_value_say(found.items[index]);
      }
      pair[0] = fl_list(items, found.count);
      pair[1] = repl_value_say(given);
      if (repl_call("Отбор корпуса", pair, 2, &answer) != FL_OK) {
        strings_free(&skip);
        strings_free(&found);
        strings_free(&chosen);
        return 1;
      }
      corpus_take_strings(answer, &chosen);
    }
  }

  if (chosen.count == 0) {
    fprintf(stderr, "flang test: под «%s» не нашлось ни одного .flang\n", given);
    strings_free(&skip);
    strings_free(&found);
    strings_free(&chosen);
    return 2;
  }

  for (index = 0; index < chosen.count; index += 1) {
    corpus_row *row = corpus_rows_open(&rows, chosen.items[index]);
    corpus_one(chosen.items[index], check, steps, depth, row);
  }

  /* Свод — целиком на flang: слова, машиночитаемый вид и код возврата. */
  repl_cycle();
  if (fl_list_alloc(&repl_ctx, rows.count, &items, &error) != FL_OK) {
    repl_oom();
  }
  for (index = 0; index < rows.count; index += 1) {
    items[index] = corpus_row_value(&rows.items[index]);
  }
  args[0] = repl_value_say(given);
  args[1] = fl_list(items, rows.count);
  args[2] = fl_number((double)(long)(corpus_now() - started));
  if (repl_call("Свести корпус", args, 3, &result) != FL_OK) {
    code = 1;
  } else {
    const char *utf8 = NULL;
    size_t bytes = 0;
    if (ledger) {
      /* Ведомость по строке на файл: её записывают и сверяют диффом. Ни
         замечаний, ни итога — они бы поехали в тот же поток и попали в дифф. */
      if (val_field(result, "ведомостью", &field) && val_text(field, &utf8, &bytes) && bytes > 0) {
        fwrite(utf8, 1, bytes, stdout);
        fputc('\n', stdout);
      }
    } else if (json) {
      if (val_field(result, "в JSON", &field) && val_text(field, &utf8, &bytes)) {
        fwrite(utf8, 1, bytes, stdout);
        fputc('\n', stdout);
      }
    } else {
      if (val_field(result, "замечания", &field) && val_text(field, &utf8, &bytes) && bytes > 0) {
        fwrite(utf8, 1, bytes, stderr);
        fputc('\n', stderr);
      }
      if (val_field(result, "итог", &field) && val_text(field, &utf8, &bytes)) {
        fwrite(utf8, 1, bytes, stdout);
        fputc('\n', stdout);
      }
    }
    fflush(stderr);
    fflush(stdout);
    if (val_field(result, "код", &field) && field.tag == FL_NUMBER) {
      code = (int)field.as.number;
    }
  }

  strings_free(&skip);
  strings_free(&found);
  strings_free(&chosen);
  corpus_rows_free(&rows);
  return code;
}

#define IO_MAX_PORTS 8
#define IO_MAX_LINKS 64
#define IO_OUT_LIMIT (1 << 20)

typedef struct {
  int port;
  int fd;
} io_listen;

typedef struct {
  int number;
  int fd;
  /* Соединение открыла ПРОГРАММА («Открыть соединение»), а не приняли мы. Читает
     это поле только запись: закрывает соединение тот, кто его завёл, и потому
     ответ в принятое кладёт трубку, а ответ в открытое — нет. */
  bool outgoing;
} io_link;

typedef struct {
  bool read_files;
  bool write_files;
  bool net;
  bool clock;
  bool random;
  bool spawn;
  bool in_dir;
  bool seeded;
  unsigned long seed_state;
  long timeout_ms;
  char *root;
  io_listen listens[IO_MAX_PORTS];
  size_t listen_count;
  io_link links[IO_MAX_LINKS];
  size_t link_count;
  int next_link;
} io_host;

/* ── сборка значений «Значение» ──────────────────────────────────────────── */

static fl_value io_text(const char *utf8, size_t bytes) {
  return run_scalar("Скаляр строка", "значение", repl_value_text(utf8, bytes));
}

static fl_value io_say(const char *text) { return io_text(text, strlen(text)); }

static fl_value io_number(double number) {
  return run_scalar("Скаляр число", "значение", fl_number(number));
}


static fl_value io_pair(const char *key, fl_value value) {
  const char *names[2];
  fl_value values[2];
  names[0] = "ключ";
  values[0] = repl_value_say(key);
  names[1] = "значение";
  values[1] = value;
  return repl_value_record(names, values, 2);
}

static fl_value io_record(const fl_value *pairs, size_t count) {
  return repl_value_variant_fields("Значение записи", "поля", repl_value_list(pairs, count));
}

static fl_value io_list(const fl_value *items, size_t count) {
  return repl_value_variant_fields("Значение списка", "элементы", repl_value_list(items, count));
}

/*
 * Вариант языка в JSON-значении — запись с ключами `variant` и `fields`. Форма
 * та же, в какой его отдаёт свидетель (`JSON.stringify` значения рантайма) и в
 * какой его читает «Овеществить» вычислителя на flang. Одна форма на всех:
 * второй способ записать вариант был бы вторым способом разойтись.
 */
static fl_value io_variant(const char *name, const fl_value *fields, size_t count) {
  fl_value pairs[2];
  pairs[0] = io_pair("variant", io_say(name));
  pairs[1] = io_pair("fields", io_record(fields, count));
  return io_record(pairs, 2);
}

static fl_value io_fail(const char *code, const char *message) {
  fl_value fields[2];
  fields[0] = io_pair("код", io_say(code));
  fields[1] = io_pair("сообщение", io_say(message));
  return io_variant("Сбой", fields, 2);
}

static fl_value io_fail_errno(const char *code, const char *what) {
  char buffer[512];
  snprintf(buffer, sizeof(buffer), "%s: %s", what, strerror(errno));
  return io_fail(code, buffer);
}

/* Кодовые точки, а не байты: «сколько» обязано совпасть с «длина» языка на
   том же тексте (SPEC, раздел 5). Продолжающие байты UTF-8 (10xxxxxx) не
   считаются. */
static size_t io_points(const char *utf8, size_t bytes) {
  size_t index = 0;
  size_t points = 0;
  for (index = 0; index < bytes; index += 1) {
    if ((utf8[index] & 0xC0) != 0x80) {
      points += 1;
    }
  }
  return points;
}

/*
 * ── ГДЕ ФАЙЛ ПЕРЕСТАЁТ БЫТЬ ТЕКСТОМ ────────────────────────────────────────
 *
 * «Прочитать файл» и «Записать файл» объявлены со `строка`, а строка в этом
 * языке — UTF-8 (SPEC, раздел 5). До 22 августа 2026 хозяин этого не проверял,
 * и двоичный файл проходил сквозь текстовую пару МОЛЧА: чтение отдавало сырые
 * октеты строкой, `длина` считала их кодовыми точками (13 886 504 октета
 * назывались 11 776 136 знаками), а запись рвала содержимое `strlen`ом на
 * первом нулевом октете — 4096 октетов на входе, 7 байт на выходе, и ни одного
 * замечания. Отказ лучше испорченного файла, поэтому теперь спрашивается прямо.
 *
 * Бед было ДВЕ, и лекарства у них разные. `strlen` снят длиной у значения —
 * молча рвать нечем, и нулевой октет стал законным содержимым (он и был им:
 * U+0000 — обычная точка, а `flang/self/link.flang` разделяет им имена).
 * Остаётся ложь о числе знаков на неправильном UTF-8, и на неё — отказ.
 *
 * Спрашивает хозяин у рантайма (`fl_utf8_not_text_at`), а не у себя: тот же
 * вопрос задаёт планировщик конкурентности, и два ответа на один вопрос были бы
 * вторым способом хозяевам разойтись. Двоичному — октетная пара, она ниже.
 */
/* Отказ «это не текст», названный одинаково у чтения и у записи: номер октета,
   его значение и имя поручения, которым это содержимое возится без потерь. */
static fl_value io_not_text(const char *what, const char *utf8, size_t bytes, size_t at, const char *instead) {
  char buffer[512];
  snprintf(buffer, sizeof(buffer), "%s не текст: октет %lu из %lu (0x%02X) не складывается в UTF-8; октеты возит «%s»",
           what, (unsigned long)at, (unsigned long)bytes, (unsigned)(unsigned char)utf8[at - 1], instead);
  return io_fail("FLANG_IO_NOT_TEXT", buffer);
}

/* ── чтение поручения ────────────────────────────────────────────────────── */

static bool io_order_name(fl_value order, const char **utf8, size_t *bytes) {
  fl_value name = fl_nothing();
  return zn_field(order, "variant", &name) && zn_text(name, utf8, bytes);
}

static bool io_order_is(fl_value order, const char *name) {
  const char *utf8 = NULL;
  size_t bytes = 0;
  return io_order_name(order, &utf8, &bytes) && bytes == strlen(name) && memcmp(utf8, name, bytes) == 0;
}

static bool io_order_field(fl_value order, const char *key, fl_value *out) {
  fl_value fields = fl_nothing();
  return zn_field(order, "fields", &fields) && zn_field(fields, key, out);
}

static char *io_order_text(fl_value order, const char *key) {
  fl_value field = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  if (!io_order_field(order, key, &field) || !zn_text(field, &utf8, &bytes)) {
    return NULL;
  }
  return repl_dup(utf8, bytes);
}

static bool io_order_number(fl_value order, const char *key, double *out) {
  fl_value field = fl_nothing();
  return io_order_field(order, key, &field) && zn_number(field, out);
}

/* ── путь под правилом «внутри каталога» ─────────────────────────────────── */

static char *io_path(io_host *host, const char *given, fl_value *bad, bool *ok) {
  char *full = NULL;
  *ok = true;
  if (given == NULL || given[0] == '\0') {
    *bad = io_fail("FLANG_IO_PATH", "поручению нужен непустой путь");
    *ok = false;
    return NULL;
  }
  full = repl_resolve(host->root, given);
  if (host->in_dir) {
    const size_t root = strlen(host->root);
    if (strncmp(full, host->root, root) != 0 || (full[root] != '/' && full[root] != '\0')) {
      char buffer[1024];
      snprintf(buffer, sizeof(buffer), "путь «%s» ведёт за пределы каталога работы", given);
      *bad = io_fail("FLANG_IO_DENIED", buffer);
      *ok = false;
      free(full);
      return NULL;
    }
  }
  return full;
}

/* ── случайность с семенем ───────────────────────────────────────────────── */

/*
 * mulberry32 — тот же генератор, что у планировщика конкурентности
 * (`makeRandom` в `flang/src/conc.mjs`), и повторён он здесь ЦЕЛОЧИСЛЕННОЙ
 * арифметикой на 32 битах, а не приблизительно. Прогон с семенем обязан дать
 * ту же последовательность у всех восьми целей печати — иначе «повторимо»
 * означало бы «повторимо в Node».
 */
static double io_random(io_host *host) {
  unsigned long state = 0;
  unsigned long t = 0;
  if (!host->seeded) {
    return (double)rand() / ((double)RAND_MAX + 1.0);
  }
  host->seed_state = (host->seed_state + 0x6d2b79f5UL) & 0xffffffffUL;
  state = host->seed_state;
  t = state;
  t = ((t ^ (t >> 15)) * (t | 1UL)) & 0xffffffffUL;
  t ^= (t + (((t ^ (t >> 7)) * (t | 61UL)) & 0xffffffffUL)) & 0xffffffffUL;
  t &= 0xffffffffUL;
  return (double)((t ^ (t >> 14)) & 0xffffffffUL) / 4294967296.0;
}

/* ── связи ───────────────────────────────────────────────────────────────── */

static int io_listen_on(io_host *host, int port, char *why, size_t why_size) {
  size_t index = 0;
  int fd = -1;
  int yes = 1;
  struct sockaddr_in address;
  for (index = 0; index < host->listen_count; index += 1) {
    if (host->listens[index].port == port) {
      return host->listens[index].fd;
    }
  }
  if (host->listen_count == IO_MAX_PORTS) {
    snprintf(why, why_size, "хозяин слушает уже %d портов — больше некуда", IO_MAX_PORTS);
    return -1;
  }
  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0) {
    snprintf(why, why_size, "сокет не заведён: %s", strerror(errno));
    return -1;
  }
  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
  memset(&address, 0, sizeof(address));
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_ANY);
  address.sin_port = htons((unsigned short)port);
  if (bind(fd, (struct sockaddr *)&address, sizeof(address)) != 0 || listen(fd, 16) != 0) {
    snprintf(why, why_size, "порт %d не занят хозяином: %s", port, strerror(errno));
    close(fd);
    return -1;
  }
  host->listens[host->listen_count].port = port;
  host->listens[host->listen_count].fd = fd;
  host->listen_count += 1;
  return fd;
}

/*
 * Пойти НАРУЖУ. Это вторая половина сети, и без неё на языке нельзя было
 * написать клиента ни к одной службе с двоичным протоколом: `«Запросить»` умеет
 * только HTTP, а `«Принять соединение»` ждёт, пока придут к нам.
 *
 * `getaddrinfo`, а не `inet_addr`: имя узла разрешать всё равно надо, а второй
 * способ не умеет ни имён, ни IPv6. Первый годный адрес и берётся — перебирать
 * все и выбирать «лучший» здесь некому и незачем.
 */
static int io_connect_to(io_host *host, const char *address, int port, char *why, size_t why_size) {
  struct addrinfo hints;
  struct addrinfo *found = NULL;
  struct addrinfo *step = NULL;
  char service[8];
  int fd = -1;
  int failed = 0;
  (void)host;
  snprintf(service, sizeof(service), "%d", port);
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  failed = getaddrinfo(address, service, &hints, &found);
  if (failed != 0) {
    snprintf(why, why_size, "адрес «%s» не разрешён: %s", address, gai_strerror(failed));
    return -1;
  }
  for (step = found; step != NULL; step = step->ai_next) {
    fd = socket(step->ai_family, step->ai_socktype, step->ai_protocol);
    if (fd < 0) {
      continue;
    }
    if (connect(fd, step->ai_addr, step->ai_addrlen) == 0) {
      freeaddrinfo(found);
      return fd;
    }
    close(fd);
    fd = -1;
  }
  snprintf(why, why_size, "соединение с %s:%d не установлено: %s", address, port, strerror(errno));
  freeaddrinfo(found);
  return -1;
}

static int io_link_fd(io_host *host, int number) {
  size_t index = 0;
  for (index = 0; index < host->link_count; index += 1) {
    if (host->links[index].number == number) {
      return host->links[index].fd;
    }
  }
  return -1;
}

/* Открыла ли соединение сама программа. Неизвестное соединение — «нет»: до
   этого вопроса дело доходит только после того, как `io_link_fd` его нашёл. */
static bool io_link_outgoing(io_host *host, int number) {
  size_t index = 0;
  for (index = 0; index < host->link_count; index += 1) {
    if (host->links[index].number == number) {
      return host->links[index].outgoing;
    }
  }
  return false;
}

static void io_link_drop(io_host *host, int number) {
  size_t index = 0;
  for (index = 0; index < host->link_count; index += 1) {
    if (host->links[index].number == number) {
      host->links[index] = host->links[host->link_count - 1];
      host->link_count -= 1;
      return;
    }
  }
}

static void io_close(io_host *host) {
  size_t index = 0;
  for (index = 0; index < host->link_count; index += 1) {
    close(host->links[index].fd);
  }
  host->link_count = 0;
  for (index = 0; index < host->listen_count; index += 1) {
    close(host->listens[index].fd);
  }
  host->listen_count = 0;
}

/* ── запуск процесса ─────────────────────────────────────────────────────── */

/*
 * Три исхода, и все три названы отдельно, потому что смешать их значит соврать:
 *
 *   не запустилось вовсе  → «Сбой» FLANG_IO_SPAWN (процесса не было);
 *   кончилось само        → «Процесс завершён» с КОДОМ, каким бы он ни был;
 *   кончилось не само     → «Процесс убит» с именем сигнала.
 *
 * Ненулевой код возврата — РЕЗУЛЬТАТ работы, а не сбой: ради него поручение и
 * заведено. Слить «убит» с «вернул 0» нельзя ни в какую сторону, поэтому
 * `WIFSIGNALED` спрашивается раньше `WEXITSTATUS`.
 */
static fl_value io_spawn(io_host *host, const char *program, char *const *argv) {
  int out_pipe[2];
  int err_pipe[2];
  pid_t child = 0;
  repl_buf out;
  repl_buf err;
  int status = 0;
  bool too_much = false;
  if (pipe(out_pipe) != 0) {
    return io_fail_errno("FLANG_IO_SPAWN", "труба вывода не заведена");
  }
  if (pipe(err_pipe) != 0) {
    close(out_pipe[0]);
    close(out_pipe[1]);
    return io_fail_errno("FLANG_IO_SPAWN", "труба ошибок не заведена");
  }
  child = fork();
  if (child < 0) {
    close(out_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[0]);
    close(err_pipe[1]);
    return io_fail_errno("FLANG_IO_SPAWN", "процесс не порождён");
  }
  if (child == 0) {
    /* Дитя: трубы на место, каталог работы — корень хозяина, и execvp. Промах
       execvp сообщается кодом 127 — тем же, каким о нём говорит оболочка. */
    dup2(out_pipe[1], 1);
    dup2(err_pipe[1], 2);
    close(out_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[0]);
    close(err_pipe[1]);
    if (chdir(host->root) != 0) {
      _exit(127);
    }
    execvp(program, argv);
    _exit(127);
  }
  close(out_pipe[1]);
  close(err_pipe[1]);
  buf_init(&out);
  buf_init(&err);
  {
    /* Читаются ОБЕ трубы до конца, и читаются вперемешку: закрыть глаза на одну
       значит поймать взаимную блокировку на программе, которая пишет в обе. */
    int fds[2];
    bool alive[2];
    char chunk[4096];
    fds[0] = out_pipe[0];
    fds[1] = err_pipe[0];
    alive[0] = true;
    alive[1] = true;
    while (alive[0] || alive[1]) {
      fd_set set;
      int top = -1;
      int index = 0;
      struct timeval wait;
      FD_ZERO(&set);
      for (index = 0; index < 2; index += 1) {
        if (alive[index]) {
          FD_SET(fds[index], &set);
          if (fds[index] > top) top = fds[index];
        }
      }
      wait.tv_sec = host->timeout_ms / 1000;
      wait.tv_usec = (host->timeout_ms % 1000) * 1000;
      if (select(top + 1, &set, NULL, NULL, &wait) <= 0) {
        kill(child, SIGKILL);
        break;
      }
      for (index = 0; index < 2; index += 1) {
        if (alive[index] && FD_ISSET(fds[index], &set)) {
          const ssize_t got = read(fds[index], chunk, sizeof(chunk));
          if (got <= 0) {
            alive[index] = false;
          } else {
            buf_add(index == 0 ? &out : &err, chunk, (size_t)got);
            if (out.used + err.used > IO_OUT_LIMIT) {
              too_much = true;
              kill(child, SIGKILL);
              alive[0] = false;
              alive[1] = false;
            }
          }
        }
      }
    }
  }
  close(out_pipe[0]);
  close(err_pipe[0]);
  while (waitpid(child, &status, 0) < 0 && errno == EINTR) {
    /* повтор */
  }
  if (too_much) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "программа «%s» напечатала больше %d байт", program, IO_OUT_LIMIT);
    buf_free(&out);
    buf_free(&err);
    return io_fail("FLANG_IO_SPAWN", buffer);
  }
  {
    fl_value fields[3];
    fl_value answer = fl_nothing();
    fields[1] = io_pair("вывод", io_text(out.data == NULL ? "" : out.data, out.used));
    fields[2] = io_pair("ошибки", io_text(err.data == NULL ? "" : err.data, err.used));
    if (WIFSIGNALED(status)) {
      char name[64];
      snprintf(name, sizeof(name), "SIG%d", WTERMSIG(status));
      fields[0] = io_pair("сигнал", io_say(name));
      answer = io_variant("Процесс убит", fields, 3);
    } else {
      fields[0] = io_pair("код", io_number((double)WEXITSTATUS(status)));
      answer = io_variant("Процесс завершён", fields, 3);
    }
    buf_free(&out);
    buf_free(&err);
    return answer;
  }
}

/* ── сеть: разбор ответа HTTP, общий для обоих путей ─────────────────────── */

/*
 * Код ответа — три цифры после «HTTP/1.x »; тело — после пустой строки. Разбор
 * заголовков дальше этого не идёт: отклик «Ответ сети» несёт ровно код и тело,
 * и городить их читателя незачем.
 *
 * Вынесено отдельно затем, что путей теперь ДВА — свой сокет и внешний хозяин
 * для «https», — а отклик у поручения «Запросить» обязан быть один и тот же.
 * Две копии этого разбора разошлись бы молча.
 */
static fl_value io_http_answer(const repl_buf *answer) {
  int code = 0;
  const char *split = NULL;
  if (answer->used < 12 || strncmp(answer->data, "HTTP/1.", 7) != 0) {
    return io_fail("FLANG_IO_NET", "ответ не похож на HTTP");
  }
  code = atoi(answer->data + 9);
  split = strstr(answer->data, "\r\n\r\n");
  {
    fl_value fields[2];
    const char *start = split == NULL ? answer->data + answer->used : split + 4;
    fields[0] = io_pair("код", io_number((double)code));
    fields[1] = io_pair("тело", io_text(start, (size_t)(answer->data + answer->used - start)));
    return io_variant("Ответ сети", fields, 2);
  }
}

/* ── сеть: «https» исполняется НЕ ЗДЕСЬ ──────────────────────────────────── */

/*
 * ОТКУДА БЕРЁТСЯ ШИФРОВАНИЕ. Не отсюда. Криптографии в этом файле не прибавилось
 * ни байта, и `bootstrap/Makefile` по-прежнему линкует `-lm -lpthread` и ничего
 * сверх: точка раскрутки как собиралась одним `cc`, так и собирается. Три пути
 * взвешены числом в `docs/adr/0007-encryption-by-request-to-an-external-host.md`,
 * и выбран третий — ТОТ ЖЕ, каким в словаре живут процессы: поручение уходит
 * НАРУЖУ, чужая проверенная программа его исполняет, мы разбираем ответ.
 *
 * ЧЕМ ИСПОЛНЯЕТСЯ: `curl`, найденный по PATH. Имя зашито и ключи зашиты, и
 * переменной среды, которая бы их подменила, здесь нет НАМЕРЕННО: «чем ходить в
 * сеть», названное снаружи, есть тихий способ снять проверку сертификата.
 *
 * КЛЮЧИ, И ПОЧЕМУ КАЖДЫЙ:
 *   -q                    НЕ читать ~/.curlrc. Стоит первым, до всего: строка
 *                         `insecure` в чужом файле настроек сняла бы проверку
 *                         сертификата, и НИ ОДИН прогон этого бы не показал.
 *                         Главный ключ здесь — этот, а не те, что про TLS.
 *   -sS                   без счётчика, но с текстом ошибки на stderr.
 *   -i                    заголовки в поток: ответ разбирает тот же
 *                         `io_http_answer`, что и незашифрованный путь.
 *   -g                    НЕ считать «[», «]», «{», «}» в адресе перечислением:
 *                         адрес приходит из программы, а не из руки человека, и
 *                         `?ids[]=1` не должен превращаться в другой запрос.
 *   --http1.1             разбор ждёт «HTTP/1.», а поверх TLS curl по умолчанию
 *                         договаривается на HTTP/2 и печатает «HTTP/2 200».
 *   -H "Content-Type:"    СНЯТЬ заголовок, который curl дописывает к телу сам
 *                         («application/x-www-form-urlencoded»). Поручение
 *                         «Запросить» заголовков не возит вовсе, и наш сокет по
 *                         «http» не шлёт ни одного: чужая служба обязана видеть
 *                         одно и то же тело обоими путями. Замерено на
 *                         postman-echo: без этого ключа тело приезжало полем
 *                         формы, а не телом.
 *   --proto =https        только https: ни file, ни gopher, ни подмены схемы.
 *   --proto-redir =https  перенаправления и так не исполняются, но если завтра
 *                         их включат — вниз по схеме уйти будет нельзя.
 *   --tlsv1.2             нижняя граница версии.
 *   --max-time            из `--timeout` хозяина, секундами.
 *   --                    конец ключей: адрес не станет ключом, начнись он с «-».
 *
 * ЧЕГО ЗДЕСЬ НЕТ И НЕ БУДЕТ: ключа `-k` (`--insecure`), ключа
 * `--proxy-insecure`, `--cacert` из среды — ни одного способа сказать
 * «сертификат не проверять». Тихо принять чужой сертификат ХУЖЕ, чем не уметь
 * вовсе, и потому проверка не выключается ничем, что скажет программа на flang.
 *
 * КТО ПРОВЕРЯЕТ СЕРТИФИКАТ: curl своим хранилищем корней. Срок, цепочка и имя
 * узла — его работа, не наша, и отказ приезжает ЕГО словами (первая строка
 * stderr) под нашим кодом. Проверено подделкой: expired, wrong.host,
 * self-signed и untrusted-root с badssl.com отвергнуты все четыре.
 *
 * ★ ЧЕГО ПРОВЕРКА НЕ ДЕЛАЕТ, И ЭТО НАЗВАНО, А НЕ УМОЛЧАНО: ОТЗЫВ СЕРТИФИКАТА НЕ
 * ПРОВЕРЯЕТСЯ. Пятая подделка, `revoked.badssl.com`, прошла с кодом 200 —
 * отозванный лист принят. Ни OCSP, ни CRL curl с OpenSSL по умолчанию не
 * спрашивает. Ключ `--cert-status` (OCSP-скрепка) ЗАМЕРЕН и НЕ ВЗЯТ: с ним
 * отказ «No OCSP response received» приезжает не только от revoked.badssl.com,
 * но и от rosettacode.org, и от api.github.com — скрепку не отдаёт почти никто,
 * то есть ключ закрывает не дыру, а весь выход в сеть. Отзыв остаётся ДОЛГОМ, и
 * долг записан здесь, в `--help` команды `io` и в ADR-0007.
 *
 * ЧТО ЧЕСТНО НАЗВАТЬ ДОЛГОМ ЭТОГО ПУТИ:
 *   • «https» требует ЗАПУСКА ПРОЦЕССА, значит `--no-spawn` его запрещает — и
 *     запрещает громко: молча завести дитя у хозяина, которому это запрещено,
 *     значит соврать в ключе;
 *   • тело не совпадает побайтово с незашифрованным путём: curl снимает кусочную
 *     упаковку (`Transfer-Encoding: chunked`), а наш сокет отдаёт её как есть;
 *   • сырого TLS-сокета по-прежнему нет: «Открыть соединение» — голый TCP, и
 *     клиент к базе, требующей шифрования, этим не пишется;
 *   • curl обязан быть на машине. Нет его — прежний отказ FLANG_IO_NO_TLS, но с
 *     названной причиной.
 */
#define IO_TLS_PROGRAM "curl"

/* Первая строка чужого вывода: ровно она и есть «внятные слова» отказа, всё
   остальное у curl — присказка про то, куда сходить почитать.
   Обрез по длине мог прийтись на середину знака: имя узла приезжает из
   программы на flang и бывает не в латинице, а половина знака сломала бы UTF-8
   в отклике. Снимается ТОЛЬКО НЕПОЛНАЯ последовательность — ищется последний
   ведущий байт, и обещанная им длина сверяется с тем, сколько байт дошло.
   Первая редакция снимала хвост БЕЗУСЛОВНО и тем съедала последний знак у
   всякой строки, кончавшейся не латиницей. */
static void io_first_line(const char *text, size_t bytes, char *out, size_t out_size) {
  size_t index = 0;
  size_t taken = 0;
  if (out_size == 0) return;
  if (text != NULL) {
    while (index < bytes && text[index] != '\n' && text[index] != '\r' && taken + 1 < out_size) {
      out[taken] = text[index];
      taken += 1;
      index += 1;
    }
    {
      size_t lead = taken;
      while (lead > 0 && ((unsigned char)out[lead - 1] & 0xC0) == 0x80) {
        lead -= 1;
      }
      if (lead > 0) {
        const unsigned char first = (unsigned char)out[lead - 1];
        size_t need = 1;
        if ((first & 0xF8) == 0xF0) {
          need = 4;
        } else if ((first & 0xF0) == 0xE0) {
          need = 3;
        } else if ((first & 0xE0) == 0xC0) {
          need = 2;
        }
        if (need > 1 && (taken - lead + 1) < need) {
          taken = lead - 1;
        }
      }
    }
  }
  out[taken] = '\0';
}

/* Код возврата curl → код отказа языка. Различать обязательно: «сертификат не
   принят» и «не дозвонился» — разные беды, и программа вправе поступить с ними
   по-разному. Числа — из curl(1), раздел «EXIT CODES». */
static const char *io_tls_code(int code) {
  switch (code) {
    case 60: /* сертификат узла не проверился */
    case 90: /* открытый ключ не совпал с приколотым */
    case 91: /* ответ OCSP негоден */
      return "FLANG_IO_TLS_CERT";
    case 3:  /* адрес разобрать не вышло */
    case 6:  /* имя не разрешилось */
    case 7:  /* не соединилось */
    case 28: /* время вышло */
      return "FLANG_IO_NET";
    default:
      return "FLANG_IO_TLS";
  }
}

static fl_value io_https(io_host *host, const char *method, const char *address, const char *body) {
  /* Больше всего ключей у запроса с телом: 21 слово и замыкающий NULL. Запас
     здесь не «на всякий случай», а на следующий ключ — переполнение массива
     аргументов не заметит ни один прогон. */
  char *args[32];
  size_t count = 0;
  char timeout[32];
  int out_pipe[2];
  int err_pipe[2];
  int in_pipe[2];
  pid_t child = 0;
  repl_buf out;
  repl_buf err;
  int status = 0;
  bool too_much = false;
  bool no_time = false;
  size_t sent = 0;
  size_t to_send = 0;
  void (*was_pipe)(int) = NULL;
  const bool with_body =
      body != NULL && body[0] != '\0' && strcmp(method, "GET") != 0 && strcmp(method, "HEAD") != 0;

  if (!host->spawn) {
    return io_fail("FLANG_IO_DENIED",
                   "«https» здесь исполняет ВНЕШНЯЯ программа, а хозяину запрещено их запускать "
                   "(--no-spawn): своего шифрования у двоичного нет, и завести дитя молча значило бы "
                   "соврать в ключе");
  }

  snprintf(timeout, sizeof(timeout), "%ld", host->timeout_ms > 0 ? (host->timeout_ms + 999) / 1000 : 30L);
  args[count] = IO_TLS_PROGRAM;         count += 1;
  args[count] = "-q";                   count += 1;
  args[count] = "-sS";                  count += 1;
  args[count] = "-i";                   count += 1;
  args[count] = "-g";                   count += 1;
  args[count] = "--http1.1";            count += 1;
  args[count] = "-H";                   count += 1;
  args[count] = "Content-Type:";        count += 1;
  args[count] = "--proto";              count += 1;
  args[count] = "=https";               count += 1;
  args[count] = "--proto-redir";        count += 1;
  args[count] = "=https";               count += 1;
  args[count] = "--tlsv1.2";            count += 1;
  args[count] = "--max-time";           count += 1;
  args[count] = timeout;                count += 1;
  if (strcmp(method, "HEAD") == 0) {
    args[count] = "--head";             count += 1;
  } else {
    args[count] = "-X";                 count += 1;
    args[count] = (char *)method;       count += 1;
  }
  if (with_body) {
    args[count] = "--data-binary";      count += 1;
    args[count] = "@-";                 count += 1;
    to_send = strlen(body);
  }
  args[count] = "--";                   count += 1;
  args[count] = (char *)address;        count += 1;
  args[count] = NULL;

  if (pipe(out_pipe) != 0) {
    return io_fail_errno("FLANG_IO_TLS", "труба вывода не заведена");
  }
  if (pipe(err_pipe) != 0) {
    close(out_pipe[0]);
    close(out_pipe[1]);
    return io_fail_errno("FLANG_IO_TLS", "труба ошибок не заведена");
  }
  if (pipe(in_pipe) != 0) {
    close(out_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[0]);
    close(err_pipe[1]);
    return io_fail_errno("FLANG_IO_TLS", "труба ввода не заведена");
  }
  child = fork();
  if (child < 0) {
    close(out_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[0]);
    close(err_pipe[1]);
    close(in_pipe[0]);
    close(in_pipe[1]);
    return io_fail_errno("FLANG_IO_TLS", "внешний хозяин не порождён");
  }
  if (child == 0) {
    dup2(in_pipe[0], 0);
    dup2(out_pipe[1], 1);
    dup2(err_pipe[1], 2);
    close(in_pipe[0]);
    close(in_pipe[1]);
    close(out_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[0]);
    close(err_pipe[1]);
    /* 126 — «каталог не сменился», 127 — «программы нет». Слить их нельзя:
       вторая означает «шифрования здесь нет», а первая — нашу же беду. */
    if (chdir(host->root) != 0) {
      _exit(126);
    }
    execvp(IO_TLS_PROGRAM, args);
    _exit(127);
  }
  close(in_pipe[0]);
  close(out_pipe[1]);
  close(err_pipe[1]);
  if (!with_body) {
    close(in_pipe[1]);
    in_pipe[1] = -1;
  }
  /* Дитя вправе закрыть свой конец раньше, чем мы дописали тело; без этого
     SIGPIPE снял бы НАС, а не его. Прежний обработчик возвращается на место. */
  was_pipe = signal(SIGPIPE, SIG_IGN);

  buf_init(&out);
  buf_init(&err);
  {
    int fds[2];
    bool alive[2];
    char chunk[4096];
    fds[0] = out_pipe[0];
    fds[1] = err_pipe[0];
    alive[0] = true;
    alive[1] = true;
    while (alive[0] || alive[1] || in_pipe[1] >= 0) {
      fd_set reading;
      fd_set writing;
      int top = -1;
      int index = 0;
      struct timeval wait;
      FD_ZERO(&reading);
      FD_ZERO(&writing);
      for (index = 0; index < 2; index += 1) {
        if (alive[index]) {
          FD_SET(fds[index], &reading);
          if (fds[index] > top) top = fds[index];
        }
      }
      if (in_pipe[1] >= 0) {
        FD_SET(in_pipe[1], &writing);
        if (in_pipe[1] > top) top = in_pipe[1];
      }
      wait.tv_sec = host->timeout_ms / 1000;
      wait.tv_usec = (host->timeout_ms % 1000) * 1000;
      if (select(top + 1, &reading, &writing, NULL, &wait) <= 0) {
        no_time = true;
        kill(child, SIGKILL);
        break;
      }
      if (in_pipe[1] >= 0 && FD_ISSET(in_pipe[1], &writing)) {
        const ssize_t put = write(in_pipe[1], body + sent, to_send - sent);
        if (put <= 0) {
          close(in_pipe[1]);
          in_pipe[1] = -1;
        } else {
          sent += (size_t)put;
          if (sent >= to_send) {
            close(in_pipe[1]);
            in_pipe[1] = -1;
          }
        }
      }
      for (index = 0; index < 2; index += 1) {
        if (alive[index] && FD_ISSET(fds[index], &reading)) {
          const ssize_t got = read(fds[index], chunk, sizeof(chunk));
          if (got <= 0) {
            alive[index] = false;
          } else {
            buf_add(index == 0 ? &out : &err, chunk, (size_t)got);
            if (out.used + err.used > IO_OUT_LIMIT) {
              too_much = true;
              kill(child, SIGKILL);
              alive[0] = false;
              alive[1] = false;
            }
          }
        }
      }
    }
  }
  if (in_pipe[1] >= 0) close(in_pipe[1]);
  close(out_pipe[0]);
  close(err_pipe[0]);
  signal(SIGPIPE, was_pipe);
  while (waitpid(child, &status, 0) < 0 && errno == EINTR) {
    /* повтор */
  }

  if (no_time) {
    buf_free(&out);
    buf_free(&err);
    return io_fail("FLANG_IO_NET", "внешний хозяин «" IO_TLS_PROGRAM "» не уложился в срок");
  }
  if (too_much) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "ответ по «https» больше %d байт", IO_OUT_LIMIT);
    buf_free(&out);
    buf_free(&err);
    return io_fail("FLANG_IO_TLS", buffer);
  }
  if (WIFSIGNALED(status)) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "внешний хозяин «%s» снят сигналом %d", IO_TLS_PROGRAM, WTERMSIG(status));
    buf_free(&out);
    buf_free(&err);
    return io_fail("FLANG_IO_TLS", buffer);
  }
  {
    const int code = WEXITSTATUS(status);
    if (code == 127) {
      buf_free(&out);
      buf_free(&err);
      return io_fail("FLANG_IO_NO_TLS",
                     "своего шифрования у двоичного хозяина нет, а внешней программы «" IO_TLS_PROGRAM
                     "» на машине не нашлось: адрес по «https» исполнить нечем, "
                     "а притворяться, что сходил, — хуже отказа");
    }
    if (code == 126) {
      buf_free(&out);
      buf_free(&err);
      return io_fail("FLANG_IO_TLS", "внешнему хозяину не сменился рабочий каталог");
    }
    if (code != 0) {
      char line[512];
      char buffer[768];
      io_first_line(err.data, err.used, line, sizeof(line));
      if (line[0] == '\0') {
        snprintf(buffer, sizeof(buffer), "внешний хозяин «%s» вернул код %d и ничего не сказал", IO_TLS_PROGRAM,
                 code);
      } else {
        snprintf(buffer, sizeof(buffer), "%s", line);
      }
      buf_free(&out);
      buf_free(&err);
      return io_fail(io_tls_code(code), buffer);
    }
  }
  {
    fl_value result = io_http_answer(&out);
    buf_free(&out);
    buf_free(&err);
    return result;
  }
}

/* ── сеть: запрос по HTTP ────────────────────────────────────────────────── */

/*
 * Клиент HTTP/1.1 БЕЗ ШИФРОВАНИЯ, своим сокетом, — ровно столько, сколько нужно
 * поручению «Запросить» по «http://».
 *
 * `https` разбирается ЗДЕСЬ ЖЕ, но исполняется не здесь: он уходит в
 * `io_https` внешней программе. Втащить TLS в это основание значило бы положить
 * в него чужую криптографию — путь отвергнутый, а не забытый; отдать поручение
 * наружу — тот же путь, каким в словаре живут процессы. Довод целиком —
 * `docs/adr/0007-encryption-by-request-to-an-external-host.md`.
 */
static fl_value io_request(io_host *host, const char *method, const char *address, const char *body) {
  char host_name[512];
  char path[2048];
  char port[16];
  const char *rest = NULL;
  const char *slash = NULL;
  const char *colon = NULL;
  struct addrinfo hints;
  struct addrinfo *found = NULL;
  int fd = -1;
  repl_buf request;
  repl_buf answer;
  fl_value result = fl_nothing();

  if (strncmp(address, "https://", 8) == 0) {
    return io_https(host, method, address, body);
  }
  if (strncmp(address, "http://", 7) != 0) {
    return io_fail("FLANG_IO_NET", "адрес обязан начинаться с «http://»");
  }
  rest = address + 7;
  slash = strchr(rest, '/');
  if (slash == NULL) {
    snprintf(host_name, sizeof(host_name), "%s", rest);
    snprintf(path, sizeof(path), "/");
  } else {
    const size_t length = (size_t)(slash - rest);
    snprintf(host_name, sizeof(host_name), "%.*s", (int)(length < sizeof(host_name) ? length : sizeof(host_name) - 1),
             rest);
    snprintf(path, sizeof(path), "%s", slash);
  }
  colon = strchr(host_name, ':');
  if (colon == NULL) {
    snprintf(port, sizeof(port), "80");
  } else {
    snprintf(port, sizeof(port), "%s", colon + 1);
    host_name[colon - host_name] = '\0';
  }

  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_STREAM;
  if (getaddrinfo(host_name, port, &hints, &found) != 0 || found == NULL) {
    char buffer[768];
    snprintf(buffer, sizeof(buffer), "имя «%s» не разрешилось в адрес", host_name);
    return io_fail("FLANG_IO_NET", buffer);
  }
  fd = socket(found->ai_family, found->ai_socktype, found->ai_protocol);
  if (fd < 0 || connect(fd, found->ai_addr, found->ai_addrlen) != 0) {
    if (fd >= 0) close(fd);
    freeaddrinfo(found);
    return io_fail_errno("FLANG_IO_NET", "связь не установлена");
  }
  freeaddrinfo(found);

  buf_init(&request);
  buf_put(&request, method);
  buf_put(&request, " ");
  buf_put(&request, path);
  buf_put(&request, " HTTP/1.1\r\nHost: ");
  buf_put(&request, host_name);
  buf_put(&request, "\r\nConnection: close\r\n");
  if (body != NULL && body[0] != '\0' && strcmp(method, "GET") != 0 && strcmp(method, "HEAD") != 0) {
    char length[64];
    snprintf(length, sizeof(length), "Content-Length: %lu\r\n", (unsigned long)strlen(body));
    buf_put(&request, length);
    buf_put(&request, "\r\n");
    buf_put(&request, body);
  } else {
    buf_put(&request, "\r\n");
  }
  if (write(fd, request.data, request.used) < 0) {
    buf_free(&request);
    close(fd);
    return io_fail_errno("FLANG_IO_NET", "запрос не отправлен");
  }
  buf_free(&request);

  buf_init(&answer);
  for (;;) {
    char chunk[4096];
    const ssize_t got = read(fd, chunk, sizeof(chunk));
    if (got <= 0) break;
    buf_add(&answer, chunk, (size_t)got);
    if (answer.used > IO_OUT_LIMIT) break;
  }
  close(fd);

  result = io_http_answer(&answer);
  buf_free(&answer);
  return result;
}

/* ── один поручение → один отклик ────────────────────────────────────────── */

static int io_compare_names(const void *left, const void *right) {
  return strcmp(*(const char *const *)left, *(const char *const *)right);
}

static fl_value io_perform(io_host *host, fl_value order) {
  const char *name = NULL;
  size_t name_bytes = 0;

  if (io_order_is(order, "Прочитать файл")) {
    char *given = io_order_text(order, "путь");
    fl_value bad = fl_nothing();
    bool ok = true;
    char *full = NULL;
    if (!host->read_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено читать файлы");
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    {
      size_t bytes = 0;
      char *text = repl_read_file(full, &bytes);
      free(full);
      if (text == NULL) {
        return io_fail_errno("FLANG_IO_READ", "файл не прочитан");
      }
      {
        const size_t at = fl_utf8_not_text_at(text, bytes);
        if (at > 0) {
          fl_value refusal = io_not_text("файл", text, bytes, at, "Прочитать октеты из файла");
          free(text);
          return refusal;
        }
      }
      {
        fl_value fields[1];
        fields[0] = io_pair("содержимое", io_text(text, bytes));
        free(text);
        return io_variant("Прочитано", fields, 1);
      }
    }
  }

  if (io_order_is(order, "Записать файл")) {
    char *given = io_order_text(order, "путь");
    fl_value field = fl_nothing();
    fl_value bad = fl_nothing();
    const char *text = "";
    size_t bytes = 0;
    bool ok = true;
    char *full = NULL;
    if (!host->write_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено писать файлы");
    }
    /* Содержимое берётся ЗНАЧЕНИЕМ, а не копией через `io_order_text`: у копии
       длина считалась `strlen`, и нулевой октет обрывал запись молча — 4096
       октетов на входе, 7 байт на выходе. У значения длина своя, точная, и
       нулевой октет теперь доезжает до диска как всякий другой. */
    if (io_order_field(order, "содержимое", &field)) {
      (void)zn_text(field, &text, &bytes);
    }
    {
      const size_t at = fl_utf8_not_text_at(text, bytes);
      if (at > 0) {
        free(given);
        return io_not_text("содержимое", text, bytes, at, "Записать октеты в файл");
      }
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    {
      FILE *file = fopen(full, "wb");
      free(full);
      if (file == NULL) {
        return io_fail_errno("FLANG_IO_WRITE", "файл не открыт на запись");
      }
      if (bytes > 0 && fwrite(text, 1, bytes, file) != bytes) {
        fclose(file);
        return io_fail_errno("FLANG_IO_WRITE", "файл не записан");
      }
      fclose(file);
      {
        fl_value fields[1];
        fields[0] = io_pair("сколько", io_number((double)io_points(text, bytes)));
        return io_variant("Записано", fields, 1);
      }
    }
  }

  /*
   * ── ОКТЕТНАЯ ПАРА У ФАЙЛОВ ────────────────────────────────────────────────
   *
   * Ровно та же пара, что ADR-0004 завёл соединению, и заведена она по тому же
   * доводу: хозяин ничего не решает о смысле байтов. Список чисел из [0, 255]
   * не переводится ни при чтении, ни при записи — значит терять нечего и
   * хозяевам разойтись негде. Длина берётся у СПИСКА, поэтому нулевой октет
   * здесь обычное число 0, а не конец файла.
   *
   * Откликов своих не заведено: чтение отвечает «Октеты» — тем же, что у
   * соединения, — а запись «Записано», и `сколько` там честнее текстового,
   * потому что меряет октеты, а не кодовые точки.
   *
   * Пустой список у файла значит ПУСТОЙ ФАЙЛ, а не конец связи: продолжения у
   * файла нет, он читается целиком одним поручением.
   */
  if (io_order_is(order, "Прочитать октеты из файла")) {
    char *given = io_order_text(order, "путь");
    fl_value bad = fl_nothing();
    bool ok = true;
    char *full = NULL;
    if (!host->read_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено читать файлы");
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    {
      size_t bytes = 0;
      char *text = repl_read_file(full, &bytes);
      free(full);
      if (text == NULL) {
        return io_fail_errno("FLANG_IO_READ", "файл не прочитан");
      }
      {
        fl_value *values = bytes == 0 ? NULL : (fl_value *)repl_alloc(bytes * sizeof(fl_value));
        fl_value fields[1];
        fl_value answer = fl_nothing();
        size_t at = 0;
        for (at = 0; at < bytes; at += 1) {
          values[at] = io_number((double)(unsigned char)text[at]);
        }
        free(text);
        fields[0] = io_pair("октеты", io_list(values, bytes));
        free(values);
        answer = io_variant("Октеты", fields, 1);
        return answer;
      }
    }
  }

  if (io_order_is(order, "Записать октеты в файл")) {
    char *given = io_order_text(order, "путь");
    fl_value list = fl_nothing();
    fl_value bad = fl_nothing();
    const fl_value *items = NULL;
    size_t count = 0;
    bool ok = true;
    char *full = NULL;
    if (!host->write_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено писать файлы");
    }
    if (!io_order_field(order, "октеты", &list) || !zn_items(list, &items, &count)) {
      free(given);
      return io_fail("FLANG_IO_OCTETS", "поручению нужен список октетов, а дан не список");
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    {
      unsigned char *bytes = count == 0 ? NULL : (unsigned char *)repl_alloc(count);
      FILE *file = NULL;
      size_t at = 0;
      for (at = 0; at < count; at += 1) {
        double octet = 0;
        /* Каждое число проверяется на месте, и отказ называет номер: тихое
           приведение к байту записало бы в файл не то, что сказала программа. */
        if (!zn_number(items[at], &octet) || octet < 0 || octet > 255 || octet != (double)(long)octet) {
          char why[128];
          snprintf(why, sizeof(why), "октет %lu не годится: нужно целое от 0 до 255", (unsigned long)(at + 1));
          free(bytes);
          free(full);
          return io_fail("FLANG_IO_OCTETS", why);
        }
        bytes[at] = (unsigned char)(long)octet;
      }
      file = fopen(full, "wb");
      free(full);
      if (file == NULL) {
        free(bytes);
        return io_fail_errno("FLANG_IO_WRITE", "файл не открыт на запись");
      }
      if (count > 0 && fwrite(bytes, 1, count, file) != count) {
        fclose(file);
        free(bytes);
        return io_fail_errno("FLANG_IO_WRITE", "файл не записан");
      }
      fclose(file);
      free(bytes);
      {
        fl_value fields[1];
        fields[0] = io_pair("сколько", io_number((double)count));
        return io_variant("Записано", fields, 1);
      }
    }
  }

  /* «Удалить файл» убирает ОДНО имя: файл или ПУСТОЙ каталог. Зовётся `remove`,
     а не `unlink`+`rmdir` вручную, потому что в POSIX он и есть «убрать имя, чем
     бы оно ни было», и различать эти два случая хозяину незачем — план назвал
     путь, а не вид узла. Рекурсии здесь нет и не будет: «Перечислить каталог»
     отдаёт имена без признака каталога, и обход дерева стоял бы на догадке.
     Разрешение спрашивается ТО ЖЕ, что у записи: удаление — это запись в дерево,
     и хозяин, которому писать запрещено, удалять тем более не вправе. */
  if (io_order_is(order, "Удалить файл")) {
    char *given = io_order_text(order, "путь");
    fl_value bad = fl_nothing();
    bool ok = true;
    char *full = NULL;
    if (!host->write_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено писать файлы");
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    if (remove(full) != 0) {
      free(full);
      return io_fail_errno("FLANG_IO_REMOVE", "имя не убрано");
    }
    free(full);
    return io_variant("Убрано", NULL, 0);
  }

  /* «Завести временный каталог»: имя досочиняет ХОЗЯИН (`mkdtemp`), и потому два
     прогона одного плана за один каталог не дерутся. План даёт ОБРАЗЕЦ — начало
     имени, — и обратно получает путь В ТЕХ ЖЕ КООРДИНАТАХ, в каких давал: он
     относителен каталогу работы, и остальные поручения примут его как есть.
     Отдавать полный путь нельзя: под правилом «внутри каталога» он и сам по себе
     годится, но план, сложивший из него имя файла, получил бы путь, который
     `io_path` уже не примет на чужом хозяине. Шесть `X` добавляет хозяин: они
     часть договора `mkdtemp`, а не имени, которое выбирал план. */
  if (io_order_is(order, "Завести временный каталог")) {
    char *given = io_order_text(order, "образец");
    fl_value bad = fl_nothing();
    bool ok = true;
    char *full = NULL;
    char *pattern = NULL;
    size_t bytes = 0;
    if (!host->write_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено писать файлы");
    }
    full = io_path(host, given, &bad, &ok);
    if (!ok) {
      free(given);
      return bad;
    }
    bytes = strlen(full);
    pattern = (char *)repl_alloc(bytes + 7);
    memcpy(pattern, full, bytes);
    memcpy(pattern + bytes, "XXXXXX", 7);
    free(full);
    if (mkdtemp(pattern) == NULL) {
      free(pattern);
      free(given);
      return io_fail_errno("FLANG_IO_TEMPDIR", "временный каталог не заведён");
    }
    {
      const size_t head = strlen(given);
      char *answer = (char *)repl_alloc(head + 7);
      fl_value fields[1];
      memcpy(answer, given, head);
      memcpy(answer + head, pattern + bytes, 7);
      free(pattern);
      free(given);
      fields[0] = io_pair("путь", io_say(answer));
      free(answer);
      return io_variant("Заведено", fields, 1);
    }
  }

  if (io_order_is(order, "Перечислить каталог")) {
    char *given = io_order_text(order, "путь");
    fl_value bad = fl_nothing();
    bool ok = true;
    char *full = NULL;
    if (!host->read_files) {
      free(given);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено читать файлы");
    }
    full = io_path(host, given, &bad, &ok);
    free(given);
    if (!ok) return bad;
    {
      DIR *directory = opendir(full);
      repl_strings names;
      free(full);
      if (directory == NULL) {
        return io_fail_errno("FLANG_IO_LIST", "каталог не открыт");
      }
      strings_init(&names);
      for (;;) {
        const struct dirent *entry = readdir(directory);
        if (entry == NULL) break;
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        strings_say(&names, entry->d_name);
      }
      closedir(directory);
      /* СОРТИРОВКА — НЕ ПРИЧЁСЫВАНИЕ ВЫВОДА, а условие сравнимости: `readdir`
         порядка не обещает вовсе, а весь смысл словаря в том, что журнал
         поручений настоящего хозяина сверяется с журналом поддельного. Порядок
         — по байтам UTF-8, то есть по кодовым точкам, а не по правилам локали:
         локаль — это то, чего хозяин не выбирает. */
      qsort(names.items, names.count, sizeof(char *), io_compare_names);
      {
        fl_value *values = names.count == 0 ? NULL : (fl_value *)repl_alloc(names.count * sizeof(fl_value));
        fl_value fields[1];
        size_t index = 0;
        for (index = 0; index < names.count; index += 1) {
          values[index] = io_say(names.items[index]);
        }
        fields[0] = io_pair("имена", io_list(values, names.count));
        free(values);
        strings_free(&names);
        return io_variant("Перечислено", fields, 1);
      }
    }
  }

  if (io_order_is(order, "Запустить процесс")) {
    char *program = io_order_text(order, "программа");
    fl_value list = fl_nothing();
    const fl_value *items = NULL;
    size_t count = 0;
    if (!host->spawn) {
      free(program);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено запускать процессы");
    }
    if (program == NULL || program[0] == '\0') {
      free(program);
      return io_fail("FLANG_IO_SPAWN", "поручению нужно непустое имя программы");
    }
    if (io_order_field(order, "аргументы", &list)) {
      zn_items(list, &items, &count);
    }
    {
      char **argv = (char **)repl_alloc((count + 2) * sizeof(char *));
      fl_value answer = fl_nothing();
      size_t index = 0;
      argv[0] = program;
      for (index = 0; index < count; index += 1) {
        const char *utf8 = NULL;
        size_t bytes = 0;
        argv[index + 1] = zn_text(items[index], &utf8, &bytes) ? repl_dup(utf8, bytes) : repl_say("");
      }
      argv[count + 1] = NULL;
      answer = io_spawn(host, program, argv);
      for (index = 0; index < count; index += 1) {
        free(argv[index + 1]);
      }
      free(argv);
      free(program);
      return answer;
    }
  }

  if (io_order_is(order, "Текущее время")) {
    fl_value fields[1];
    struct timeval now;
    if (!host->clock) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено смотреть на часы");
    }
    gettimeofday(&now, NULL);
    fields[0] = io_pair("миллисекунды", io_number((double)now.tv_sec * 1000.0 + (double)(now.tv_usec / 1000)));
    return io_variant("Отметка времени", fields, 1);
  }

  if (io_order_is(order, "Случайное число")) {
    fl_value fields[1];
    if (!host->random) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено бросать кости");
    }
    fields[0] = io_pair("значение", io_number(io_random(host)));
    return io_variant("Выпало", fields, 1);
  }

  if (io_order_is(order, "Запросить")) {
    char *method = io_order_text(order, "способ");
    char *address = io_order_text(order, "адрес");
    char *body = io_order_text(order, "тело");
    fl_value answer = fl_nothing();
    if (!host->net) {
      free(method);
      free(address);
      free(body);
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    {
      char upper[16];
      size_t index = 0;
      const char *from = method == NULL ? "GET" : method;
      for (index = 0; index + 1 < sizeof(upper) && from[index] != '\0'; index += 1) {
        upper[index] = (char)(from[index] >= 'a' && from[index] <= 'z' ? from[index] - 32 : from[index]);
      }
      upper[index] = '\0';
      answer = io_request(host, upper, address == NULL ? "" : address, body);
    }
    free(method);
    free(address);
    free(body);
    return answer;
  }

  if (io_order_is(order, "Открыть соединение")) {
    double port = 0;
    char why[256];
    char *address = NULL;
    int fd = -1;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    address = io_order_text(order, "адрес");
    if (address == NULL || address[0] == '\0') {
      free(address);
      return io_fail("FLANG_IO_NET", "поручению «Открыть соединение» нужен непустой адрес");
    }
    /* Ноль здесь НЕ годится, в отличие от приёма: «порт 0» на слушающем сокете
       значит «дай любой свободный», а на исходящем не значит ничего. */
    if (!io_order_number(order, "порт", &port) || port < 1 || port > 65535 || port != (double)(long)port) {
      free(address);
      return io_fail("FLANG_IO_NET", "порт не годится: нужно целое от 1 до 65535");
    }
    if (host->link_count == IO_MAX_LINKS) {
      free(address);
      return io_fail("FLANG_IO_NET", "у хозяина кончились места под соединения");
    }
    fd = io_connect_to(host, address, (int)port, why, sizeof(why));
    free(address);
    if (fd < 0) {
      return io_fail("FLANG_IO_NET", why);
    }
    {
      fl_value fields[1];
      host->links[host->link_count].number = host->next_link;
      host->links[host->link_count].fd = fd;
      host->links[host->link_count].outgoing = true;
      host->link_count += 1;
      fields[0] = io_pair("соединение", io_number((double)host->next_link));
      host->next_link += 1;
      return io_variant("Соединение открыто", fields, 1);
    }
  }

  if (io_order_is(order, "Принять соединение")) {
    double port = 0;
    char why[256];
    int fd = -1;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    if (!io_order_number(order, "порт", &port) || port < 0 || port > 65535 || port != (double)(long)port) {
      return io_fail("FLANG_IO_NET", "порт не годится: нужно целое от 0 до 65535");
    }
    fd = io_listen_on(host, (int)port, why, sizeof(why));
    if (fd < 0) {
      return io_fail("FLANG_IO_NET", why);
    }
    if (host->link_count == IO_MAX_LINKS) {
      return io_fail("FLANG_IO_NET", "у хозяина кончились места под соединения");
    }
    {
      const int accepted = accept(fd, NULL, NULL);
      fl_value fields[1];
      if (accepted < 0) {
        return io_fail_errno("FLANG_IO_NET", "соединение не принято");
      }
      host->links[host->link_count].number = host->next_link;
      host->links[host->link_count].fd = accepted;
      host->links[host->link_count].outgoing = false;
      host->link_count += 1;
      fields[0] = io_pair("соединение", io_number((double)host->next_link));
      host->next_link += 1;
      return io_variant("Соединение открыто", fields, 1);
    }
  }

  if (io_order_is(order, "Прочитать из соединения")) {
    double number = 0;
    int fd = -1;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    if (!io_order_number(order, "соединение", &number) || (fd = io_link_fd(host, (int)number)) < 0) {
      return io_fail("FLANG_IO_READ", "соединения у хозяина нет: оно закрыто, не принималось и не открывалось");
    }
    {
      char chunk[8192];
      const ssize_t got = read(fd, chunk, sizeof(chunk));
      fl_value fields[1];
      /* Пустая строка — это КОНЕЦ, а не «пока ничего»: сюда попадают только
         после того, как связь кончилась. Программа этим и отличает обрезанный
         запрос от недочитанного. */
      fields[0] = io_pair("содержимое", io_text(chunk, got > 0 ? (size_t)got : 0));
      return io_variant("Прочитано", fields, 1);
    }
  }

  if (io_order_is(order, "Ответить в соединение")) {
    double number = 0;
    int fd = -1;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    if (!io_order_number(order, "соединение", &number) || (fd = io_link_fd(host, (int)number)) < 0) {
      return io_fail("FLANG_IO_WRITE", "соединения у хозяина нет: оно закрыто, не принималось и не открывалось");
    }
    /* Содержимое берётся ЗНАЧЕНИЕМ, а не копией: у копии длина считалась
       `strlen`, и пакет, начинающийся с нулевого октета, «записывался» нулём
       байт — а нулевая длина здесь ещё и значит «положить трубку», то есть
       двоичный запрос не просто терялся, он рвал соединение. Разбор —
       `docs/zettel/the-binary-host-cuts-content-at-the-first-zero-octet.md`.
       Двоичное возит октетная пара ниже; здесь — текст, и нетекст отвергается. */
    {
      fl_value field = fl_nothing();
      fl_value fields[1];
      const char *text = "";
      size_t bytes = 0;
      size_t at = 0;
      /* ЕДИНСТВЕННОЕ место, где принятое соединение отличается от открытого:
         закрывает тот, кто завёл. Принятое хозяин закрывает ответом — обмен на
         нём кончился; открытое оставляет программе — разговор продолжается.
         Пустое содержимое закрывает и то и другое: это и есть «положить
         трубку», и другого слова для этого в словаре нет. */
      bool closing = false;
      if (io_order_field(order, "содержимое", &field)) {
        (void)zn_text(field, &text, &bytes);
      }
      at = fl_utf8_not_text_at(text, bytes);
      if (at > 0) {
        return io_not_text("содержимое", text, bytes, at, "Ответить октетами в соединение");
      }
      closing = bytes == 0 || !io_link_outgoing(host, (int)number);
      if (bytes > 0 && write(fd, text, bytes) < 0) {
        close(fd);
        io_link_drop(host, (int)number);
        return io_fail_errno("FLANG_IO_WRITE", "ответ не записан");
      }
      if (closing) {
        close(fd);
        io_link_drop(host, (int)number);
      }
      fields[0] = io_pair("сколько", io_number((double)io_points(text, bytes)));
      return io_variant("Записано", fields, 1);
    }
  }

  /*
   * ── ОКТЕТЫ ────────────────────────────────────────────────────────────────
   * Та же труба, что у пары выше, но без единого решения о том, что байты
   * значат. У двоичного хозяина порча своя, не такая, как у хозяина на Node, и
   * названа она числом: Node раскодирует поток как UTF-8 и заменяет всякий
   * не-UTF-8 октет знаком U+FFFD, а здесь байты доезжают сырыми — зато `strlen`
   * при ЗАПИСИ обрезает содержимое на первом нулевом октете. То есть двоичный
   * протокол не работал ни под одним из двух хозяев, и не работал по-разному:
   * один терял на чтении, другой на записи.
   *
   * Список чисел лечит обоих сразу и лечит одинаково: переводить нечего, значит
   * и разойтись негде. Длина берётся из СПИСКА, а не из `strlen`, — вот почему
   * нулевой октет здесь обычное число 0.
   */
  if (io_order_is(order, "Прочитать октеты из соединения")) {
    double number = 0;
    int fd = -1;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    if (!io_order_number(order, "соединение", &number) || (fd = io_link_fd(host, (int)number)) < 0) {
      return io_fail("FLANG_IO_READ", "соединения у хозяина нет: оно закрыто, не принималось и не открывалось");
    }
    {
      unsigned char chunk[8192];
      const ssize_t got = read(fd, chunk, sizeof(chunk));
      const size_t count = got > 0 ? (size_t)got : 0;
      fl_value *values = count == 0 ? NULL : (fl_value *)repl_alloc(count * sizeof(fl_value));
      fl_value fields[1];
      fl_value answer = fl_nothing();
      size_t at = 0;
      for (at = 0; at < count; at += 1) {
        values[at] = io_number((double)chunk[at]);
      }
      /* Пустой список — это КОНЕЦ, ровно как пустая строка у «Прочитано». */
      fields[0] = io_pair("октеты", io_list(values, count));
      free(values);
      answer = io_variant("Октеты", fields, 1);
      return answer;
    }
  }

  if (io_order_is(order, "Ответить октетами в соединение")) {
    double number = 0;
    int fd = -1;
    fl_value list = fl_nothing();
    const fl_value *items = NULL;
    size_t count = 0;
    if (!host->net) {
      return io_fail("FLANG_IO_DENIED", "хозяину запрещено ходить в сеть");
    }
    if (!io_order_number(order, "соединение", &number) || (fd = io_link_fd(host, (int)number)) < 0) {
      return io_fail("FLANG_IO_WRITE", "соединения у хозяина нет: оно закрыто, не принималось и не открывалось");
    }
    if (!io_order_field(order, "октеты", &list) || !zn_items(list, &items, &count)) {
      return io_fail("FLANG_IO_OCTETS", "поручению нужен список октетов, а дан не список");
    }
    {
      unsigned char *bytes = count == 0 ? NULL : (unsigned char *)repl_alloc(count);
      size_t at = 0;
      for (at = 0; at < count; at += 1) {
        double octet = 0;
        /* Каждое число проверяется на месте, и отказ называет номер. Молчаливое
           приведение к байту отправило бы собеседнику не то, что сказала
           программа, и разница всплыла бы у него, а не здесь. */
        if (!zn_number(items[at], &octet) || octet < 0 || octet > 255 || octet != (double)(long)octet) {
          char why[128];
          snprintf(why, sizeof(why), "октет %lu не годится: нужно целое от 0 до 255", (unsigned long)(at + 1));
          free(bytes);
          return io_fail("FLANG_IO_OCTETS", why);
        }
        bytes[at] = (unsigned char)(long)octet;
      }
      {
        /* Правила закрытия — те же самые и взяты у текстового близнеца
           буквально: закрывает тот, кто завёл; пустое кладёт трубку. Пустое
           здесь — пустой СПИСОК. */
        const bool closing = count == 0 || !io_link_outgoing(host, (int)number);
        fl_value fields[1];
        if (count > 0 && write(fd, bytes, count) < 0) {
          free(bytes);
          close(fd);
          io_link_drop(host, (int)number);
          return io_fail_errno("FLANG_IO_WRITE", "ответ не записан");
        }
        free(bytes);
        if (closing) {
          close(fd);
          io_link_drop(host, (int)number);
        }
        /* ОКТЕТЫ, а не кодовые точки: у текстового близнеца здесь названный
           зазор («Content-Length служба считает знаками»), а тут его нет — что
           записано, то и посчитано. */
        fields[0] = io_pair("сколько", io_number((double)count));
        return io_variant("Записано", fields, 1);
      }
    }
  }

  /*
   * Экрана у двоичного нет, и сказано это ИМЕНОВАННЫМ отказом, а не «не знаю
   * такого поручения». Разница не педантизм: первое значит «хозяин отстал от
   * словаря языка и его надо чинить», второе — «программа просит невозможного
   * здесь и может попросить другого».
   */
  if (io_order_is(order, "Показать") || io_order_is(order, "Ждать событие")) {
    char buffer[256];
    const char *utf8 = NULL;
    size_t bytes = 0;
    io_order_name(order, &utf8, &bytes);
    snprintf(buffer, sizeof(buffer), "у двоичного хозяина нет экрана: поручение «%.*s» исполнить нечем", (int)bytes,
             utf8);
    return io_fail("FLANG_IO_NO_SCREEN", buffer);
  }

  {
    char buffer[256];
    if (io_order_name(order, &name, &name_bytes)) {
      snprintf(buffer, sizeof(buffer), "хозяин не знает поручения «%.*s»", (int)name_bytes, name);
    } else {
      snprintf(buffer, sizeof(buffer), "хозяину пришло не поручение");
    }
    return io_fail("FLANG_IO_UNKNOWN", buffer);
  }
}

/*
 * Отказ печатается тем же JSON, что у свидетеля: `{error, diagnostics}`, где
 * диагностика одна и несёт код и сообщение. Идёт он в stderr, а не в stdout, —
 * там, где у удачи стоит вердикт.
 */
static void io_print_error(const char *code, const char *message, double line, double column, bool pretty) {
  fl_value diagnostic[4];
  fl_value list[1];
  fl_value pairs[2];
  fl_value printed = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  size_t count = 3;
  diagnostic[0] = io_pair("code", io_say(code));
  diagnostic[1] = io_pair("message", io_say(message));
  diagnostic[2] = io_pair("severity", io_say("error"));
  /* МЕСТО СТАВИТСЯ НЕ ВСЕГДА, и это не небрежность: свидетель кладёт `span`
     тому отказу, который родился ВНУТРИ прогона плана (`план.span`), и не
     кладёт тому, который родился до него — «плана с таким именем нет» указывать
     не на что. Ключ, поставленный лишний раз, разошёлся бы с ним побайтово. */
  if (line > 0) {
    fl_value place[2];
    place[0] = io_pair("line", io_number(line));
    place[1] = io_pair("column", io_number(column));
    diagnostic[3] = io_pair("span", io_record(place, 2));
    count = 4;
  }
  list[0] = io_record(diagnostic, count);
  pairs[0] = io_pair("error", io_say(message));
  pairs[1] = io_pair("diagnostics", io_list(list, 1));
  {
    fl_value node = io_record(pairs, 2);
    if (repl_call("Печать значения", &node, 1, &printed) == FL_OK && val_text(printed, &utf8, &bytes)) {
      if (pretty) {
        ast_pretty_to(stderr, utf8, bytes);
      } else {
        fwrite(utf8, 1, bytes, stderr);
      }
      fputc('\n', stderr);
    } else {
      fprintf(stderr, "%s: %s\n", code, message);
    }
  }
}

/** Вердикт удачного прогона: `{plan, result, orders, log}` — ключи свидетеля. */
static void io_report(fl_value plan, fl_value result, const fl_value *log, size_t count, bool pretty) {
  fl_value pairs[4];
  fl_value field = fl_nothing();
  fl_value printed = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  char *name = NULL;
  val_field(plan, "имя", &field);
  name = val_copy(field);
  pairs[0] = io_pair("plan", io_say(name));
  pairs[1] = io_pair("result", result);
  pairs[2] = io_pair("orders", io_number((double)count));
  pairs[3] = io_pair("log", io_list(log, count));
  free(name);
  {
    fl_value node = io_record(pairs, 4);
    if (repl_call("Печать значения", &node, 1, &printed) != FL_OK || !val_text(printed, &utf8, &bytes)) {
      fputs("flang io: вердикт не напечатался\n", stderr);
      return;
    }
    if (pretty) {
      ast_pretty(utf8, bytes);
    } else {
      fwrite(utf8, 1, bytes, stdout);
    }
    fputc('\n', stdout);
    fflush(stdout);
  }
}

/*
 * Виток за витком: шаг плана, поручение хозяину, отклик обратно.
 *
 * КОД ВОЗВРАТА РЕШАЕТСЯ ЗДЕСЬ, и решается он не по коду отказа, а по тому, КТО
 * принял решение. «Провал» — это вариант, который вернула САМА ПРОГРАММА: она
 * нашла беду и назвала её, и это код 1. Всё остальное, что мешает наступить
 * отклику, — код 3: сломался инструмент. Кодом отказа их не различить, у
 * «Провала» он свой, программа пишет туда что хочет.
 */
static int io_loop(io_host *host, fl_value ready, fl_value plan, fl_value first, fl_value *result,
                   fl_value **log, size_t *count, size_t *room, double limit, bool pretty) {
  fl_value state = fl_nothing();
  fl_value response = fl_nothing();
  fl_value last = fl_nothing();
  fl_value step = first;
  fl_value field = fl_nothing();
  char *kind = NULL;
  char *plan_name = NULL;
  double line = 0;
  double column = 0;
  int code = 0;

  val_field(plan, "имя", &field);
  plan_name = val_copy(field);
  if (val_field(plan, "строка", &field) && field.tag == FL_NUMBER) line = field.as.number;
  if (val_field(plan, "столбец", &field) && field.tag == FL_NUMBER) column = field.as.number;

  val_field(step, "вид", &field);
  kind = val_copy(field);
  if (strcmp(kind, "состояние") != 0) {
    char *why = NULL;
    char *what = NULL;
    val_field(step, "код", &field);
    what = val_copy(field);
    val_field(step, "сообщение", &field);
    why = val_copy(field);
    io_print_error(what[0] == '\0' ? "FLANG_IO" : what, why, line, column, pretty);
    free(why);
    free(what);
    free(kind);
    free(plan_name);
    return 3;
  }
  free(kind);
  val_field(step, "значение", &state);
  response = io_variant("Пока ничего", NULL, 0);

  *log = (fl_value *)repl_alloc(*room * sizeof(fl_value));
  for (;;) {
    fl_value step_args[4];
    /*
     * ПОДКЛЮЧЕНИЕ К ИДУЩЕЙ СЛУЖБЕ — ВТОРАЯ ПОЛОВИНА ОТВЕТА (задача 0061).
     *
     * Обработчик сигнала отвечает сразу и сам, но вправе написать только то,
     * что POSIX объявил безопасным: имя функции, глубину, витки, память. Здесь,
     * на границе витка плана, безопасно всё — и потому здесь говорится то, чего
     * обработчик сказать не мог: какой план идёт и сколько поручений он уже
     * отдал. Заменять друг друга эти два ответа не могут: тесный расчёт до
     * границы витка не дойдёт вовсе, а служба стоит на ней почти всё время.
     *
     * Цена — одно чтение переменной на виток плана, то есть на ПОРУЧЕНИЕ, а не
     * на виток вычислителя. Копия последнего поручения — присваивание
     * `fl_value`, четыре слова, и делается она рядом с настоящим поручением
     * хозяину (файл, сеть, время), против которого не считается.
     */
    if (fl_watch_asked()) {
      const char *what = NULL;
      size_t what_bytes = 0;
      if (!io_order_name(last, &what, &what_bytes)) {
        what = "ещё ни одного";
        what_bytes = strlen(what);
      }
      fprintf(stderr, "ПОДКЛЮЧЕНИЕ: идёт план «%s», поручений отдано %lu, последнее «%.*s»\n", plan_name,
              (unsigned long)*count, (int)what_bytes, what);
      fflush(stderr);
    }
    step_args[0] = ready;
    step_args[1] = plan;
    step_args[2] = state;
    step_args[3] = response;
    if (repl_call("Шаг плана", step_args, 4, &step) != FL_OK) {
      io_print_error("FLANG_IO", "шаг плана не отработал", line, column, pretty);
      free(plan_name);
      return 3;
    }
    val_field(step, "вид", &field);
    kind = val_copy(field);
    if (strcmp(kind, "готово") == 0) {
      val_field(step, "значение", result);
      free(kind);
      free(plan_name);
      return 0;
    }
    if (strcmp(kind, "провал") == 0 || strcmp(kind, "сбой") == 0 || strcmp(kind, "не проверено") == 0) {
      char *what = NULL;
      char *why = NULL;
      bool not_checked = strcmp(kind, "не проверено") == 0;
      val_field(step, "код", &field);
      what = val_copy(field);
      val_field(step, "сообщение", &field);
      why = val_copy(field);
      /* Пустой код у «Провала» заменяется общим: диагностика без кода не
         годится машине. Число выхода при этом от кода не зависит вовсе. */
      /* ЧЕТВЁРТЫЙ ИСХОД. «Не проверено» — это САМА ПРОГРАММА говорит «смотреть
         было нечем», и код у него 3, а не 1: третий код означает «сломался
         инструмент», а не «предмет плох». Умолчание кода у него своё —
         FLANG_IO_NOT_CHECKED, — потому что «сдался сам» и «не смог посмотреть»
         обязаны различаться и в машинном коде диагностики, а не только в
         числе выхода. */
      io_print_error(what[0] == '\0' ? (not_checked ? "FLANG_IO_NOT_CHECKED" : "FLANG_IO_FAILED") : what, why, line,
                     column, pretty);
      code = strcmp(kind, "провал") == 0 ? 1 : 3;
      free(what);
      free(why);
      free(kind);
      free(plan_name);
      return code;
    }
    free(kind);
    if ((double)*count >= limit) {
      char buffer[512];
      snprintf(buffer, sizeof(buffer), "план «%s» исчерпал предел поручений (%.0f)", plan_name, limit);
      io_print_error("FLANG_IO_LIMIT", buffer, line, column, pretty);
      free(plan_name);
      return 3;
    }
    {
      fl_value order = fl_nothing();
      fl_value entry[2];
      val_field(step, "поручение", &order);
      val_field(step, "потом", &state);
      last = order;
      response = io_perform(host, order);
      entry[0] = io_pair("поручение", order);
      entry[1] = io_pair("отклик", response);
      if (*count == *room) {
        *room *= 2;
        *log = (fl_value *)repl_grow(*log, *room * sizeof(fl_value));
      }
      (*log)[*count] = io_record(entry, 2);
      *count += 1;
    }
  }
}

/* ── цикл поручений ──────────────────────────────────────────────────────── */

/*
 * ЦИКЛ ЖИВЁТ ЗДЕСЬ, а шаг — на flang, и граница между ними проведена не по
 * вкусу. Программа на flang доступа к миру не имеет по построению: она строит
 * ОПИСАНИЕ действия и отдаёт его наружу. Значит между двумя поручениями
 * управление обязано выйти к тому, кто умеет делать эффекты, — и цикл
 * принадлежит ему.
 *
 * Свидетель устроен так же (`runPlan` в `flang/src/io.mjs`), только зовёт
 * хозяина функцией; передать функцию в flang нечем, поэтому здесь цикл написан
 * заново, а шаг зовётся по имени: «Начало плана», потом «Шаг плана» на каждом
 * витке. Программа готовится ОДИН раз — «Подготовить программу» отдаёт
 * значение, которое цикл держит между витками.
 */


static int io_file(int argc, char **argv) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  io_host host;
  fl_value args[6];
  fl_value found = fl_nothing();
  fl_value plan = fl_nothing();
  fl_value program = fl_nothing();
  fl_value ready = fl_nothing();
  fl_value step = fl_nothing();
  fl_value answer = fl_nothing();
  fl_value field = fl_nothing();
  fl_value bads = fl_nothing();
  fl_value *log = NULL;
  size_t log_count = 0;
  size_t log_room = 16;
  const char *path = NULL;
  const char *plan_name = "";
  double orders_limit = 10000;
  double max_steps = 10000000;
  double max_depth = 10000;
  bool pretty = false;
  char buffer[4096];
  char *base = NULL;
  char *full = NULL;
  char *text = NULL;
  size_t bytes = 0;
  int index = 0;
  int code = 0;

  memset(&host, 0, sizeof(host));
  host.read_files = true;
  host.write_files = true;
  host.net = true;
  host.clock = true;
  host.random = true;
  host.spawn = true;
  host.timeout_ms = 30000;
  host.next_link = 1;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--pretty") == 0) {
      pretty = true;
    } else if (strcmp(argv[index], "--in-dir") == 0) {
      host.in_dir = true;
    } else if (strcmp(argv[index], "--no-read") == 0) {
      host.read_files = false;
    } else if (strcmp(argv[index], "--no-write") == 0) {
      host.write_files = false;
    } else if (strcmp(argv[index], "--no-net") == 0) {
      host.net = false;
    } else if (strcmp(argv[index], "--no-clock") == 0) {
      host.clock = false;
    } else if (strcmp(argv[index], "--no-random") == 0) {
      host.random = false;
    } else if (strcmp(argv[index], "--no-spawn") == 0) {
      host.spawn = false;
    } else if (strcmp(argv[index], "--plan") == 0 && index + 1 < argc) {
      index += 1;
      plan_name = argv[index];
    } else if (strcmp(argv[index], "--seed") == 0 && index + 1 < argc) {
      index += 1;
      host.seeded = true;
      host.seed_state = (unsigned long)strtod(argv[index], NULL) & 0xffffffffUL;
      if (host.seed_state == 0) host.seed_state = 0x9e3779b9UL;
    } else if (strcmp(argv[index], "--timeout") == 0 && index + 1 < argc) {
      /* СРОК ХОЗЯИНА, в миллисекундах, и ключ этот обязан быть в обоих
         прогонщиках сразу: разойдись `flang io` на Node и `flang io` двоичный
         хотя бы одним ключом — и «то же самое, только быстрее» перестало бы
         быть правдой. Умолчание прежнее (30 000 мс), и довод к нему прежний:
         хозяин обязан ОТВЕТИТЬ, а зависший навсегда — не ответ. Ключ поднимает
         срок там, где работа честно длиннее: одна сборка релизного C идёт
         128 000 мс. */
      index += 1;
      host.timeout_ms = (long)strtod(argv[index], NULL);
      if (host.timeout_ms <= 0) {
        fputs("flang io: --timeout должен быть целым положительным числом миллисекунд\n", stderr);
        return 2;
      }
    } else if (strcmp(argv[index], "--max-orders") == 0 && index + 1 < argc) {
      index += 1;
      orders_limit = strtod(argv[index], NULL);
    } else if (strcmp(argv[index], "--max-steps") == 0 && index + 1 < argc) {
      index += 1;
      max_steps = strtod(argv[index], NULL);
    } else if (strcmp(argv[index], "--max-depth") == 0 && index + 1 < argc) {
      index += 1;
      max_depth = strtod(argv[index], NULL);
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang io: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang io: не назван файл. Пример: flang io план.flang\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(full);
    return 2;
  }

  /* ЗАМОК РЯДОМ СО ВХОДОМ подменяет чтение исходников зависимостей: их может не
     быть на диске вовсе. Испорченный замок — отказ, а не откат к чтению файлов:
     откат означал бы сборку не из замка. Стоит ДО `repl_cycle`, чтобы разборы
     проверки груза не пережили её ни одним байтом арены. */
  if (!lock_beside(full)) {
    free(text);
    free(full);
    return 1;
  }
  /* Пути поручений разрешаются относительно каталога ВХОДНОГО ФАЙЛА, а не
     текущего: план, лежащий рядом со своими данными, обязан находить их и
     будучи позванным откуда угодно. Правило то же, что у свидетеля. */
  host.root = repl_dirname(full);

  repl_cycle();
  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, full);
  strings_add(&texts, text, bytes);
  repl_imports_of(text, bytes, full, &queue);
  args[0] = repl_closure(&paths, &texts, &queue);
  args[1] = repl_value_say(full);
  args[2] = repl_value_say(plan_name);

  /* Снимок подключения (`kill -USR1`) печатает команду, которой служба поднята,
     — тем же способом и по той же причине, что у `flang run`. Служба идёт
     часами, и человек, подключившийся к чужому процессу, обязан узнать из
     снимка, ЧТО именно идёт, а не идти искать это в чужой истории оболочки. */
  {
    char repeat[1024];
    snprintf(repeat, sizeof(repeat), "flang io %s --plan \"%s\"", full, plan_name);
    fl_watch_repeat_set(repeat);
  }

  if (repl_call("План исходников", args, 3, &found) != FL_OK) {
    fputs("flang io: связывание не отработало\n", stderr);
    code = 3;
  } else if (val_field(found, "диагностики", &bads) && bads.tag == FL_LIST && bads.as.list.count > 0) {
    repl_bads list;
    size_t item = 0;
    bads_init(&list);
    for (item = 0; item < bads.as.list.count; item += 1) {
      bads_take(&list, bads.as.list.items[item]);
    }
    check_print_bads(&list, path, paths.count);
    bads_free(&list);
    code = 1;
  } else if (!val_field(found, "план", &plan) || !val_field(found, "программа", &program)) {
    fputs("flang io: поиск плана не вернул плана\n", stderr);
    code = 3;
  } else {
    bool has = false;
    val_field(plan, "есть", &field);
    has = field.tag == FL_FLAG && field.as.flag;
    if (!has) {
      /* «Плана с таким именем нет» — это код 3, а не 2, и это контракт
         свидетеля: двойка означает КРИВОЙ ВЫЗОВ (не назван файл, непонятный
         ключ), а здесь вызов правильный и до плана дело дошло. Места у такого
         отказа нет: указывать не на что. */
      char *why = NULL;
      char *what = NULL;
      val_field(plan, "код", &field);
      what = val_copy(field);
      val_field(plan, "сообщение", &field);
      why = val_copy(field);
      io_print_error(what, why, 0, 0, pretty);
      free(why);
      free(what);
      code = 3;
    } else {
      fl_value ready_args[3];
      ready_args[0] = program;
      ready_args[1] = fl_number(max_steps);
      ready_args[2] = fl_number(max_depth);
      if (repl_call("Подготовить программу", ready_args, 3, &ready) != FL_OK) {
        fputs("flang io: программа не подготовлена к вычислению\n", stderr);
        code = 3;
      } else {
        fl_value start_args[2];
        val_field(plan, "начало", &field);
        start_args[0] = ready;
        start_args[1] = field;
        if (repl_call("Начало плана", start_args, 2, &step) != FL_OK) {
          fputs("flang io: начальное состояние не посчиталось\n", stderr);
          code = 3;
        } else {
          code = io_loop(&host, ready, plan, step, &answer, &log, &log_count, &log_room, orders_limit, pretty);
        }
      }
    }
  }

  /* Вердикт печатается только у дошедшего до конца — так же, как у свидетеля:
     сдавшийся план отвечает в stderr отказом, а не половиной вердикта. */
  if (code == 0) {
    io_report(plan, answer, log, log_count, pretty);
  }
  io_close(&host);
  free(log);
  free(host.root);
  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  free(text);
  free(full);
  return code;
}


/* ═══════════════════ замок: `flang lock` и его груз ══════════════════════ */

/*
 * ЗАМОК, В КОТОРОМ ЛЕЖАТ САМИ ЗАВИСИМОСТИ, а не ссылки на них: схема 2,
 * `flang/src/lockfile.mjs` — там же довод целиком.
 *
 * Груз — ИСХОДНИК модуля строкой JSON, адрес — sha256 по нему, сжатия в формате
 * нет вовсе. Отсюда и цена этой команды у двоичного: sha256 (выше) плюс сборка
 * записи. Экранирования строки JSON здесь своего НЕТ — его делает «Печать
 * строки» из `flang/core/json.flang`, уже втащенная в замыкание.
 */
typedef struct {
  char *name;   /* имя модуля — из его же заголовка, а не из ссылки на него */
  char *path;   /* путь внутри замка: от каталога замка и всегда через `/` */
  char *source; /* груз: весь текст файла, байт в байт */
  size_t bytes;
  size_t functions;
  char address[65];
} lock_module;

typedef struct {
  lock_module *items;
  size_t count;
  size_t capacity;
} lock_modules;

static void lock_modules_init(lock_modules *list) {
  list->items = NULL;
  list->count = 0;
  list->capacity = 0;
}

static lock_module *lock_modules_push(lock_modules *list) {
  if (list->count == list->capacity) {
    list->capacity = list->capacity == 0 ? 8 : list->capacity * 2;
    list->items = repl_grow(list->items, list->capacity * sizeof(lock_module));
  }
  list->count += 1;
  return &list->items[list->count - 1];
}

static void lock_modules_free(lock_modules *list) {
  size_t at = 0;
  for (at = 0; at < list->count; at += 1) {
    free(list->items[at].name);
    free(list->items[at].path);
    free(list->items[at].source);
  }
  free(list->items);
  lock_modules_init(list);
}



/*
 * Разбор одного файла ради трёх вещей: как модуль зовут, сколько в нём функций
 * и куда он ссылается. Разбор здесь тот же, каким живут остальные команды
 * («Разбор исходника»), и второго выбора функции разбора не заводится: он
 * однажды разошёлся бы с первым.
 *
 * Импорты ставятся в очередь ПАРОЙ — путь и категория, — потому что имя модуля
 * берётся из его собственного заголовка, а категория нужна запасным ответом на
 * случай файла без заголовка.
 */
static bool lock_scan(const char *full, const char *text, size_t bytes, char **name, size_t *functions,
                      repl_strings *seen, repl_strings *queue_paths, repl_strings *queue_names) {
  fl_value args[2];
  fl_value parsed = fl_nothing();
  fl_value program = fl_nothing();
  fl_value diagnostics = fl_nothing();
  const fl_value *legacy = NULL;
  const fl_value *items = NULL;
  const char *utf8 = NULL;
  size_t got = 0;
  size_t count = 0;
  size_t index = 0;
  char *directory = NULL;

  args[0] = repl_value_text(text, bytes);
  args[1] = repl_value_list(NULL, 0);
  if (repl_call("Разбор исходника", args, 2, &parsed) != FL_OK) {
    return false;
  }
  /* Беды РАЗБОРА приезжают плоскими — «код», «сообщение», «строка», — а не
     записью «место», как беды связывания. Разбирается это здесь тем же
     способом, что и при загрузке файла в оболочку: у двух форм беды один
     печатник, но разные читатели, и путать их значило бы терять место. */
  if (val_field(parsed, "диагностики", &diagnostics) && diagnostics.tag == FL_LIST &&
      diagnostics.as.list.count > 0) {
    repl_bads bads;
    bads_init(&bads);
    for (index = 0; index < diagnostics.as.list.count; index += 1) {
      fl_value bad = diagnostics.as.list.items[index];
      fl_value code = fl_nothing();
      fl_value message = fl_nothing();
      fl_value line = fl_nothing();
      if (!val_field(bad, "код", &code) || !val_field(bad, "сообщение", &message)) {
        continue;
      }
      val_field(bad, "строка", &line);
      bads_push(&bads, val_copy(code), val_copy(message), true,
                line.tag == FL_NUMBER ? (size_t)line.as.number : 0, 0);
    }
    repl_print_bads(&bads, NULL, "файл", full, 0, 0);
    bads_free(&bads);
    return false;
  }
  if (!val_field(parsed, "программа", &program)) {
    return false;
  }

  *name = zn_field_text(program, "module", &utf8, &got) ? repl_dup(utf8, got) : NULL;
  zn_field_items(program, "functions", &items, &count);
  *functions = count;

  directory = repl_dirname(full);
  zn_field_items(program, "legacy", &legacy, &count);
  for (index = 0; index < count; index += 1) {
    const char *construct = NULL;
    size_t construct_bytes = 0;
    fl_value value = fl_nothing();
    const fl_value *imports = NULL;
    size_t imported = 0;
    size_t inner = 0;
    if (!zn_field_text(legacy[index], "construct", &construct, &construct_bytes)) {
      continue;
    }
    if (construct_bytes != 12 || memcmp(construct, "moduleHeader", 12) != 0) {
      continue;
    }
    if (!zn_field(legacy[index], "value", &value)) {
      continue;
    }
    zn_field_items(value, "imports", &imports, &imported);
    for (inner = 0; inner < imported; inner += 1) {
      const char *from = NULL;
      size_t from_bytes = 0;
      const char *category = NULL;
      size_t category_bytes = 0;
      char *relative = NULL;
      char *target = NULL;
      if (!zn_field_text(imports[inner], "from", &from, &from_bytes)) {
        continue;
      }
      relative = repl_dup(from, from_bytes);
      target = repl_resolve(directory, relative);
      free(relative);
      if (strings_has(seen, target, strlen(target))) {
        free(target);
        continue;
      }
      strings_say(seen, target);
      strings_say(queue_paths, target);
      if (zn_field_text(imports[inner], "category", &category, &category_bytes)) {
        strings_add(queue_names, category, category_bytes);
      } else {
        strings_say(queue_names, "");
      }
      free(target);
    }
  }
  free(directory);
  return true;
}

/*
 * Обход замыкания «использует» с чтением файлов — то же, что делает
 * `собратьЗамок` свидетеля, и в том же порядке: очередь в ширину от входа,
 * дедупликация при постановке, а не при снятии.
 *
 * `with_entry` разводит замок и пакет одним доводом: у ЗАМКА входной модуль в
 * груз не едет (замок отвечает «из чего собрана эта программа», а сама
 * программа лежит рядом), у ПАКЕТА едет — он и есть то, что отдают.
 */
static bool lock_collect(const char *entry, const char *root, const char *entry_name, bool with_entry,
                         lock_modules *out) {
  repl_strings seen;
  repl_strings queue_paths;
  repl_strings queue_names;
  size_t at = 0;
  bool ok = true;
  strings_init(&seen);
  strings_init(&queue_paths);
  strings_init(&queue_names);
  strings_say(&seen, entry);
  strings_say(&queue_paths, entry);
  strings_say(&queue_names, entry_name == NULL ? "" : entry_name);

  for (at = 0; at < queue_paths.count && ok; at += 1) {
    const char *file = queue_paths.items[at];
    char *name = NULL;
    size_t functions = 0;
    size_t bytes = 0;
    char *text = repl_read_file(file, &bytes);
    if (text == NULL) {
      fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", file);
      ok = false;
      break;
    }
    if (!lock_scan(file, text, bytes, &name, &functions, &seen, &queue_paths, &queue_names)) {
      free(text);
      free(name);
      ok = false;
      break;
    }
    if (at > 0 || with_entry) {
      lock_module *record = lock_modules_push(out);
      record->name = name != NULL ? name : repl_say(queue_names.items[at]);
      record->path = lock_path(root, file);
      record->source = text;
      record->bytes = bytes;
      record->functions = functions;
      lock_print(text, bytes, record->address);
    } else {
      free(name);
      free(text);
    }
  }

  strings_free(&seen);
  strings_free(&queue_paths);
  strings_free(&queue_names);
  return ok;
}

/*
 * Порядок записей — ПО ПУТИ, а не по обходу: замок обязан быть одним и тем же
 * файлом при одной и той же программе, иначе `git diff` шумит на пустом месте.
 * Сравнение побайтовое — у свидетеля это сравнение строк JavaScript, и на
 * путях из кодовых точек ниже 0x10000 оба порядка совпадают.
 */
static int lock_by_path(const void *left, const void *right) {
  const lock_module *l = left;
  const lock_module *r = right;
  return strcmp(l->path, r->path);
}

/** Печать замка: sha256 канонического JSON от списка пар «путь, адрес». */
static bool lock_seal(const lock_modules *modules, char *out) {
  repl_buf buf;
  size_t at = 0;
  bool ok = true;
  buf_init(&buf);
  buf_char(&buf, '[');
  for (at = 0; at < modules->count && ok; at += 1) {
    if (at > 0) {
      buf_char(&buf, ',');
    }
    buf_char(&buf, '[');
    ok = lock_json_text(modules->items[at].path, strlen(modules->items[at].path), &buf);
    buf_char(&buf, ',');
    ok = ok && lock_json_text(modules->items[at].address, 64, &buf);
    buf_char(&buf, ']');
  }
  buf_char(&buf, ']');
  if (ok) {
    lock_print(buf.data, buf.used, out);
  }
  buf_free(&buf);
  return ok;
}

/** Одна запись груза: имя, путь, число функций, адрес и сам исходник. */
static bool lock_write_module(const lock_module *module, repl_buf *out) {
  bool ok = true;
  buf_put(out, "{\"имя\":");
  ok = lock_json_text(module->name, strlen(module->name), out);
  buf_put(out, ",\"путь\":");
  ok = ok && lock_json_text(module->path, strlen(module->path), out);
  buf_put(out, ",\"функций\":");
  buf_number(out, module->functions);
  buf_put(out, ",\"адрес\":");
  ok = ok && lock_json_text(module->address, 64, out);
  buf_put(out, ",\"исходник\":");
  ok = ok && lock_json_text(module->source, module->bytes, out);
  buf_char(out, '}');
  return ok;
}

/**
 * `flang lock <файл> [--pretty]` — замок, в котором лежат сами зависимости.
 *
 * Печатается в stdout, как результат всякой другой команды: файл кладёт тот,
 * кто вызвал, — `flang lock программа.flang > flang.lock`. Своей записи на диск
 * команда не делает, и это тот же договор, что у свидетеля: у команд этого
 * инструмента ровно один выход, и второй способ создать файл был бы вторым
 * способом ошибиться.
 *
 * Входного модуля в грузе НЕТ: замок отвечает на вопрос «из чего собрана эта
 * программа», а сама программа лежит рядом с ним.
 */
static int lock_file(int argc, char **argv) {
  lock_modules modules;
  repl_buf out;
  char buffer[4096];
  char seal[65];
  const char *path = NULL;
  char *base = NULL;
  char *full = NULL;
  char *root = NULL;
  char *entry = NULL;
  bool pretty = false;
  int index = 0;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--pretty") == 0) {
      pretty = true;
    } else if (strcmp(argv[index], "-") == 0) {
      fputs("flang lock требует файл: со стандартного ввода импорты не разрешаются\n", stderr);
      return 2;
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang lock: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang lock: не назван файл. Пример: flang lock программа.flang\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  free(base);
  root = repl_dirname(full);

  repl_cycle();
  lock_modules_init(&modules);
  buf_init(&out);
  if (!lock_collect(full, root, NULL, false, &modules)) {
    code = 1;
  } else {
    qsort(modules.items, modules.count, sizeof(lock_module), lock_by_path);
    entry = lock_path(root, full);
    if (!lock_seal(&modules, seal)) {
      fputs("flang lock: печать замка не посчиталась\n", stderr);
      code = 1;
    } else {
      bool ok = true;
      size_t at = 0;
      buf_put(&out, "{\"схема\":");
      buf_number(&out, LOCK_SCHEMA);
      buf_put(&out, ",\"вход\":");
      ok = lock_json_text(entry, strlen(entry), &out);
      buf_put(&out, ",\"модули\":[");
      for (at = 0; at < modules.count && ok; at += 1) {
        if (at > 0) {
          buf_char(&out, ',');
        }
        ok = lock_write_module(&modules.items[at], &out);
      }
      buf_put(&out, "],\"печать\":");
      ok = ok && lock_json_text(seal, 64, &out);
      buf_char(&out, '}');
      if (!ok) {
        fputs("flang lock: замок не напечатался\n", stderr);
        code = 1;
      } else {
        if (pretty) {
          ast_pretty(out.data, out.used);
        } else {
          fwrite(out.data, 1, out.used, stdout);
        }
        fputc('\n', stdout);
        fflush(stdout);
      }
    }
  }

  buf_free(&out);
  lock_modules_free(&modules);
  free(entry);
  free(root);
  free(full);
  return code;
}


/* ══════════════════════════ пакет: `flang package` ═══════════════════════ */

/*
 * ПАКЕТ — ЭТО ЗАМОК, КОТОРОМУ ДАЛИ ИМЯ И ВЕРСИЮ (`flang/src/package.mjs`).
 *
 * Груз у них общий — те же записи «имя, путь, функций, адрес, исходник», — и
 * потому номер схемы у пакета двинут вместе с замком: сменился груз, сменились
 * оба. Своего сверх замка у пакета четыре вещи: имя, версия, источник и
 * ведомость доказанного, и все четыре ЗАВЕРЕНЫ печатью. Незаверенная версия —
 * это версия, которую правят одним `sed` и не ловят ничем: до того как печать
 * накрыла личность, подмена `"версия"` с 1.0.0 на 9.9.9 проходила проверку
 * молча.
 */
#define PACKAGE_SCHEMA 2
#define PACKAGE_DECL "flang.package"
#define PACKAGE_EXT ".flang-package"

/** Пакет опознаётся ТОЛЬКО по расширению пути импорта: имя тут не спрашивается. */
static bool pkg_is_package(const char *path) {
  const size_t bytes = strlen(path);
  const size_t tail = strlen(PACKAGE_EXT);
  return bytes >= tail && memcmp(path + bytes - tail, PACKAGE_EXT, tail) == 0;
}

/** Отказ пакета — кодом FLANG_PACKAGE, тем же, что у свидетеля. */
static bool pkg_refuse(const char *say) {
  repl_print_bad("FLANG_PACKAGE", say, NULL, NULL, 0, 0);
  return false;
}

typedef struct {
  char *name;
  char *version;
  char *source; /* NULL — источника в объявлении нет, и в пакет он не едет */
} pkg_decl;

static void pkg_decl_free(pkg_decl *decl) {
  free(decl->name);
  free(decl->version);
  free(decl->source);
  decl->name = NULL;
  decl->version = NULL;
  decl->source = NULL;
}

/** Одно поле объявления: непустая строка. Нет обязательного — отказ. */
static bool pkg_decl_field(fl_value node, const char *key, const char *where, bool required, char **out) {
  fl_value value = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  repl_buf say;
  *out = NULL;
  if (!zn_field(node, key, &value)) {
    if (!required) {
      return true;
    }
    buf_init(&say);
    buf_put(&say, where);
    buf_put(&say, ": нет поля «");
    buf_put(&say, key);
    buf_put(&say, "»");
    pkg_refuse(say.data);
    buf_free(&say);
    return false;
  }
  if (!zn_text(value, &utf8, &bytes) || bytes == 0) {
    buf_init(&say);
    buf_put(&say, where);
    buf_put(&say, ": поле «");
    buf_put(&say, key);
    buf_put(&say, "» — непустая строка");
    pkg_refuse(say.data);
    buf_free(&say);
    return false;
  }
  *out = repl_dup(utf8, bytes);
  return true;
}

/*
 * ОБЪЯВЛЕНИЕ РЯДОМ СО ВХОДНЫМ ФАЙЛОМ, а не ключи вызова, и причина не в
 * удобстве: ключ вызова живёт в истории оболочки, а объявление живёт в
 * репозитории автора и попадает в `git diff`. Версия, поднятая ключом,
 * поднялась бы молча.
 */
static bool pkg_declaration(const char *entry, const char *said, pkg_decl *out) {
  char *root = repl_dirname(entry);
  char *path = repl_join(root, PACKAGE_DECL);
  size_t bytes = 0;
  char *text = repl_read_file(path, &bytes);
  fl_value node = fl_nothing();
  size_t at = 0;
  bool ok = true;
  out->name = NULL;
  out->version = NULL;
  out->source = NULL;
  free(root);
  if (text == NULL) {
    repl_buf say;
    buf_init(&say);
    buf_put(&say, "рядом с ");
    buf_put(&say, said);
    buf_put(&say, " нет объявления " PACKAGE_DECL ": пакету нужны имя и версия, и берутся они оттуда, а не из вызова");
    ok = pkg_refuse(say.data);
    buf_free(&say);
    free(path);
    return ok;
  }
  if (!facts_json(text, &at, &node)) {
    repl_buf say;
    buf_init(&say);
    buf_put(&say, path);
    buf_put(&say, " не разбирается как JSON");
    ok = pkg_refuse(say.data);
    buf_free(&say);
  } else if (!val_is(node, "Значение записи")) {
    repl_buf say;
    buf_init(&say);
    buf_put(&say, path);
    buf_put(&say, ": ожидалась запись JSON");
    ok = pkg_refuse(say.data);
    buf_free(&say);
  } else {
    ok = pkg_decl_field(node, "имя", path, true, &out->name) &&
         pkg_decl_field(node, "версия", path, true, &out->version) &&
         pkg_decl_field(node, "источник", path, false, &out->source);
  }
  free(text);
  free(path);
  if (!ok) {
    pkg_decl_free(out);
  }
  return ok;
}

/*
 * ПЕЧАТЬ ПАКЕТА НАКРЫВАЕТ ВСЁ, ЧТО ОН О СЕБЕ ГОВОРИТ, а не только груз.
 *
 * Замок заверяет груз, и для него это правильно: он отвечает на вопрос «из чего
 * собрана эта программа». Пакет отвечает ещё и на вопрос «кто он такой», и
 * незаверенное имя с версией правились бы одним `sed`.
 */
static bool pkg_seal(const pkg_decl *decl, const char *entry, const lock_modules *modules, char *out) {
  repl_buf buf;
  size_t at = 0;
  bool ok = true;
  buf_init(&buf);
  buf_char(&buf, '[');
  ok = lock_json_text(decl->name, strlen(decl->name), &buf);
  buf_char(&buf, ',');
  ok = ok && lock_json_text(decl->version, strlen(decl->version), &buf);
  buf_char(&buf, ',');
  ok = ok && lock_json_text(decl->source == NULL ? "" : decl->source,
                            decl->source == NULL ? 0 : strlen(decl->source), &buf);
  buf_char(&buf, ',');
  ok = ok && lock_json_text(entry, strlen(entry), &buf);
  buf_put(&buf, ",[");
  for (at = 0; at < modules->count && ok; at += 1) {
    const lock_module *module = &modules->items[at];
    if (at > 0) {
      buf_char(&buf, ',');
    }
    buf_char(&buf, '[');
    ok = lock_json_text(module->path, strlen(module->path), &buf);
    buf_char(&buf, ',');
    ok = ok && lock_json_text(module->name, strlen(module->name), &buf);
    buf_char(&buf, ',');
    buf_number(&buf, module->functions);
    buf_char(&buf, ',');
    ok = ok && lock_json_text(module->address, 64, &buf);
    buf_char(&buf, ']');
  }
  buf_put(&buf, "]]");
  if (ok) {
    lock_print(buf.data, buf.used, out);
  }
  buf_free(&buf);
  return ok;
}

/*
 * ПАКЕТ НАД ПАКЕТОМ: груз вложенного переезжает КАК ЕСТЬ, вместе с адресом
 * каждого модуля, и потому остаётся тем же байт в байт. У того, кто собирает
 * пакет над чужим, исходников чужого нет и не будет — в этом весь смысл.
 *
 * Ставится ЦЕЛИКОМ, а не обходом импортов: у привезённого пакета замыкание уже
 * полное, обходить его второй раз нечем и незачем. Проверяется он при этом
 * полностью, теми же заставами, что и при чтении: испорченный вложенный пакет
 * обязан отвергнуться ЗДЕСЬ, а не всплыть у того, кому мы отдадим свой.
 */
static bool pkg_take_nested(const char *file, const char *root, lock_modules *out);

/*
 * Обход замыкания пакета: то же, что у замка, плюс две разницы. Входной модуль
 * в груз ЕДЕТ — он и есть то, что отдают. И встреченный `.flang-package`
 * раскрывается целиком, а не читается как исходник.
 */
static bool pkg_collect(const char *entry, const char *root, const char *entry_name, lock_modules *out,
                        repl_strings *own, char **entry_module) {
  repl_strings seen;
  repl_strings queue_paths;
  repl_strings queue_names;
  size_t at = 0;
  bool ok = true;
  strings_init(&seen);
  strings_init(&queue_paths);
  strings_init(&queue_names);
  strings_say(&seen, entry);
  strings_say(&queue_paths, entry);
  strings_say(&queue_names, entry_name);

  for (at = 0; at < queue_paths.count && ok; at += 1) {
    const char *file = queue_paths.items[at];
    char *name = NULL;
    size_t functions = 0;
    size_t bytes = 0;
    char *text = NULL;
    if (pkg_is_package(file)) {
      ok = pkg_take_nested(file, root, out);
      continue;
    }
    text = repl_read_file(file, &bytes);
    if (text == NULL) {
      fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", file);
      ok = false;
      break;
    }
    if (!lock_scan(file, text, bytes, &name, &functions, &seen, &queue_paths, &queue_names)) {
      free(text);
      free(name);
      ok = false;
      break;
    }
    if (at == 0 && entry_module != NULL) {
      /* Имя ВХОДНОГО модуля берётся из его заголовка, а не из запасного: пакет,
         названный в объявлении иначе, чем модуль, обязан отвергнуться, и
         «называется никак» — законный ответ. */
      *entry_module = name != NULL ? repl_say(name) : NULL;
    }
    {
      lock_module *record = lock_modules_push(out);
      record->name = name != NULL ? name : repl_say(queue_names.items[at]);
      record->path = lock_path(root, file);
      record->source = text;
      record->bytes = bytes;
      record->functions = functions;
      lock_print(text, bytes, record->address);
    }
    /* СВОИ ИМЕНА берутся из одиночного разбора входа: в слитой программе своё от
       привезённого не отличить, а ведомость обещает за то, что написано в этом
       модуле, и ни строкой больше. */
    if (at == 0 && own != NULL) {
      fl_value args[2];
      fl_value parsed = fl_nothing();
      fl_value program = fl_nothing();
      const fl_value *items = NULL;
      size_t count = 0;
      size_t index = 0;
      args[0] = repl_value_text(text, bytes);
      args[1] = repl_value_list(NULL, 0);
      if (repl_call("Разбор исходника", args, 2, &parsed) == FL_OK && val_field(parsed, "программа", &program)) {
        zn_field_items(program, "functions", &items, &count);
        for (index = 0; index < count; index += 1) {
          const char *utf8 = NULL;
          size_t got = 0;
          if (zn_field_text(items[index], "name", &utf8, &got)) {
            strings_add(own, utf8, got);
          }
        }
      }
    }
  }

  strings_free(&seen);
  strings_free(&queue_paths);
  strings_free(&queue_names);
  return ok;
}

/*
 * Открытый пакет: разобранный JSON плюс то, что он говорит о себе.
 *
 * Общий у двух читателей — у сборки пакета над пакетом и у ПОДКЛЮЧЕНИЯ пакета к
 * программе, — и общий намеренно: читатель, проверяющий три заставы из четырёх,
 * был бы дырой ровно в том месте, где её никто не ищет.
 */
typedef struct {
  fl_value node;
  const fl_value *items;
  size_t count;
  char *name;
  char *version;
  char *source;
  char *entry;
} pkg_open;

static void pkg_open_free(pkg_open *pkg) {
  free(pkg->name);
  free(pkg->version);
  free(pkg->source);
  free(pkg->entry);
  pkg->name = NULL;
  pkg->version = NULL;
  pkg->source = NULL;
  pkg->entry = NULL;
  pkg->items = NULL;
  pkg->count = 0;
}

/*
 * Прочитать пакет и проверить всё, что он о себе говорит.
 *
 * ПАКЕТ ПРЕЖНЕЙ СХЕМЫ отвергается по НОМЕРУ, раньше всякого разбора груза, и
 * текст отказа говорит, что делать: груз схемы 1 был base64 от brotli, и
 * попытка прочесть его как исходник дала бы не отказ, а мусор под видом кода.
 * Печать сверяется ДО груза и накрывает имя, версию, источник, вход и весь
 * список: незаверенная версия — это версия, которую правят одним `sed`.
 */
static bool pkg_open_file(const char *file, pkg_open *pkg) {
  size_t bytes = 0;
  char *text = repl_read_file(file, &bytes);
  fl_value schema = fl_nothing();
  fl_value modules = fl_nothing();
  const char *utf8 = NULL;
  size_t utf8_bytes = 0;
  size_t read = 0;
  double number = 0;
  repl_buf say;
  bool ok = true;

  pkg->node = fl_nothing();
  pkg->items = NULL;
  pkg->count = 0;
  pkg->name = NULL;
  pkg->version = NULL;
  pkg->source = NULL;
  pkg->entry = NULL;

  if (text == NULL) {
    buf_init(&say);
    buf_put(&say, "пакет ");
    buf_put(&say, file);
    buf_put(&say, " не прочитан");
    ok = pkg_refuse(say.data);
    buf_free(&say);
    return ok;
  }
  if (!facts_json(text, &read, &pkg->node)) {
    buf_init(&say);
    buf_put(&say, "пакет ");
    buf_put(&say, file);
    buf_put(&say, " не прочитан: не разбирается как JSON");
    ok = pkg_refuse(say.data);
    buf_free(&say);
    free(text);
    return ok;
  }
  free(text);

  if (!zn_field(pkg->node, "схема", &schema) || !zn_number(schema, &number) ||
      number != (double)PACKAGE_SCHEMA) {
    buf_init(&say);
    if (!zn_field(pkg->node, "схема", &schema)) {
      buf_put(&say, "пакет без номера схемы: прежним форматом собран или испорчен, а нужна схема ");
      buf_number(&say, PACKAGE_SCHEMA);
    } else {
      fl_value printed = fl_nothing();
      buf_put(&say, "пакет собран прежним форматом: схема ");
      if (repl_call("Печать значения", &schema, 1, &printed) == FL_OK && val_text(printed, &utf8, &utf8_bytes)) {
        buf_add(&say, utf8, utf8_bytes);
      } else {
        buf_put(&say, "?");
      }
      buf_put(&say, ", а нужна ");
      buf_number(&say, PACKAGE_SCHEMA);
    }
    buf_put(&say, ". Пересоберите: flang package <входной файл> > <имя>" PACKAGE_EXT);
    ok = pkg_refuse(say.data);
    buf_free(&say);
    return ok;
  }
  if (!zn_field_text(pkg->node, "имя", &utf8, &utf8_bytes) || utf8_bytes == 0) {
    return pkg_refuse("у пакета нет имени");
  }
  pkg->name = repl_dup(utf8, utf8_bytes);
  if (!zn_field_text(pkg->node, "версия", &utf8, &utf8_bytes) || utf8_bytes == 0) {
    buf_init(&say);
    buf_put(&say, "у пакета «");
    buf_put(&say, pkg->name);
    buf_put(&say, "» нет версии");
    ok = pkg_refuse(say.data);
    buf_free(&say);
    pkg_open_free(pkg);
    return ok;
  }
  pkg->version = repl_dup(utf8, utf8_bytes);
  if (zn_field_text(pkg->node, "источник", &utf8, &utf8_bytes)) {
    pkg->source = repl_dup(utf8, utf8_bytes);
  }
  if (!zn_field_text(pkg->node, "вход", &utf8, &utf8_bytes)) {
    pkg_open_free(pkg);
    return pkg_refuse("у пакета нет входного модуля");
  }
  pkg->entry = repl_dup(utf8, utf8_bytes);
  if (!zn_field(pkg->node, "модули", &modules) || !zn_items(modules, &pkg->items, &pkg->count)) {
    buf_init(&say);
    buf_put(&say, "в пакете «");
    buf_put(&say, pkg->name);
    buf_put(&say, "» нет списка модулей");
    ok = pkg_refuse(say.data);
    buf_free(&say);
    pkg_open_free(pkg);
    return ok;
  }

  /* ПЕЧАТЬ СВЕРЯЕТСЯ РАНЬШЕ ГРУЗА и по тому же списку, каким она считалась. */
  {
    pkg_decl said;
    lock_modules read_modules;
    char seal[65];
    const char *told = NULL;
    size_t told_bytes = 0;
    size_t at = 0;
    said.name = pkg->name;
    said.version = pkg->version;
    said.source = pkg->source;
    lock_modules_init(&read_modules);
    for (at = 0; at < pkg->count && ok; at += 1) {
      lock_module *record = lock_modules_push(&read_modules);
      fl_value number_node = fl_nothing();
      double got = 0;
      record->name = NULL;
      record->path = NULL;
      record->source = NULL;
      record->bytes = 0;
      record->functions = 0;
      record->address[0] = '\0';
      ok = zn_field_text(pkg->items[at], "имя", &utf8, &utf8_bytes);
      if (ok) {
        record->name = repl_dup(utf8, utf8_bytes);
        ok = zn_field_text(pkg->items[at], "путь", &utf8, &utf8_bytes);
      }
      if (ok) {
        record->path = repl_dup(utf8, utf8_bytes);
        ok = zn_field_text(pkg->items[at], "адрес", &utf8, &utf8_bytes) && utf8_bytes == 64;
      }
      if (ok) {
        memcpy(record->address, utf8, 64);
        record->address[64] = '\0';
        if (zn_field(pkg->items[at], "функций", &number_node) && zn_number(number_node, &got)) {
          record->functions = (size_t)got;
        }
      }
    }
    ok = ok && pkg_seal(&said, pkg->entry, &read_modules, seal);
    lock_modules_free(&read_modules);
    if (!ok || !zn_field_text(pkg->node, "печать", &told, &told_bytes) || told_bytes != 64 ||
        memcmp(told, seal, 64) != 0) {
      buf_init(&say);
      buf_put(&say, "печать пакета «");
      buf_put(&say, pkg->name);
      buf_put(&say, "» не сходится: пакет правлен или испорчен");
      ok = pkg_refuse(say.data);
      buf_free(&say);
      pkg_open_free(pkg);
      return ok;
    }
  }
  return true;
}

/*
 * Куда ложится модуль пакета: входной — на место САМОГО ФАЙЛА пакета, прочие —
 * рядом с ним. На пакет ссылаются `использует «Имя» из "sets.flang-package"`, и
 * разрешение импорта обязано попасть ровно в эту запись.
 */
static char *pkg_module_place(const char *file, const pkg_open *pkg, const char *inner) {
  char *where = NULL;
  char *full = NULL;
  if (strcmp(inner, pkg->entry) == 0) {
    return repl_say(file);
  }
  where = repl_dirname(file);
  full = repl_resolve(where, inner);
  free(where);
  return full;
}

static bool pkg_take_nested(const char *file, const char *root, lock_modules *out) {
  pkg_open pkg;
  size_t at = 0;
  bool ok = pkg_open_file(file, &pkg);
  for (at = 0; at < pkg.count && ok; at += 1) {
    char *inner = NULL;
    char *source_text = NULL;
    size_t source_bytes = 0;
    repl_buf label;
    buf_init(&label);
    buf_put(&label, "пакете «");
    buf_put(&label, pkg.name);
    buf_char(&label, ' ');
    buf_put(&label, pkg.version);
    buf_put(&label, "»");
    ok = lock_take_module(true, file, pkg.items[at], label.data, &inner, &source_text, &source_bytes);
    buf_free(&label);
    if (!ok) {
      free(inner);
      free(source_text);
      break;
    }
    {
      char *full = pkg_module_place(file, &pkg, inner);
      char *rebased = lock_path(root, full);
      size_t index = 0;
      bool already = false;
      for (index = 0; index < out->count; index += 1) {
        if (strcmp(out->items[index].path, rebased) == 0) {
          already = true;
          break;
        }
      }
      if (already) {
        free(rebased);
        free(source_text);
      } else {
        lock_module *record = lock_modules_push(out);
        const char *told = NULL;
        size_t told_bytes = 0;
        fl_value number_node = fl_nothing();
        double got = 0;
        record->path = rebased;
        record->source = source_text;
        record->bytes = source_bytes;
        record->functions = 0;
        record->name = zn_field_text(pkg.items[at], "имя", &told, &told_bytes) ? repl_dup(told, told_bytes)
                                                                              : repl_say("");
        if (zn_field(pkg.items[at], "функций", &number_node) && zn_number(number_node, &got)) {
          record->functions = (size_t)got;
        }
        if (zn_field_text(pkg.items[at], "адрес", &told, &told_bytes) && told_bytes == 64) {
          memcpy(record->address, told, 64);
        }
        record->address[64] = '\0';
      }
      free(full);
      free(inner);
    }
  }
  pkg_open_free(&pkg);
  return ok;
}

/*
 * ПАКЕТЫ, НА КОТОРЫЕ ССЫЛАЕТСЯ ПРОГРАММА, — `использует «Имя» из "имя.flang-package"`.
 *
 * Опознаются по расширению пути импорта, и только по нему: имя модуля тут не
 * спрашивается ни разу. Ребро импорта даёт ПУТЬ, путь даёт файл пакета, файл
 * даёт исходник — и то, что приехало, есть ровно то, на что сослались. Поиск по
 * имени привёз бы чужое тело под правильной вывеской, и побайтовая сверка этого
 * бы не заметила: сверять было бы не с чем.
 *
 * Груз ложится в тот же склад, что и груз замка, и ложится ПОСЛЕ него: замок
 * собран по этой самой программе и потому точнее. Порядок здесь и есть правило
 * «замок поверх пакетов» — искать в складе начинают с начала.
 */
static bool pkg_beside(const char *entry) {
  repl_strings queue;
  repl_strings seen;
  size_t bytes = 0;
  char *text = repl_read_file(entry, &bytes);
  size_t at = 0;
  bool ok = true;

  if (text == NULL) {
    return true;
  }
  strings_init(&queue);
  strings_init(&seen);
  {
    repl_strings all;
    size_t index = 0;
    strings_init(&all);
    repl_imports_of(text, bytes, entry, &all);
    for (index = 0; index < all.count; index += 1) {
      if (pkg_is_package(all.items[index])) {
        strings_say(&queue, all.items[index]);
      }
    }
    strings_free(&all);
  }
  free(text);
  if (queue.count == 0) {
    strings_free(&queue);
    strings_free(&seen);
    repl_edges_forget();
    return true;
  }

  for (at = 0; at < queue.count && ok; at += 1) {
    /* Копия, а не указатель в очередь: очередь растёт ниже по ходу этого же
       витка, и `realloc` унёс бы строку из-под ног. */
    char *file = repl_say(queue.items[at]);
    pkg_open pkg;
    size_t index = 0;
    size_t first = lock_cargo_paths.count;
    if (strings_has(&seen, file, strlen(file))) {
      free(file);
      continue;
    }
    strings_say(&seen, file);
    /* Пакет, уже приехавший грузом другого пакета, на диске не ищется: его там
       нет и не должно быть — в этом весь смысл пакета над пакетом. */
    if (lock_cargo_open) {
      bool inside = false;
      for (index = 0; index < lock_cargo_paths.count; index += 1) {
        if (strcmp(lock_cargo_paths.items[index], file) == 0) {
          inside = true;
          break;
        }
      }
      if (inside) {
        free(file);
        continue;
      }
    }
    ok = pkg_open_file(file, &pkg);
    for (index = 0; index < pkg.count && ok; index += 1) {
      char *inner = NULL;
      char *source_text = NULL;
      size_t source_bytes = 0;
      char *place = NULL;
      size_t already = 0;
      bool found = false;
      repl_buf label;
      buf_init(&label);
      buf_put(&label, "пакете «");
      buf_put(&label, pkg.name);
      buf_char(&label, ' ');
      buf_put(&label, pkg.version);
      buf_put(&label, "»");
      ok = lock_take_module(true, file, pkg.items[index], label.data, &inner, &source_text, &source_bytes);
      buf_free(&label);
      if (!ok) {
        free(inner);
        free(source_text);
        break;
      }
      place = pkg_module_place(file, &pkg, inner);
      for (already = 0; already < lock_cargo_paths.count; already += 1) {
        if (strcmp(lock_cargo_paths.items[already], place) == 0) {
          found = true;
          break;
        }
      }
      if (found) {
        /* СВЕРЯЕТСЯ СОДЕРЖИМОЕ, а не имя: два пакета вправе везти одну и ту же
           `lists.flang` — это ромб, и он разрешается сам собой, когда обе
           стороны везут одно и то же. Разное содержимое на одном пути — это две
           версии одной библиотеки, а их в flang не бывает. */
        if (lock_cargo_texts.sizes[already] != source_bytes ||
            memcmp(lock_cargo_texts.items[already], source_text, source_bytes) != 0) {
          repl_buf say;
          buf_init(&say);
          buf_put(&say, "путь ");
          buf_put(&say, place);
          buf_put(&say, " привезли два пакета с разным содержимым: «");
          buf_put(&say, lock_cargo_from.count > already ? lock_cargo_from.items[already] : "?");
          buf_put(&say, "» и «");
          buf_put(&say, pkg.name);
          buf_char(&say, ' ');
          buf_put(&say, pkg.version);
          buf_put(&say,
                  "». Двух версий одной библиотеки в одной программе не бывает: поднимите обе стороны до одной "
                  "версии");
          ok = pkg_refuse(say.data);
          buf_free(&say);
        }
      } else {
        repl_buf label2;
        buf_init(&label2);
        buf_put(&label2, pkg.name);
        buf_char(&label2, ' ');
        buf_put(&label2, pkg.version);
        strings_say(&lock_cargo_paths, place);
        strings_add(&lock_cargo_texts, source_text, source_bytes);
        strings_say(&lock_cargo_from, label2.data);
        buf_free(&label2);
        lock_cargo_open = true;
      }
      free(place);
      free(inner);
      free(source_text);
    }
    /* Импорты привезённых модулей обходятся ПОСЛЕ того, как весь пакет лёг в
       склад, а не по ходу: пакет над пакетом везёт и верхний модуль, и
       вложенный файл пакета, и первый ссылается на второй. Обход по ходу
       поставил бы вложенный файл в очередь раньше, чем он лёг, и его пошли бы
       искать на диске — где его нет и не должно быть. */
    for (index = first; index < lock_cargo_paths.count && ok; index += 1) {
      repl_strings all;
      size_t inner = 0;
      strings_init(&all);
      repl_imports_of(lock_cargo_texts.items[index], lock_cargo_texts.sizes[index], lock_cargo_paths.items[index],
                      &all);
      for (inner = 0; inner < all.count; inner += 1) {
        if (pkg_is_package(all.items[inner]) && !strings_has(&seen, all.items[inner], strlen(all.items[inner]))) {
          strings_say(&queue, all.items[inner]);
        }
      }
      strings_free(&all);
    }
    pkg_open_free(&pkg);
    free(file);
  }

  strings_free(&queue);
  strings_free(&seen);
  /* Рёбра ввоза здесь собирались попутно и никому не нужны: считает по ним
     только замыкание, а склад пакетов ходит своим обходом. */
  repl_edges_forget();
  return ok;
}

/*
 * ВЕДОМОСТЬ ПАКЕТА — что ядро сказало про функции автора, и ни строкой больше.
 *
 * Считается из того же, из чего печатается `flang check --proof`: обязательства
 * и вердикты. В пакет едет СПРАВКОЙ: тот, кто пакет подключил, доказывает всё
 * заново. Пригодна она для одного — посмотреть, что обещает библиотека, ДО того
 * как на неё сослаться.
 *
 * Строк своих здесь нет ни у чего, кроме сборки JSON: обязательства считает
 * `flang/self/obligations.flang`, вердикты — `flang/self/proofterm.flang`, обе
 * в замыкании. Второго счёта не заводится: два набора вердиктов спорили бы
 * между собой, а спорить о доказанном должны люди, а не две реализации.
 */
static bool pkg_ledger(fl_value program, const repl_strings *own, repl_buf *out) {
  fl_value total = fl_nothing();
  fl_value descents_in = fl_nothing();
  fl_value descents = fl_nothing();
  fl_value svod = fl_nothing();
  fl_value obligations = fl_nothing();
  fl_value runs = fl_nothing();
  fl_value verified = fl_nothing();
  fl_value checked = fl_nothing();
  fl_value args[3];
  size_t at = 0;
  size_t written = 0;
  bool ok = true;

  /* Отметки анализа («Отметить меры», «Отметить доказанные» — свидетель кладёт
     их в `loadProgram`) здесь НЕ ставятся, и это замер, а не пропуск: с ними и
     без них ведомость на семи пакетах вышла одна и та же, байт в байт. Правка,
     которая ничего не держит, — это две лишние строки в доверенном основании. */
  if (repl_call("Проверить тотальность", &program, 1, &total) != FL_OK ||
      !val_field(total, "спуски", &descents_in) ||
      repl_call("Спуски узлами", &descents_in, 1, &descents) != FL_OK) {
    return false;
  }
  args[0] = program;
  args[1] = descents;
  if (repl_call("Обязательства", args, 2, &svod) != FL_OK) {
    return false;
  }
  args[0] = svod;
  args[1] = repl_value_say("obligations");
  if (repl_call("Элементы поля", args, 2, &obligations) != FL_OK || obligations.tag != FL_LIST) {
    return false;
  }
  if (repl_call("Прогоны для ядра", &program, 1, &runs) != FL_OK) {
    return false;
  }
  args[0] = program;
  args[1] = obligations;
  args[2] = runs;
  if (repl_call("Проверить доказательства", args, 3, &verified) != FL_OK) {
    return false;
  }
  args[0] = verified;
  args[1] = repl_value_say("checked");
  if (repl_call("Элементы поля", args, 2, &checked) != FL_OK || checked.tag != FL_LIST) {
    return false;
  }

  buf_char(out, '[');
  for (at = 0; at < obligations.as.list.count && ok; at += 1) {
    fl_value node = obligations.as.list.items[at];
    const char *kind = NULL;
    size_t kind_bytes = 0;
    const char *of = NULL;
    size_t of_bytes = 0;
    const char *name = NULL;
    size_t name_bytes = 0;
    bool named = false;
    const char *verdict = NULL;
    size_t verdict_bytes = 0;
    size_t index = 0;
    if (!zn_field_text(node, "kind", &kind, &kind_bytes) || kind_bytes != 13 ||
        memcmp(kind, "postcondition", 13) != 0) {
      continue;
    }
    if (!zn_field_text(node, "of", &of, &of_bytes)) {
      continue;
    }
    if (own->count > 0 && !strings_has(own, of, of_bytes)) {
      continue;
    }
    named = zn_field_text(node, "name", &name, &name_bytes);
    /* Вердикт сводится по ПАРЕ «чья функция, имя утверждения», как у свидетеля,
       и берётся ПОСЛЕДНИЙ совпавший: он строит карту и перезаписывает её. */
    for (index = 0; index < checked.as.list.count; index += 1) {
      fl_value row = checked.as.list.items[index];
      const char *row_of = NULL;
      size_t row_of_bytes = 0;
      const char *row_name = NULL;
      size_t row_name_bytes = 0;
      const char *row_verdict = NULL;
      size_t row_verdict_bytes = 0;
      if (!zn_field_text(row, "of", &row_of, &row_of_bytes) || row_of_bytes != of_bytes ||
          memcmp(row_of, of, of_bytes) != 0) {
        continue;
      }
      if (!zn_field_text(row, "name", &row_name, &row_name_bytes)) {
        row_name_bytes = 0;
      }
      if (row_name_bytes != (named ? name_bytes : 0) ||
          (row_name_bytes > 0 && memcmp(row_name, name, row_name_bytes) != 0)) {
        continue;
      }
      if (zn_field_text(row, "verdict", &row_verdict, &row_verdict_bytes)) {
        verdict = row_verdict;
        verdict_bytes = row_verdict_bytes;
      } else {
        verdict = NULL;
      }
    }
    if (written > 0) {
      buf_char(out, ',');
    }
    written += 1;
    buf_put(out, "{\"функция\":");
    ok = lock_json_text(of, of_bytes, out);
    buf_put(out, ",\"утверждение\":");
    if (named) {
      ok = ok && lock_json_text(name, name_bytes, out);
    } else {
      buf_put(out, "null");
    }
    buf_put(out, ",\"сила\":");
    if (verdict != NULL) {
      ok = ok && lock_json_text(verdict, verdict_bytes, out);
    } else {
      buf_put(out, "null");
    }
    buf_char(out, '}');
  }
  buf_char(out, ']');
  return ok;
}

/**
 * `flang package <файл> [--pretty]` — пакет: груз замка плюс имя, версия,
 * источник и ведомость доказанного.
 *
 * ПРОВЕРКА СТОИТ ДО СБОРКИ, как у печати в целевой язык: пакет — это обещание,
 * а обещать за непроверенное нельзя. Отказ проверки — отказ команды, а не пакет
 * с припиской «зато собрался».
 */
static int package_file(int argc, char **argv) {
  lock_modules modules;
  pkg_decl decl;
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  repl_strings own;
  repl_strings proven;
  repl_bads bads;
  repl_buf out;
  repl_buf ledger;
  fl_value program = fl_nothing();
  char buffer[4096];
  char seal[65];
  const char *path = NULL;
  char *base = NULL;
  char *full = NULL;
  char *root = NULL;
  char *entry = NULL;
  char *entry_module = NULL;
  char *text = NULL;
  size_t bytes = 0;
  bool pretty = false;
  bool has_program = false;
  bool ok = true;
  int index = 0;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--pretty") == 0) {
      pretty = true;
    } else if (strcmp(argv[index], "-") == 0) {
      fputs("flang package требует файл: со стандартного ввода импорты не разрешаются\n", stderr);
      return 2;
    } else if (argv[index][0] != '-' && path == NULL) {
      path = argv[index];
    } else {
      fprintf(stderr, "flang package: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (path == NULL) {
    fputs("flang package: не назван файл. Пример: flang package модуль.flang\n", stderr);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  full = repl_resolve(base, path);
  text = repl_read_file(full, &bytes);
  free(base);
  if (text == NULL) {
    fprintf(stderr, "FLANG_CLI: не прочитан файл %s\n", path);
    free(full);
    return 2;
  }
  root = repl_dirname(full);

  /* Замок и пакеты рядом — та же подмена, что у остальных команд: пакет над
     пакетом собирается там, где исходников вложенного на диске нет. */
  if (!lock_beside(full)) {
    free(text);
    free(root);
    free(full);
    return 1;
  }
  if (!pkg_declaration(full, path, &decl)) {
    free(text);
    free(root);
    free(full);
    return 1;
  }

  /* ── проверка перед сборкой: та же дорога, что у `flang check` ── */
  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_init(&own);
  strings_init(&proven);
  bads_init(&bads);
  lock_modules_init(&modules);
  buf_init(&out);
  buf_init(&ledger);
  strings_say(&paths, full);
  strings_add(&texts, text, bytes);
  repl_imports_of(text, bytes, full, &queue);
  ok = repl_check_sources(repl_closure(&paths, &texts, &queue), full, &bads, &program, &has_program, &proven, true, true, true,
                          NULL, NULL, NULL, NULL);
  if (!ok || bads.count > 0) {
    repl_buf say;
    buf_init(&say);
    buf_put(&say, path);
    buf_put(&say, " не проходит проверку: пакет собирается только из проверенного");
    pkg_refuse(say.data);
    buf_free(&say);
    code = 1;
  }

  if (code == 0) {
    if (!pkg_collect(full, root, decl.name, &modules, &own, &entry_module)) {
      code = 1;
    } else if (!pkg_ledger(program, &own, &ledger)) {
      fputs("flang package: отчёт о доказательствах не посчитался\n", stderr);
      code = 1;
    } else {
      const char *own_name = entry_module;
      if (own_name == NULL || strcmp(own_name, decl.name) != 0) {
        repl_buf say;
        buf_init(&say);
        buf_put(&say, "в " PACKAGE_DECL " пакет назван «");
        buf_put(&say, decl.name);
        buf_put(&say, "», а модуль в ");
        buf_put(&say, path);
        buf_put(&say, " называется ");
        if (own_name == NULL || own_name[0] == '\0') {
          buf_put(&say, "никак");
        } else {
          buf_put(&say, "«");
          buf_put(&say, own_name);
          buf_put(&say, "»");
        }
        pkg_refuse(say.data);
        buf_free(&say);
        code = 1;
      }
    }
  }

  if (code == 0) {
    entry = lock_path(root, full);
    qsort(modules.items, modules.count, sizeof(lock_module), lock_by_path);
    if (!pkg_seal(&decl, entry, &modules, seal)) {
      fputs("flang package: печать пакета не посчиталась\n", stderr);
      code = 1;
    } else {
      size_t at = 0;
      ok = true;
      buf_put(&out, "{\"схема\":");
      buf_number(&out, PACKAGE_SCHEMA);
      buf_put(&out, ",\"имя\":");
      ok = lock_json_text(decl.name, strlen(decl.name), &out);
      buf_put(&out, ",\"версия\":");
      ok = ok && lock_json_text(decl.version, strlen(decl.version), &out);
      buf_put(&out, ",\"вход\":");
      ok = ok && lock_json_text(entry, strlen(entry), &out);
      buf_put(&out, ",\"модули\":[");
      for (at = 0; at < modules.count && ok; at += 1) {
        if (at > 0) {
          buf_char(&out, ',');
        }
        ok = lock_write_module(&modules.items[at], &out);
      }
      buf_put(&out, "],\"ведомость\":");
      buf_add(&out, ledger.data, ledger.used);
      /* Источник ставится ПОСЛЕ ведомости и только если он объявлен: пустая
         строка в JSON читается как «источник забыли», а не «его не было». */
      if (decl.source != NULL) {
        buf_put(&out, ",\"источник\":");
        ok = ok && lock_json_text(decl.source, strlen(decl.source), &out);
      }
      buf_put(&out, ",\"печать\":");
      ok = ok && lock_json_text(seal, 64, &out);
      buf_char(&out, '}');
      if (!ok) {
        fputs("flang package: пакет не напечатался\n", stderr);
        code = 1;
      } else {
        if (pretty) {
          ast_pretty(out.data, out.used);
        } else {
          fwrite(out.data, 1, out.used, stdout);
        }
        fputc('\n', stdout);
        fflush(stdout);
      }
    }
  }

  buf_free(&out);
  buf_free(&ledger);
  bads_free(&bads);
  lock_modules_free(&modules);
  pkg_decl_free(&decl);
  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  strings_free(&own);
  strings_free(&proven);
  free(entry);
  free(entry_module);
  free(root);
  free(text);
  free(full);
  return code;
}

/* ══════════════════════════ новый пакет: `flang new` ══════════════════════ */

/*
 * СТРУКТУРА, КОТОРУЮ КОМАНДА ВОСПРОИЗВОДИТ, — та же, что в `fspec/` дерева:
 * `guard.flang` и `policy.flang` копируются с диска дословно (это они и
 * проверяют потом сами себя — план, который меняться не должен от пакета к
 * пакету), а `settings.txt`, спека-пример, слепок, манифест и README
 * складываются заново под названное имя. Ту же проверку — «Имя пакета
 * допустимо» — самостоятельно доказывает `flang/self/cli.flang`; здесь она
 * продублирована ровно так же, как строгий разбор `--предел-шагов` у
 * `human_steps`.
 */
#define NEW_MANIFEST "flang.package"
#define NEW_TEMPLATE_ENV "FLANG_FSPEC_TEMPLATE_DIR"

static const char *const NEW_RESERVED[] = {"check", "ast",  "tokens",  "run",     "test", "facts", "emit",
                                           "io",    "repl", "lock",    "package", "new",  "lsp",   "help",
                                           "version", "flang", "fspec"};
#define NEW_RESERVED_COUNT (sizeof(NEW_RESERVED) / sizeof(NEW_RESERVED[0]))

/** Запрещённые куски имени пакета — та же строка, что «Запрещённые куски
    имени пакета» в cli.flang. */
static const char *const NEW_FORBIDDEN[] = {" ", "\t", "\n", "/", "\\", "\"", "«", "»"};
#define NEW_FORBIDDEN_COUNT (sizeof(NEW_FORBIDDEN) / sizeof(NEW_FORBIDDEN[0]))

/** Дословно та же проверка, что «Имя пакета допустимо» в cli.flang: имя
    остаётся русским (или любой другой письменностью языка) настолько же
    свободно, насколько остальной flang — запрещены только куски, которые
    ломают путь на диске, JSON манифеста или флаговый разбор. */
static bool new_name_ok(const char *name) {
  size_t index = 0;
  if (name == NULL || name[0] == '\0') {
    return false;
  }
  if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) {
    return false;
  }
  for (index = 0; index < NEW_FORBIDDEN_COUNT; index += 1) {
    if (strstr(name, NEW_FORBIDDEN[index]) != NULL) {
      return false;
    }
  }
  for (index = 0; index < NEW_RESERVED_COUNT; index += 1) {
    if (strcmp(name, NEW_RESERVED[index]) == 0) {
      return false;
    }
  }
  return true;
}

static bool new_refuse(const char *say) {
  repl_print_bad("FLANG_NEW", say, NULL, NULL, 0, 0);
  return false;
}

/**
 * Каталог с образцом `fspec/`: сперва `$FLANG_FSPEC_TEMPLATE_DIR`, иначе
 * `<каталог двоичного>/../fspec` — на дереве исходников это и есть корневой
 * `fspec/`, рядом с `bootstrap/`. Не найден ни один — NULL, и пакет не
 * заводится вовсе: пробел лучше спеки, скопированной ниоткуда.
 */
static char *new_template_dir(const char *self) {
  const char *env = getenv(NEW_TEMPLATE_ENV);
  char *self_dir = NULL;
  char *parent = NULL;
  char *candidate = NULL;
  char *probe = NULL;
  if (env != NULL && env[0] != '\0') {
    probe = repl_join(env, "guard.flang");
    if (repl_exists(probe)) {
      free(probe);
      return repl_say(env);
    }
    free(probe);
  }
  self_dir = repl_self_dir(self);
  if (self_dir == NULL) {
    return NULL;
  }
  parent = repl_dirname(self_dir);
  free(self_dir);
  candidate = repl_join(parent, "fspec");
  free(parent);
  probe = repl_join(candidate, "guard.flang");
  if (repl_exists(probe)) {
    free(probe);
    return candidate;
  }
  free(probe);
  free(candidate);
  return NULL;
}

/** Абсолютный путь к САМОМУ двоичному: settings.txt пакета обязан находить
    компилятор независимо от того, откуда потом позовут `flang io`. */
static char *new_compiler_self(const char *self) {
  char *dir = repl_self_dir(self);
  char *full = NULL;
  if (dir == NULL) {
    return repl_say("flang");
  }
  full = repl_join(dir, "flang");
  free(dir);
  if (access(full, X_OK) != 0) {
    free(full);
    return repl_say("flang");
  }
  return full;
}

static bool new_copy_template(const char *template_dir, const char *filename, const char *dest_dir) {
  char *source = repl_join(template_dir, filename);
  char *destination = repl_join(dest_dir, filename);
  size_t bytes = 0;
  char *text = repl_read_file(source, &bytes);
  bool ok = false;
  free(source);
  if (text == NULL) {
    repl_buf say;
    buf_init(&say);
    buf_put(&say, "образец ");
    buf_put(&say, filename);
    buf_put(&say, " не прочитан — пакет не создан");
    new_refuse(say.data);
    buf_free(&say);
    free(destination);
    return false;
  }
  ok = emit_write(destination, text, bytes);
  free(destination);
  free(text);
  return ok;
}

static char *new_title(const char *name) {
  char *title = repl_say(name);
  if (title[0] >= 'a' && title[0] <= 'z') {
    title[0] = (char)(title[0] - 'a' + 'A');
  }
  return title;
}

static bool new_write_all(const char *target, const char *fspec_dir, const char *spec_dir,
                          const char *template_dir, const char *compiler_path, const char *name) {
  char *title = new_title(name);
  char *path = NULL;
  repl_buf out;
  bool ok = true;

  buf_init(&out);
  buf_put(&out, "модуль «");
  buf_put(&out, title);
  buf_put(&out,
          "»\n\n"
          "тотальная функция «Поприветствовать»\n"
          "  принимает имя: строка\n"
          "  возвращает строка\n"
          "  пример «приветствие Марата»\n"
          "    дано имя равно \"Марат\"\n"
          "    ожидается \"Привет, Марат!\"\n"
          "  соединить [\"Привет, \", имя, \"!\"] по \"\"\n");
  {
    repl_buf filename;
    buf_init(&filename);
    buf_put(&filename, name);
    buf_put(&filename, ".flang");
    path = repl_join(target, filename.data);
    buf_free(&filename);
  }
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out, "{\"имя\": \"");
  buf_put(&out, title);
  buf_put(&out, "\", \"версия\": \"0.1.0\"}\n");
  path = repl_join(target, NEW_MANIFEST);
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out, "# ");
  buf_put(&out, title);
  buf_put(&out,
          "\n\n"
          "Пакет на flang. Минуты до первой доказанной тотальной функции:\n"
          "флаг `тотальная` компилятор не принимает на слово, а проверяет.\n\n"
          "## Собрать и проверить\n\n"
          "    flang check ");
  buf_put(&out, name);
  buf_put(&out,
          ".flang\n"
          "    flang test ");
  buf_put(&out, name);
  buf_put(&out,
          ".flang\n\n"
          "Ответ `check` — сколько функций и сколько из них с доказанным\n"
          "завершением; `test` прогоняет примеры, записанные внутри функций.\n\n"
          "## Спеки предметной области\n\n"
          "Каталог `fspec/` — доказанные бизнес-правила, а не только код.\n"
          "Проверить все спеки разом:\n\n"
          "    flang io fspec/guard.flang\n\n"
          "Добавить спеку: файл `fspec/spec/NN-имя.flang` со своим\n"
          "`обеспечивает «имя» цель`, затем та же команда, а после — переписать\n"
          "слепок обещаний командой `flang io fspec/snapshot.flang`. Подробнее —\n"
          "`fspec/README.md`.\n\n"
          "## Пакет\n\n"
          "    flang package ");
  buf_put(&out, name);
  buf_put(&out,
          ".flang > ");
  buf_put(&out, name);
  buf_put(&out,
          ".flang-package\n\n"
          "Имя и версия для `flang package` берутся из `flang.package` рядом со\n"
          "входным файлом.\n");
  path = repl_join(target, "README.md");
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out, compiler_path);
  buf_put(&out, "\nspec\n");
  path = repl_join(fspec_dir, "settings.txt");
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out,
          "# Спеки пакета\n\n"
          "Бизнес-правило, доказанное компилятором, а не только описанное словами.\n"
          "`spec/01-order-steps.flang` — полный работающий пример: две проверки,\n"
          "ни одна не переживает подмену тела заглушкой той же подписи.\n\n"
          "    flang io fspec/guard.flang        # проверить все спеки разом\n"
          "    flang io fspec/snapshot.flang     # переписать слепок после правки спек\n\n"
          "`guard.flang` и `policy.flang` — та же проверка, что в дереве flang\n"
          "(https://github.com/digitable-lol/flang, каталог fspec/): читает\n"
          "`settings.txt` (компилятор и каталог спек), находит файлы `spec/*.flang`,\n"
          "спрашивает у компилятора отчёт о доказательствах и сверяет его с\n"
          "`snapshot.txt` — слепком обещаний, который не даёт следующей спеке молча\n"
          "ослабить прежнюю.\n\n"
          "Новая спека — файл в `spec/` с номером в начале имени, модулем\n"
          "`«Спека N: …»` и хотя бы одним `обеспечивает «имя» цель`.\n");
  path = repl_join(fspec_dir, "README.md");
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out,
          "модуль «Спека 1: шаги приёмки заказа»\n\n"
          "тотальная функция «Шаги приёмки заказа»\n"
          "  возвращает список строка\n"
          "  обеспечивает «шагов ровно три» (длина результат) равен 3\n"
          "  обеспечивает «первый шаг — оплата» результат содержит \"оплата\"\n"
          "  пример «список шагов приёмки»\n"
          "    ожидается [\"оплата\", \"сборка\", \"доставка\"]\n"
          "  [\"оплата\", \"сборка\", \"доставка\"]\n");
  path = repl_join(spec_dir, "01-order-steps.flang");
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  buf_init(&out);
  buf_put(&out,
          "01-order-steps.flang :: Шаги приёмки заказа :: шагов ровно три :: (длина "
          "результат) равен 3\n"
          "01-order-steps.flang :: Шаги приёмки заказа :: первый шаг — оплата :: "
          "результат содержит \"оплата\"\n");
  path = repl_join(fspec_dir, "snapshot.txt");
  ok = emit_write(path, out.data, out.used) && ok;
  free(path);
  buf_free(&out);

  ok = new_copy_template(template_dir, "guard.flang", fspec_dir) && ok;
  ok = new_copy_template(template_dir, "policy.flang", fspec_dir) && ok;

  free(title);
  return ok;
}

static int new_project(int argc, char **argv, const char *self) {
  const char *name = NULL;
  bool force = false;
  int index = 0;
  char buffer[4096];
  char *base = NULL;
  char *target = NULL;
  char *fspec_dir = NULL;
  char *spec_dir = NULL;
  char *template_dir = NULL;
  char *compiler_path = NULL;
  struct stat info;
  bool exists = false;
  int code = 0;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--force") == 0 || strcmp(argv[index], "--силой") == 0) {
      force = true;
    } else if (strcmp(argv[index], "-") == 0) {
      fputs("flang new требует имя пакета: со стандартного ввода оно не читается\n", stderr);
      return 2;
    } else if (argv[index][0] != '-' && name == NULL) {
      name = argv[index];
    } else {
      fprintf(stderr, "flang new: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }
  if (name == NULL) {
    fputs("flang new: не назван пакет. Пример: flang new проба\n", stderr);
    return 2;
  }
  if (!new_name_ok(name)) {
    fprintf(stderr,
            "FLANG_NEW: имя «%s» недопустимо — без пробела, косой черты, кавычек и без\n"
            "занятых слов (имена команд, «flang», «fspec»). Пакет не создан.\n",
            name);
    return 2;
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  target = repl_resolve(base, name);
  free(base);

  exists = stat(target, &info) == 0;
  if (exists && !S_ISDIR(info.st_mode)) {
    fprintf(stderr, "FLANG_NEW: «%s» уже существует и не каталог — новый пакет некуда класть\n", target);
    free(target);
    return 1;
  }
  if (exists && !force) {
    fprintf(stderr,
            "FLANG_NEW: каталог «%s» уже существует. flang new не переписывает чужую работу\n"
            "молча — допишите --force (или --силой), если это точно то же место.\n",
            target);
    free(target);
    return 1;
  }

  template_dir = new_template_dir(self);
  if (template_dir == NULL) {
    fprintf(stderr,
            "FLANG_NEW: не найден образец fspec/ (guard.flang рядом с policy.flang) — искали\n"
            "в $%s и в <каталог двоичного>/../fspec. Пакет не создан.\n",
            NEW_TEMPLATE_ENV);
    free(target);
    return 1;
  }

  compiler_path = new_compiler_self(self);
  fspec_dir = repl_join(target, "fspec");
  spec_dir = repl_join(fspec_dir, "spec");

  if (!emit_make_dir(spec_dir)) {
    free(target);
    free(fspec_dir);
    free(spec_dir);
    free(template_dir);
    free(compiler_path);
    return 1;
  }

  code = new_write_all(target, fspec_dir, spec_dir, template_dir, compiler_path, name) ? 0 : 1;
  if (code == 0) {
    fprintf(stderr,
            "flang new: пакет «%s» создан в %s\n"
            "  cd %s && flang check %s.flang\n"
            "  flang io fspec/guard.flang\n",
            name, target, name, name);
  }

  free(target);
  free(fspec_dir);
  free(spec_dir);
  free(template_dir);
  free(compiler_path);
  return code;
}

/* ═══════════════════ языковой сервер: `flang lsp` ═════════════════════════ */

/*
 * ЧТО ЗДЕСЬ ЖИВЁТ И ЧЕГО ЗДЕСЬ НЕТ.
 *
 * Здесь ТОЛЬКО хозяин: рамки `Content-Length`, разбор входящего JSON, чтение
 * файлов с диска, перевод пути в адрес `file://` и обратно. Всё, что решает,
 * чем является сообщение и что на него ответить, живёт в `flang/self/lsp.flang`
 * — 2 893 строки на самом языке, — и зовётся отсюда по именам «Новый сервер»,
 * «Принять», «Принять проверенное», «Открытые тексты».
 *
 * Разделение то же самое, что у свидетеля между `bin/flang-lsp.mjs` (транспорт,
 * 185 строк) и `src/lsp.mjs` (сервер, 900): разойдись оно — и сверка двух
 * реализаций сравнивала бы разные вещи.
 *
 * РАЗБОР JSON — ЧУЖОЙ, а не свой: тело сообщения читает `facts_json`, тот же,
 * каким приезжают факты в `flang facts`. Печать исходящего своего кода не
 * заводит вовсе — сервер отдаёт УЖЕ НАПЕЧАТАННЫЕ строки («Печать значения» из
 * `core/json.flang`), и порядок ключей в них — часть договора с редактором.
 *
 * ЧТО ЭТОТ РАЗБОР НЕ УМЕЕТ: `\uXXXX` в строке JSON (`run_text` отказывает на
 * нём намеренно). Редакторы шлют UTF-8 буквами (`JSON.stringify` не экранирует
 * не-ASCII), поэтому на живом клиенте это не встречается; названо здесь, чтобы
 * не считалось незамеченным.
 *
 * АРЕНА. Сервер живёт дольше одного сообщения, а арена компилятора сбрасывается
 * на каждом (иначе память росла бы всю сессию: проверка одного файла стоит
 * десятки мегабайт). Поэтому значение «Сервер» между сообщениями хранится ВНЕ
 * арены — `lsp_keep` копирует его в malloc, `lsp_restore` возвращает в свежую
 * арену. Имена полей и вариантов при этом не копируются: они статические строки
 * напечатанного кода и сброс арены переживают.
 */

static fl_value lsp_keep(fl_value node);

static const fl_field *lsp_keep_fields(const fl_field *fields, size_t count) {
  fl_field *copy = NULL;
  size_t index = 0;
  if (count == 0) {
    return NULL;
  }
  copy = (fl_field *)repl_alloc(count * sizeof(fl_field));
  for (index = 0; index < count; index += 1) {
    copy[index].name = fields[index].name;
    copy[index].value = lsp_keep(fields[index].value);
  }
  return copy;
}

/** Значение из арены — в память, которую сброс арены не тронет. */
static fl_value lsp_keep(fl_value node) {
  fl_value out = node;
  size_t index = 0;
  switch (node.tag) {
    case FL_STRING:
      out.as.string.utf8 = repl_dup(node.as.string.utf8, node.as.string.bytes);
      break;
    case FL_LIST: {
      fl_value *items = NULL;
      if (node.as.list.count > 0) {
        items = (fl_value *)repl_alloc(node.as.list.count * sizeof(fl_value));
        for (index = 0; index < node.as.list.count; index += 1) {
          items[index] = lsp_keep(node.as.list.items[index]);
        }
      }
      out.as.list.items = items;
      /* Запас массива принадлежит арене; копия его не наследует. */
      out.as.list.grow = NULL;
      break;
    }
    case FL_RECORD: {
      fl_record *record = (fl_record *)repl_alloc(sizeof(fl_record));
      record->count = node.as.record->count;
      record->fields = lsp_keep_fields(node.as.record->fields, node.as.record->count);
      out.as.record = record;
      break;
    }
    case FL_VARIANT: {
      fl_variant *variant = (fl_variant *)repl_alloc(sizeof(fl_variant));
      variant->name = node.as.variant->name;
      variant->count = node.as.variant->count;
      variant->fields = lsp_keep_fields(node.as.variant->fields, node.as.variant->count);
      out.as.variant = variant;
      break;
    }
    default:
      break;
  }
  return out;
}

static void lsp_drop(fl_value node) {
  size_t index = 0;
  switch (node.tag) {
    case FL_STRING:
      free((void *)(size_t)node.as.string.utf8);
      break;
    case FL_LIST:
      for (index = 0; index < node.as.list.count; index += 1) {
        lsp_drop(node.as.list.items[index]);
      }
      free((void *)(size_t)node.as.list.items);
      break;
    case FL_RECORD:
      for (index = 0; index < node.as.record->count; index += 1) {
        lsp_drop(node.as.record->fields[index].value);
      }
      free((void *)(size_t)node.as.record->fields);
      free((void *)(size_t)node.as.record);
      break;
    case FL_VARIANT:
      for (index = 0; index < node.as.variant->count; index += 1) {
        lsp_drop(node.as.variant->fields[index].value);
      }
      free((void *)(size_t)node.as.variant->fields);
      free((void *)(size_t)node.as.variant);
      break;
    default:
      break;
  }
}

static fl_value lsp_restore(fl_value node) {
  size_t index = 0;
  switch (node.tag) {
    case FL_STRING:
      return repl_value_text(node.as.string.utf8, node.as.string.bytes);
    case FL_LIST: {
      fl_value *items = NULL;
      fl_error error;
      error.code = NULL;
      error.message = NULL;
      if (fl_list_alloc(&repl_ctx, node.as.list.count, &items, &error) != FL_OK) {
        repl_oom();
      }
      for (index = 0; index < node.as.list.count; index += 1) {
        items[index] = lsp_restore(node.as.list.items[index]);
      }
      return fl_list(items, node.as.list.count);
    }
    case FL_RECORD:
    case FL_VARIANT: {
      const size_t count = node.tag == FL_RECORD ? node.as.record->count : node.as.variant->count;
      const fl_field *fields = node.tag == FL_RECORD ? node.as.record->fields : node.as.variant->fields;
      const char **names = (const char **)repl_alloc((count + 1) * sizeof(const char *));
      fl_value *values = (fl_value *)repl_alloc((count + 1) * sizeof(fl_value));
      fl_value out = fl_nothing();
      fl_error error;
      fl_status status = FL_OK;
      error.code = NULL;
      error.message = NULL;
      for (index = 0; index < count; index += 1) {
        names[index] = fields[index].name;
        values[index] = lsp_restore(fields[index].value);
      }
      status = node.tag == FL_RECORD
                   ? fl_record_new(&repl_ctx, names, values, count, &out, &error)
                   : fl_variant_new(&repl_ctx, node.as.variant->name, names, values, count, &out, &error);
      free(names);
      free(values);
      if (status != FL_OK) {
        repl_oom();
      }
      return out;
    }
    default:
      break;
  }
  return node;
}

/* ───────────────────── адрес `file://` ↔ путь на диске ──────────────────── */

/*
 * Кодировка та же, что у `pathToFileURL` свидетеля, и «та же» здесь означает
 * побайтово: адрес документа — это КЛЮЧ, по которому редактор узнаёт свою
 * диагностику, и один лишний процент разводит две реализации молча.
 *
 * Свидетель делает два шага: сперва экранирует то, что иначе потерялось бы в
 * разборе адреса (`%`, `\`, перевод строки, возврат каретки, табуляция), потом
 * отдаёт результат `URL.pathname`, а тот кодирует управляющие знаки, пробел,
 * «"#<>?`{}» и всё, что за ASCII.
 */
static void lsp_percent(repl_buf *out, unsigned char byte) {
  static const char HEX[] = "0123456789ABCDEF";
  buf_char(out, '%');
  buf_char(out, HEX[(byte >> 4) & 0x0F]);
  buf_char(out, HEX[byte & 0x0F]);
}

static bool lsp_path_set(unsigned char byte) {
  return byte <= 0x20 || byte > 0x7E || byte == '"' || byte == '#' || byte == '<' || byte == '>' ||
         byte == '?' || byte == '`' || byte == '{' || byte == '}';
}

static char *lsp_uri_of(const char *path) {
  repl_buf out;
  size_t index = 0;
  char *result = NULL;
  buf_init(&out);
  buf_put(&out, "file://");
  for (index = 0; path[index] != '\0'; index += 1) {
    const unsigned char byte = (unsigned char)path[index];
    if (byte == '%' || byte == '\\' || lsp_path_set(byte)) {
      lsp_percent(&out, byte);
    } else {
      buf_char(&out, (char)byte);
    }
  }
  result = repl_dup(out.data, out.used);
  buf_free(&out);
  return result;
}

static int lsp_hex(char symbol) {
  if (symbol >= '0' && symbol <= '9') {
    return symbol - '0';
  }
  if (symbol >= 'a' && symbol <= 'f') {
    return symbol - 'a' + 10;
  }
  if (symbol >= 'A' && symbol <= 'F') {
    return symbol - 'A' + 10;
  }
  return -1;
}

/*
 * `resolve(fileURLToPath(uri))` свидетеля. Не адрес `file:` — не путь вовсе, и
 * ответ на это «пути нет», а не выдуманный путь: документ без пути сервер
 * держит в памяти и не проверяет, потому что проверять нечем — его импорты
 * ссылаются в никуда.
 */
static char *lsp_path_of(const char *uri, const char *base) {
  repl_buf out;
  size_t index = 7;
  char *raw = NULL;
  char *result = NULL;
  if (strncmp(uri, "file://", 7) != 0) {
    /* `file:` без двух косых — тоже адрес файла (так пишут не все, но пишут). */
    if (strncmp(uri, "file:", 5) != 0) {
      return NULL;
    }
    index = 5;
  }
  /* `file://localhost/…` — тот же локальный файл. */
  if (strncmp(uri + index, "localhost/", 10) == 0) {
    index += 9;
  }
  buf_init(&out);
  for (; uri[index] != '\0'; index += 1) {
    if (uri[index] == '%' && lsp_hex(uri[index + 1]) >= 0 && lsp_hex(uri[index + 2]) >= 0) {
      buf_char(&out, (char)((lsp_hex(uri[index + 1]) << 4) | lsp_hex(uri[index + 2])));
      index += 2;
      continue;
    }
    if (uri[index] == '?' || uri[index] == '#') {
      break;
    }
    buf_char(&out, uri[index]);
  }
  raw = repl_dup(out.data, out.used);
  buf_free(&out);
  result = repl_resolve(base, raw);
  free(raw);
  return result;
}

/* ─────────────────────────── рамки Content-Length ───────────────────────── */

/*
 * Длина в заголовке — в БАЙТАХ, а не в знаках: в исходниках flang имена
 * русские, и на первом же «использует» длина, посчитанная в знаках, обрезала бы
 * тело на середине.
 *
 * Разделителей два, как и у свидетеля: `\r\n\r\n` по спецификации и `\n\n` — то,
 * что присылают редакторы, писанные наспех. Рамка без `Content-Length` —
 * единственное, чего протокол починить не даёт: где кончается тело, неизвестно,
 * поэтому шапка выбрасывается и ищется следующая.
 */
static char *lsp_read_frame(repl_buf *tail, size_t *bytes) {
  for (;;) {
    size_t index = 0;
    size_t head = 0;
    size_t length = 0;
    bool found = false;
    for (index = 0; index + 1 < tail->used; index += 1) {
      if (index + 3 < tail->used && tail->data[index] == '\r' && tail->data[index + 1] == '\n' &&
          tail->data[index + 2] == '\r' && tail->data[index + 3] == '\n') {
        head = index + 4;
        found = true;
        break;
      }
      if (tail->data[index] == '\n' && tail->data[index + 1] == '\n') {
        head = index + 2;
        found = true;
        break;
      }
    }
    if (found) {
      size_t scan = 0;
      bool named = false;
      for (scan = 0; scan + 15 <= head; scan += 1) {
        if (strncmp(tail->data + scan, "Content-Length:", 15) == 0 ||
            strncmp(tail->data + scan, "content-length:", 15) == 0) {
          size_t digit = scan + 15;
          while (digit < head && (tail->data[digit] == ' ' || tail->data[digit] == '\t')) {
            digit += 1;
          }
          length = 0;
          while (digit < head && tail->data[digit] >= '0' && tail->data[digit] <= '9') {
            length = length * 10 + (size_t)(tail->data[digit] - '0');
            digit += 1;
          }
          named = true;
          break;
        }
      }
      if (!named) {
        fputs("flang lsp: рамка без Content-Length, пропущена\n", stderr);
        memmove(tail->data, tail->data + head, tail->used - head);
        tail->used -= head;
        tail->data[tail->used] = '\0';
        continue;
      }
      if (tail->used >= head + length) {
        char *body = repl_dup(tail->data + head, length);
        memmove(tail->data, tail->data + head + length, tail->used - head - length);
        tail->used -= head + length;
        tail->data[tail->used] = '\0';
        *bytes = length;
        return body;
      }
    }
    {
      char chunk[8192];
      const size_t got = fread(chunk, 1, sizeof(chunk), stdin);
      if (got == 0) {
        return NULL;
      }
      buf_add(tail, chunk, got);
    }
  }
}

static void lsp_write_frame(const char *body, size_t bytes) {
  printf("Content-Length: %lu\r\n\r\n", (unsigned long)bytes);
  fwrite(body, 1, bytes, stdout);
  fflush(stdout);
}

/* ──────────────────── входящее сообщение в «Сообщение» ──────────────────── */

/** `null` в JSON и «ключа нет» — разные вещи, и сервер их различает. */
static bool lsp_is_null(fl_value node) {
  fl_value scalar = fl_nothing();
  return val_is(node, "Значение скаляра") && val_field(node, "скаляр", &scalar) &&
         val_is(scalar, "Скаляр ничто");
}

static fl_value lsp_text_or(fl_value node, const char *key, bool *present) {
  fl_value field = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  *present = zn_field(node, key, &field);
  if (*present && zn_text(field, &utf8, &bytes)) {
    return repl_value_text(utf8, bytes);
  }
  return repl_value_say("");
}

static double lsp_number_or(fl_value node, const char *key, double fallback, bool *present) {
  fl_value field = fl_nothing();
  double number = 0.0;
  *present = zn_field(node, key, &field);
  if (*present && zn_number(field, &number)) {
    return number;
  }
  return fallback;
}

/*
 * `contentChanges` — список правок. Различать «область есть» и «области нет»
 * обязательно: правка без области заменяет документ целиком, и свидетель берёт
 * ПОСЛЕДНЮЮ такую, а правки с областью пропускает.
 */
static fl_value lsp_edits(fl_value params) {
  static const char *const names[3] = {"есть область", "текст", "есть текст"};
  fl_value changes = fl_nothing();
  const fl_value *items = NULL;
  size_t count = 0;
  size_t index = 0;
  fl_value *array = NULL;
  fl_error error;
  error.code = NULL;
  error.message = NULL;
  if (zn_field(params, "contentChanges", &changes)) {
    zn_items(changes, &items, &count);
  }
  if (fl_list_alloc(&repl_ctx, count, &array, &error) != FL_OK) {
    repl_oom();
  }
  for (index = 0; index < count; index += 1) {
    fl_value values[3];
    fl_value range = fl_nothing();
    bool has_text = false;
    values[0] = fl_flag(zn_field(items[index], "range", &range));
    values[1] = lsp_text_or(items[index], "text", &has_text);
    values[2] = fl_flag(has_text);
    array[index] = repl_value_record(names, values, 3);
  }
  return fl_list(array, count);
}

static fl_value lsp_empty_object(void) {
  return repl_value_variant_fields("Значение записи", "поля", repl_value_list(NULL, 0));
}

static fl_value lsp_message(fl_value json, const char *base) {
  static const char *const names[15] = {"метод",  "есть номер",   "номер",  "адрес",   "есть адрес",
                                        "путь",   "есть путь",    "текст",  "есть текст", "версия",
                                        "есть версия", "правки", "строка", "столбец", "есть место"};
  fl_value values[15];
  fl_value params = fl_nothing();
  fl_value document = fl_nothing();
  fl_value position = fl_nothing();
  fl_value id = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  bool present = false;
  bool has_id = false;
  bool has_uri = false;
  bool has_text = false;
  bool has_version = false;
  bool has_place = false;
  char *uri = NULL;
  char *path = NULL;
  double number = 0.0;

  if (!zn_field(json, "params", &params)) {
    params = lsp_empty_object();
  }
  if (!zn_field(params, "textDocument", &document)) {
    document = lsp_empty_object();
  }
  has_place = zn_field(params, "position", &position) && !lsp_is_null(position);
  has_id = zn_field(json, "id", &id);

  values[0] = lsp_text_or(json, "method", &present);
  values[1] = fl_flag(has_id && !lsp_is_null(id));
  values[2] = fl_number(has_id && zn_number(id, &number) ? number : 0.0);
  values[3] = lsp_text_or(document, "uri", &has_uri);
  values[4] = fl_flag(has_uri);
  if (has_uri && val_text(values[3], &utf8, &bytes) && bytes > 0) {
    uri = repl_dup(utf8, bytes);
    path = lsp_path_of(uri, base);
    free(uri);
  }
  values[5] = repl_value_say(path == NULL ? "" : path);
  values[6] = fl_flag(path != NULL);
  free(path);
  values[7] = lsp_text_or(document, "text", &has_text);
  values[8] = fl_flag(has_text);
  values[9] = fl_number(lsp_number_or(document, "version", 0.0, &has_version));
  values[10] = fl_flag(has_version);
  values[11] = lsp_edits(params);
  values[12] = fl_number(has_place ? lsp_number_or(position, "line", 0.0, &present) : 0.0);
  values[13] = fl_number(has_place ? lsp_number_or(position, "character", 0.0, &present) : 0.0);
  values[14] = fl_flag(has_place);
  return repl_value_record(names, values, 15);
}

/* ────────────────────────── поручение проверки ──────────────────────────── */

/*
 * `checkSource` свидетеля: разбор со связыванием, типы, завершаемость. Хозяину
 * здесь принадлежит ровно одно — ЧТЕНИЕ: замыкание `использует` собирается из
 * ОТКРЫТЫХ БУФЕРОВ, а с диска берётся только то, чего в редакторе не открыто.
 * Иначе сервер показывал бы ошибки по сохранённой версии соседнего файла,
 * которую человек уже правит на экране.
 */
static fl_value lsp_check(fl_value server, const char *path, const char *text, size_t text_bytes) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  fl_value opened = fl_nothing();
  fl_value files = fl_nothing();
  fl_value pairs = fl_nothing();
  fl_value args[3];
  fl_value verdict = fl_nothing();
  fl_value *items = NULL;
  size_t index = 0;
  fl_error error;
  error.code = NULL;
  error.message = NULL;

  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, path);
  strings_add(&texts, text, text_bytes);
  repl_imports_of(text, text_bytes, path, &queue);

  if (repl_call("Открытые тексты", &server, 1, &opened) != FL_OK) {
    opened = repl_value_list(NULL, 0);
  }
  for (index = 0; index < queue.count; index += 1) {
    const char *needed = queue.items[index];
    char *found = NULL;
    size_t bytes = 0;
    size_t inner = 0;
    if (strings_has(&paths, needed, strlen(needed))) {
      continue;
    }
    if (opened.tag == FL_LIST) {
      for (inner = 0; inner < opened.as.list.count; inner += 1) {
        fl_value field = fl_nothing();
        const char *utf8 = NULL;
        size_t got = 0;
        if (!val_field(opened.as.list.items[inner], "путь", &field) || !val_text(field, &utf8, &got)) {
          continue;
        }
        if (got != strlen(needed) || memcmp(utf8, needed, got) != 0) {
          continue;
        }
        if (val_field(opened.as.list.items[inner], "текст", &field) && val_text(field, &utf8, &got)) {
          found = repl_dup(utf8, got);
          bytes = got;
        }
        break;
      }
    }
    if (found == NULL) {
      found = repl_read_file(needed, &bytes);
    }
    if (found == NULL) {
      /* Файла нет — молчим: об этом скажет сам компилятор, кодом
         FLANG_IMPORT_NOT_FOUND, а не нашим пересказом. */
      continue;
    }
    strings_say(&paths, needed);
    strings_add(&texts, found, bytes);
    repl_imports_of(found, bytes, needed, &queue);
    free(found);
  }
  /* У сервера правки свой обход, не `repl_closure`; рёбра ввоза он не считает,
     и копиться им между запросами незачем. */
  repl_edges_forget();

  if (fl_list_alloc(&repl_ctx, paths.count, &items, &error) != FL_OK) {
    repl_oom();
  }
  for (index = 0; index < paths.count; index += 1) {
    items[index] = repl_source_value(paths.items[index], texts.items[index], texts.sizes[index]);
  }
  files = fl_list(items, paths.count);

  {
    static const char *const names[2] = {"путь", "адрес"};
    fl_value *array = NULL;
    if (fl_list_alloc(&repl_ctx, paths.count, &array, &error) != FL_OK) {
      repl_oom();
    }
    for (index = 0; index < paths.count; index += 1) {
      fl_value values[2];
      char *uri = lsp_uri_of(paths.items[index]);
      values[0] = repl_value_say(paths.items[index]);
      values[1] = repl_value_say(uri);
      array[index] = repl_value_record(names, values, 2);
      free(uri);
    }
    pairs = fl_list(array, paths.count);
  }

  args[0] = files;
  args[1] = repl_value_say(path);
  args[2] = pairs;
  if (repl_call("Проверка для сервера", args, 3, &verdict) != FL_OK) {
    fl_value bad = repl_value_say("проверка не отработала");
    if (repl_call("Сорванная проверка сервера", &bad, 1, &verdict) != FL_OK) {
      verdict = fl_nothing();
    }
  }
  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  return verdict;
}

/* ──────────────────────────── сам сервер ────────────────────────────────── */

/*
 * КОД ВОЗВРАТА ТОТ ЖЕ, ЧТО У СВИДЕТЕЛЯ: 0 после `shutdown`, 1 без него.
 * Спецификация LSP требует именно этого, и требует не из вкуса — редактор по
 * коду отличает нормальное прощание от падения сервера.
 */
static int lsp_serve(int argc, char **argv) {
  repl_buf tail;
  fl_value kept = fl_nothing();
  char buffer[4096];
  char *base = NULL;
  int index = 0;
  int code = 0;
  bool closed = false;

  for (index = 2; index < argc; index += 1) {
    if (strcmp(argv[index], "--stdio") != 0) {
      fprintf(stderr, "flang lsp: непонятный ключ «%s»\n", argv[index]);
      return 2;
    }
  }

  base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  buf_init(&tail);
  repl_cycle();
  {
    fl_value server = fl_nothing();
    if (repl_call("Новый сервер", NULL, 0, &server) != FL_OK) {
      fputs("flang lsp: сервер не завёлся\n", stderr);
      buf_free(&tail);
      free(base);
      return 2;
    }
    kept = lsp_keep(server);
  }

  while (!closed) {
    size_t bytes = 0;
    char *body = lsp_read_frame(&tail, &bytes);
    fl_value json = fl_nothing();
    fl_value step = fl_nothing();
    fl_value server = fl_nothing();
    fl_value field = fl_nothing();
    size_t at = 0;
    size_t turn = 0;
    if (body == NULL) {
      break;
    }
    repl_cycle();
    server = lsp_restore(kept);
    lsp_drop(kept);
    kept = fl_nothing();
    if (!facts_json(body, &at, &json)) {
      fputs("flang lsp: неразобранный JSON, сообщение пропущено\n", stderr);
      free(body);
      kept = lsp_keep(server);
      continue;
    }
    free(body);
    {
      fl_value args[2];
      args[0] = server;
      args[1] = lsp_message(json, base);
      if (repl_call("Принять", args, 2, &step) != FL_OK) {
        fputs("flang lsp: сообщение не обработалось\n", stderr);
        kept = lsp_keep(server);
        continue;
      }
    }
    while (val_field(step, "ждёт", &field) && field.tag == FL_FLAG && field.as.flag) {
      fl_value args[2];
      fl_value inner = fl_nothing();
      const char *path_utf8 = NULL;
      const char *text_utf8 = NULL;
      size_t path_bytes = 0;
      size_t text_bytes = 0;
      char *path = NULL;
      char *text = NULL;
      turn += 1;
      if (turn > 4096) {
        fputs("flang lsp: поручения проверки не кончаются\n", stderr);
        break;
      }
      if (!val_field(step, "путь", &field) || !val_text(field, &path_utf8, &path_bytes)) {
        break;
      }
      path = repl_dup(path_utf8, path_bytes);
      if (!val_field(step, "текст", &field) || !val_text(field, &text_utf8, &text_bytes)) {
        free(path);
        break;
      }
      text = repl_dup(text_utf8, text_bytes);
      if (!val_field(step, "сервер", &inner)) {
        free(path);
        free(text);
        break;
      }
      args[0] = step;
      args[1] = lsp_check(inner, path, text, text_bytes);
      free(path);
      free(text);
      if (repl_call("Принять проверенное", args, 2, &step) != FL_OK) {
        fputs("flang lsp: проверенное не улеглось\n", stderr);
        break;
      }
    }
    if (val_field(step, "исходящие", &field) && field.tag == FL_LIST) {
      size_t out = 0;
      for (out = 0; out < field.as.list.count; out += 1) {
        const char *utf8 = NULL;
        size_t got = 0;
        if (val_text(field.as.list.items[out], &utf8, &got)) {
          lsp_write_frame(utf8, got);
        }
      }
    }
    if (val_field(step, "выход", &field) && field.tag == FL_FLAG && field.as.flag) {
      closed = true;
      if (val_field(step, "код выхода", &field) && field.tag == FL_NUMBER) {
        code = (int)field.as.number;
      }
    }
    if (!closed) {
      if (val_field(step, "сервер", &field)) {
        kept = lsp_keep(field);
      } else {
        kept = lsp_keep(server);
      }
    }
  }

  if (kept.tag != FL_NOTHING) {
    lsp_drop(kept);
  }
  buf_free(&tail);
  free(base);
  return code;
}

/* ═══════════════════ служба MCP: `flang --mcp-mode` ══════════════════════ */

/*
 * Здесь ТОЛЬКО хозяин: чтение строк, разбор входящего JSON, чтение ввозимых
 * файлов и сама проверка. ЧЕМ является сообщение, что на него ответить и какими
 * словами — всё это решает `flang/self/mcp.flang`. Граница ровно та же, что у
 * языкового сервера, и довод тот же: разойдись она — и то, что помощник узнаёт
 * о программе, зависело бы от языка, на котором написан транспорт, а не от
 * языка, о котором вопрос.
 *
 * РАМОК Content-Length ЗДЕСЬ НЕТ, и это не упрощение: транспорт MCP по
 * стандартным потокам — это JSON-RPC ПОСТРОЧНО, по сообщению на строку. Взять
 * рамки от LSP значило бы говорить на другом протоколе и молча не работать.
 *
 * ПОЧЕМУ НЕ ГОДИТСЯ ПРОГОНЩИК, который в этом бинарнике уже есть. Он читает
 * стандартный ввод ЦЕЛИКОМ (`read_all` в flang_cli.c) и только потом отвечает
 * по строке. Клиент MCP держит трубу открытой и ждёт ответа на первый же
 * запрос — то есть на прогонщике рукопожатие никогда бы не состоялось. Разница
 * не в форме сообщений, а в том, кто кого ждёт.
 */

/** Строка до перевода строки; `\r` в конце снимается — его шлют клиенты Windows. */
static char *mcp_read_line(repl_buf *tail, size_t *bytes) {
  for (;;) {
    size_t index = 0;
    for (index = 0; index < tail->used; index += 1) {
      if (tail->data[index] == '\n') {
        size_t length = index;
        char *line = NULL;
        if (length > 0 && tail->data[length - 1] == '\r') {
          length -= 1;
        }
        line = repl_dup(tail->data, length);
        memmove(tail->data, tail->data + index + 1, tail->used - index - 1);
        tail->used -= index + 1;
        tail->data[tail->used] = '\0';
        *bytes = length;
        return line;
      }
    }
    {
      char chunk[8192];
      const size_t got = fread(chunk, 1, sizeof(chunk), stdin);
      if (got == 0) {
        return NULL;
      }
      buf_add(tail, chunk, got);
    }
  }
}

/*
 * Опознаватель запроса — ТЕКСТОМ, каким он поедет обратно. По JSON-RPC он
 * бывает числом и строкой, и ответ обязан нести тот же: разобрать его в число
 * значило бы потерять строковые опознаватели молча. Целое печатается без точки —
 * `1`, а не `1.0`: клиент сверяет опознаватель побайтово.
 */
static char *mcp_id_text(fl_value json, bool *present) {
  fl_value id = fl_nothing();
  fl_value scalar = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  double number = 0.0;
  char buffer[64];
  *present = false;
  if (!zn_field(json, "id", &id) || val_is(id, "Значение списка") || val_is(id, "Значение записи")) {
    return repl_say("");
  }
  if (!val_field(id, "скаляр", &scalar)) {
    return repl_say("");
  }
  if (val_is(scalar, "Скаляр ничто")) {
    return repl_say("");
  }
  *present = true;
  if (zn_text(id, &utf8, &bytes)) {
    repl_buf out;
    char *result = NULL;
    size_t index = 0;
    buf_init(&out);
    buf_char(&out, '"');
    for (index = 0; index < bytes; index += 1) {
      const unsigned char symbol = (unsigned char)utf8[index];
      if (symbol == '"' || symbol == '\\') {
        buf_char(&out, '\\');
        buf_char(&out, (char)symbol);
      } else if (symbol < 0x20) {
        char escape[8];
        snprintf(escape, sizeof(escape), "\\u%04x", symbol);
        buf_add(&out, escape, strlen(escape));
      } else {
        buf_char(&out, (char)symbol);
      }
    }
    buf_char(&out, '"');
    result = repl_dup(out.data, out.used);
    buf_free(&out);
    return result;
  }
  if (zn_number(id, &number)) {
    if (number == (double)(long long)number) {
      snprintf(buffer, sizeof(buffer), "%lld", (long long)number);
    } else {
      snprintf(buffer, sizeof(buffer), "%.17g", number);
    }
    return repl_say(buffer);
  }
  *present = false;
  return repl_say("");
}

/** Текст поля JSON или пустая строка. */
static char *mcp_text_of(fl_value node, const char *key) {
  fl_value field = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  if (zn_field(node, key, &field) && zn_text(field, &utf8, &bytes)) {
    return repl_dup(utf8, bytes);
  }
  return repl_say("");
}

/** Входящее сообщение → запись «Сообщение MCP», как её ждёт `self/mcp.flang`. */
static fl_value mcp_message(fl_value json) {
  static const char *const names[7] = {"метод",   "есть номер", "номер текстом", "версия клиента",
                                       "средство", "исходник",   "обещание"};
  fl_value values[7];
  fl_value params = fl_nothing();
  fl_value arguments = fl_nothing();
  bool has_id = false;
  char *method = mcp_text_of(json, "method");
  char *id = mcp_id_text(json, &has_id);
  char *version = repl_say("");
  char *tool = repl_say("");
  char *source = repl_say("");
  char *claim = repl_say("");

  if (zn_field(json, "params", &params)) {
    free(version);
    free(tool);
    version = mcp_text_of(params, "protocolVersion");
    tool = mcp_text_of(params, "name");
    if (zn_field(params, "arguments", &arguments)) {
      free(source);
      free(claim);
      source = mcp_text_of(arguments, "source");
      claim = mcp_text_of(arguments, "claim");
    }
  }

  values[0] = repl_value_say(method);
  values[1] = fl_flag(has_id);
  values[2] = repl_value_say(id);
  values[3] = repl_value_say(version);
  values[4] = repl_value_say(tool);
  values[5] = repl_value_say(source);
  values[6] = repl_value_say(claim);
  free(method);
  free(id);
  free(version);
  free(tool);
  free(source);
  free(claim);
  return repl_value_record(names, values, 7);
}

/*
 * Замечания программы — одной строкой на замечание, с кодом и местом. Собираются
 * здесь, а не на flang, ровно потому же, почему на flang не собирается чтение
 * файлов: «Беда» приезжает значением от компилятора, и превращать её в текст для
 * помощника — работа транспорта. Слова при этом те же, что видит человек.
 */
static char *mcp_bads_text(fl_value ledger) {
  fl_value list = fl_nothing();
  repl_buf out;
  char *result = NULL;
  size_t index = 0;
  buf_init(&out);
  if (val_field(ledger, "диагностики", &list) && list.tag == FL_LIST) {
    for (index = 0; index < list.as.list.count; index += 1) {
      fl_value code = fl_nothing();
      fl_value message = fl_nothing();
      fl_value at = fl_nothing();
      fl_value has = fl_nothing();
      fl_value line = fl_nothing();
      fl_value column = fl_nothing();
      const char *code_utf8 = NULL;
      const char *message_utf8 = NULL;
      size_t code_bytes = 0;
      size_t message_bytes = 0;
      char place[64];
      if (!val_field(list.as.list.items[index], "код", &code) ||
          !val_field(list.as.list.items[index], "сообщение", &message) ||
          !val_text(code, &code_utf8, &code_bytes) || !val_text(message, &message_utf8, &message_bytes)) {
        continue;
      }
      place[0] = '\0';
      if (val_field(list.as.list.items[index], "место", &at) && val_field(at, "есть", &has) &&
          has.tag == FL_FLAG && has.as.flag) {
        val_field(at, "строка", &line);
        val_field(at, "столбец", &column);
        snprintf(place, sizeof(place), ", строка %lu, столбец %lu",
                 (unsigned long)(line.tag == FL_NUMBER ? (size_t)line.as.number : 0),
                 (unsigned long)(column.tag == FL_NUMBER ? (size_t)column.as.number : 0));
      }
      if (out.used > 0) {
        buf_char(&out, '\n');
      }
      buf_add(&out, code_utf8, code_bytes);
      buf_add(&out, place, strlen(place));
      buf_add(&out, ": ", 2);
      buf_add(&out, message_utf8, message_bytes);
    }
  }
  result = repl_dup(out.data, out.used);
  buf_free(&out);
  return result;
}

/*
 * Ведомость по тексту, пришедшему от помощника. Текст не лежит на диске и не
 * обязан: он приезжает полем запроса. Имя ему всё же нужно — по нему считается
 * замыкание `использует`, и ввозимые файлы читаются с диска относительно
 * текущего каталога, ровно как у `flang check`.
 */
static fl_value mcp_ledger(const char *source, size_t bytes) {
  repl_strings paths;
  repl_strings texts;
  repl_strings queue;
  fl_value args[2];
  fl_value result = fl_nothing();
  char buffer[4096];
  char *base = getcwd(buffer, sizeof(buffer)) == NULL ? repl_say(".") : repl_say(buffer);
  char *full = repl_resolve(base, "mcp-запрос.flang");
  free(base);
  strings_init(&paths);
  strings_init(&texts);
  strings_init(&queue);
  strings_say(&paths, full);
  strings_add(&texts, source, bytes);
  repl_imports_of(source, bytes, full, &queue);
  args[0] = repl_closure(&paths, &texts, &queue);
  args[1] = repl_value_say(full);
  if (repl_call("Ведомость исходников", args, 2, &result) != FL_OK) {
    result = fl_nothing();
  }
  strings_free(&paths);
  strings_free(&texts);
  strings_free(&queue);
  free(full);
  return result;
}

static void mcp_write(fl_value step) {
  fl_value field = fl_nothing();
  const char *utf8 = NULL;
  size_t bytes = 0;
  if (val_field(step, "есть ответ", &field) && field.tag == FL_FLAG && field.as.flag &&
      val_field(step, "ответ", &field) && val_text(field, &utf8, &bytes)) {
    fwrite(utf8, 1, bytes, stdout);
    fputc('\n', stdout);
    fflush(stdout);
  }
}

static int mcp_serve(int argc, char **argv) {
  repl_buf tail;
  int index = 0;
  for (index = 2; index < argc; index += 1) {
    fprintf(stderr, "flang --mcp-mode: непонятный ключ «%s»\n", argv[index]);
    return 2;
  }
  buf_init(&tail);
  for (;;) {
    size_t bytes = 0;
    char *line = mcp_read_line(&tail, &bytes);
    fl_value json = fl_nothing();
    fl_value message = fl_nothing();
    fl_value step = fl_nothing();
    fl_value field = fl_nothing();
    size_t at = 0;
    if (line == NULL) {
      break;
    }
    if (bytes == 0) {
      free(line);
      continue;
    }
    repl_cycle();
    if (!facts_json(line, &at, &json)) {
      /* Опознавателя у неразобранной строки нет, а ответ без опознавателя
         клиенту адресовать некому. Поэтому — в журнал, а не в ответ. */
      fputs("flang --mcp-mode: строка не разобрана как JSON, пропущена\n", stderr);
      free(line);
      continue;
    }
    free(line);
    message = mcp_message(json);
    if (repl_call("Принять MCP", &message, 1, &step) != FL_OK) {
      fputs("flang --mcp-mode: сообщение не обработалось\n", stderr);
      continue;
    }
    if (val_field(step, "ждёт ведомость", &field) && field.tag == FL_FLAG && field.as.flag) {
      fl_value ledger = fl_nothing();
      fl_value args[5];
      const char *utf8 = NULL;
      size_t got = 0;
      char *bads = NULL;
      if (!val_field(step, "исходник", &field) || !val_text(field, &utf8, &got)) {
        continue;
      }
      ledger = mcp_ledger(utf8, got);
      bads = mcp_bads_text(ledger);
      args[0] = message;
      args[1] = fl_flag(val_field(ledger, "годно", &field) && field.tag == FL_FLAG && field.as.flag);
      args[2] = val_field(ledger, "словами", &field) ? field : repl_value_say("");
      args[3] = val_field(ledger, "препятствие", &field) ? field : repl_value_say("");
      args[4] = repl_value_say(bads);
      free(bads);
      if (repl_call("Принять ведомость MCP", args, 5, &step) != FL_OK) {
        fputs("flang --mcp-mode: отчёт о доказательствах не улёгся в ответ\n", stderr);
        continue;
      }
    }
    mcp_write(step);
    if (val_field(step, "выход", &field) && field.tag == FL_FLAG && field.as.flag) {
      break;
    }
  }
  buf_free(&tail);
  return 0;
}

/* ═════════════════════════ разбор аргументов ═════════════════════════════ */

/*
 * КОМАНДЫ, КОТОРЫЕ ЕСТЬ У ПОЛНОГО ИНСТРУМЕНТАРИЯ И КОТОРЫХ ЗДЕСЬ НЕТ.
 *
 * Названы поимённо, а не свалены в «неизвестная команда». Замер, с которого это
 * заведено: у двоичного 6 команд, у свидетеля на Node — 11, и человек, пришедший
 * по документации за `flang lock`, получал ответ, читающийся как опечатка. Он не
 * узнавал ни того, что команда существует, ни того, где она живёт, — а
 * документация её обещает.
 *
 * Отвечать на такое ошибкой ПРАВИЛЬНО (двоичный этого не умеет, и делать вид,
 * что умеет, было бы хуже всего), но ошибка обязана назвать причину. Список
 * стережётся с обеих сторон: `flang/test/self-bootstrap.test.mjs` требует, чтобы
 * КАЖДАЯ команда свидетеля была у двоичного либо исполнена, либо названа здесь.
 */
static const char *human_elsewhere(const char *command) {
  /* СПИСОК ПУСТ, и это событие, а не забывчивость: с этой правки двоичный
     исполняет ВСЕ ДЕСЯТЬ команд свидетеля, и называть отсутствующим нечего.
     Механизм при этом остаётся: он опустеет ровно до первой новой команды у
     свидетеля, и тогда сюда впишут её — иначе человек, пришедший за ней по
     документации, получит ответ, читающийся как опечатка. */
  (void)command;
  return NULL;
}

static bool human_word(const char *word, const char *full, const char *short_form, const char *bare) {
  return strcmp(word, full) == 0 || (short_form != NULL && strcmp(word, short_form) == 0) ||
         (bare != NULL && strcmp(word, bare) == 0);
}

/*
 * Стоит ли ключ где-нибудь в вызове. Ключ, который есть у всех, обязан работать
 * и после имени команды: `flang check --help` — первое, что набирает человек,
 * и до этой правки он получал «flang check: непонятный ключ «--help»».
 *
 * Ищется по всему вызову, а не только вторым словом: у команд этого бинарника
 * ключи стоят в любом порядке. Довод, что `--help` мог бы оказаться ЗНАЧЕНИЕМ
 * соседнего ключа (`--function --help`), здесь не работает против: вызов, в
 * котором человек написал `--help`, он написал не случайно.
 */
static bool human_flag(int argc, char **argv, const char *full, const char *short_form) {
  int index = 0;
  for (index = 1; index < argc; index += 1) {
    if (strcmp(argv[index], full) == 0 || strcmp(argv[index], short_form) == 0) {
      return true;
    }
  }
  return false;
}

/* ═══════════════════════ постоянная машины ═══════════════════════ */

/*
 * `flang --машина` — снять постоянную ЭТОЙ машины и напечатать её данными.
 *
 * ── Почему данными, а не доказательством ────────────────────────────────────
 * Витки — свойство программы: их считает рантайм, и на одном входе их всегда
 * одно и то же число. Секунды — свойство машины, и языку про них знать нечего.
 * Замер недели, ради которого команда и заводится: один и тот же файл считался
 * 9 минут при загрузке 30 и 7 часов 23 минуты при загрузке 110. Ничто в
 * программе этого не предсказывает.
 *
 * Так уже устроено всё остальное в языке: программа не спрашивает мир сама,
 * внешнее приходит данными. Постоянная машины — такие же данные, как содержимое
 * файла. Отсюда и второй вид вызова: `flang --машина <файл>` берёт снятое
 * РАНЬШЕ и не мерит ничего, чтобы обещание в витках можно было перевести в
 * секунды для НАЗВАННОЙ машины, а не для той, где случилось читать.
 *
 * ── Почему постоянная НЕ ОДНА, и это видно из вывода ────────────────────────
 * Виток витку не равен: виток разбора строит узлы и просит память, виток
 * лексера читает байты. Одним числом это не описывается, и врать одним числом
 * хуже, чем назвать два. Поэтому мерится ДВЕ работы разом, обе — настоящие шаги
 * компилятора над одним и тем же эталонным исходником, и печатаются обе с
 * разбросом между ними.
 *
 * Второе, чем машина не описывается одним числом, — сколько её сейчас свободно.
 * Ядра печатаются рядом с загрузкой: 8 процессов на 8 свободных ядрах дают
 * 7,92×, а 16 потоков при 15 занятых ядрах — 1,15×. Загрузка снимается
 * `/proc/loadavg`; где его нет, там стоит «не снято», а не ноль: ноль означал
 * бы «машина свободна», и это была бы неправда.
 */

/* Эталонный исходник замера: он и разбирается, и лексится. Меняя его, меняешь
   постоянную — поэтому он лежит здесь, а не читается с диска. */
static const char MACHINE_SOURCE[] =
    "модуль «Мера машины»\n"
    "\n"
    "тотальная функция «Сумма до»\n"
    "  принимает н: число\n"
    "  возвращает число\n"
    "  убывает н\n"
    "  если н не больше 0\n"
    "    то 0\n"
    "    иначе н плюс («Сумма до» от (н минус 1))\n"
    "\n"
    "тотальная функция «Удвоить всё»\n"
    "  принимает элементы: список числа\n"
    "  возвращает список числа\n"
    "  отобразить элементы как э → э умножить на 2\n"
    "\n"
    "тотальная функция «Только большие»\n"
    "  принимает элементы: список числа, порог: число\n"
    "  возвращает список числа\n"
    "  отфильтровать элементы где э → э больше порог\n";

static double machine_now(void) {
  struct timespec point;
  if (clock_gettime(CLOCK_MONOTONIC, &point) != 0) {
    return 0.0;
  }
  return (double)point.tv_sec + (double)point.tv_nsec / 1000000000.0;
}

/* Одна работа замера: повторять, пока не набежит `least` секунд, и вернуть
   витки и секунды. Повторов не меньше одного — иначе на быстрой машине работа
   не была бы сделана ни разу и постоянная вышла бы из нуля. */
static bool machine_weigh(const char *work, double least, unsigned long *ticks, double *seconds,
                          unsigned long *rounds) {
  double started = machine_now();
  double spent = 0.0;
  unsigned long total = 0;
  unsigned long times = 0;
  bool ok = true;
  repl_call_quiet = true;
  do {
    fl_value args[2];
    fl_value out = fl_nothing();
    size_t count = 1;
    args[0] = repl_value_text(MACHINE_SOURCE, sizeof(MACHINE_SOURCE) - 1);
    if (strcmp(work, "разбор") == 0) {
      args[1] = repl_value_list(NULL, 0);
      count = 2;
      ok = repl_call("Разбор исходника", args, count, &out) == FL_OK;
    } else {
      ok = repl_call("Токены", args, count, &out) == FL_OK;
    }
    total += (unsigned long)repl_ctx.steps;
    times += 1;
    spent = machine_now() - started;
    /* Арена не отдаёт ничего сама: без сброса повторы съели бы память
       пропорционально их числу, а на быстрой машине их тысячи. */
    fl_arena_reset(&repl_arena);
  } while (ok && spent < least);
  repl_call_quiet = false;
  *ticks = total;
  *seconds = spent;
  *rounds = times;
  return ok;
}

/* Загрузка машины за минуту. Не снята — значит не снята: ноль означал бы
   «свободна», и на этом числе строили бы обещание. */
static bool machine_load(double *load) {
  size_t bytes = 0;
  char *text = repl_read_file("/proc/loadavg", &bytes);
  if (text == NULL) {
    return false;
  }
  *load = strtod(text, NULL);
  free(text);
  return true;
}

static void machine_print(FILE *to, double ticks_parse, double ticks_lex, long cores, bool has_load,
                          double load, unsigned long parse_ticks, double parse_seconds,
                          unsigned long parse_rounds, unsigned long lex_ticks, double lex_seconds,
                          unsigned long lex_rounds) {
  fprintf(to, "машина\n");
  fprintf(to, "  ядер: %ld\n", cores);
  if (has_load) {
    fprintf(to, "  занято ядер: %.2f\n", load);
    fprintf(to, "  свободно ядер: %.2f\n", (double)cores - load < 0.0 ? 0.0 : (double)cores - load);
  } else {
    fprintf(to, "  занято ядер: не снято\n");
    fprintf(to, "  свободно ядер: не снято\n");
  }
  fprintf(to, "  витков в секунду, разбор: %.0f\n", ticks_parse);
  fprintf(to, "  витков в секунду, лексер: %.0f\n", ticks_lex);
  fprintf(to, "  разброс: %.2f\n", ticks_lex > 0.0 ? ticks_parse / ticks_lex : 0.0);
  fprintf(to, "  замер разбора: %lu витков за %.6f с, повторов %lu\n", parse_ticks, parse_seconds,
          parse_rounds);
  fprintf(to, "  замер лексера: %lu витков за %.6f с, повторов %lu\n", lex_ticks, lex_seconds, lex_rounds);
}

/*
 * Снятое раньше — обратно человеку, и НИЧЕГО не мерено.
 *
 * Тот, кто читает обещание «не больше N витков», обязан знать, на ЧЁМ мерено.
 * Поэтому снятое кладут в файл рядом с обещанием, а не пересчитывают на своей
 * машине: пересчёт молча заменил бы названную машину на случайную.
 */
static int machine_recall(const char *path) {
  size_t bytes = 0;
  char *text = repl_read_file(path, &bytes);
  if (text == NULL) {
    fprintf(stderr, "flang --машина: файл «%s» не читается\n", path);
    return 1;
  }
  fputs(text, stdout);
  free(text);
  return 0;
}

static int machine_command(int argc, char **argv) {
  unsigned long parse_ticks = 0, lex_ticks = 0, parse_rounds = 0, lex_rounds = 0;
  double parse_seconds = 0.0, lex_seconds = 0.0, load = 0.0;
  long cores = 0;
  bool has_load = false;

  if (argc > 2 && argv[2][0] != '-') {
    return machine_recall(argv[2]);
  }
  if (!repl_is_compiler()) {
    fputs("flang --машина: постоянную снимает компилятор flang, а эта программа — не он.\n", stderr);
    return 2;
  }
  if (!machine_weigh("разбор", 0.25, &parse_ticks, &parse_seconds, &parse_rounds) ||
      !machine_weigh("лексер", 0.25, &lex_ticks, &lex_seconds, &lex_rounds) || parse_seconds <= 0.0 ||
      lex_seconds <= 0.0) {
    fputs("flang --машина: замер не удался — работа компилятора отказала\n", stderr);
    return 1;
  }
  cores = sysconf(_SC_NPROCESSORS_ONLN);
  if (cores < 1) {
    cores = 1;
  }
  has_load = machine_load(&load);
  machine_print(stdout, (double)parse_ticks / parse_seconds, (double)lex_ticks / lex_seconds, cores, has_load,
                load, parse_ticks, parse_seconds, parse_rounds, lex_ticks, lex_seconds, lex_rounds);
  return 0;
}

/*
 * ГОЛАЯ КОМАНДА НА ТЕРМИНАЛЕ ОТКРЫВАЕТ ОБОЛОЧКУ — как `iex`, как `python`.
 *
 * Под конвейером голая команда остаётся прогонщиком, и это не уступка, а
 * контракт: им живут тест формулы Homebrew, проба плагина asdf,
 * `scripts/build-release-c.mjs` и всякий, кто зовёт программу на flang трубой.
 * Человека на том конце различает `isatty`, и другого способа нет: JSON,
 * набираемый руками в терминале, — не тот случай, ради которого стоит держать
 * дверь.
 *
 * «Компилятор ли я» спрашивается здесь же и раньше терминала по важности: у
 * ЧУЖОЙ программы, напечатанной с этим файлом, человеческого входа нет вовсе, и
 * увести её со стандартного ввода значило бы сломать ей протокол.
 */
int fl_human_bare(void) {
  bool compiler = false;
  if (isatty(0) != 1) {
    return 0;
  }
  fl_arena_init(&repl_arena);
  fl_ctx_init(&repl_ctx, &repl_arena);
  compiler = repl_is_compiler();
  fl_arena_release(&repl_arena);
  return compiler ? 1 : 0;
}

/**
 * Человеческий вход бинарника: сюда прогонщик передаёт управление, увидев в
 * аргументах хоть что-нибудь.
 *
 * Неизвестная команда — отказ с кодом 2, а не молчание. Молчание и было прежней
 * бедой: `flang chek файл.flang` с опечаткой читал пустой стандартный ввод,
 * ничего не печатал и отвечал нулём, а человек уходил в уверенности, что
 * проверил файл.
 *
 * Арена одна на весь вход и заводится здесь: и проверка файла, и оболочка зовут
 * компилятор, и делить владение памятью между ними было бы нечем.
 */
int fl_human_main(int argc, char **argv, const char *self) {
  const char *command = argc > 1 ? argv[1] : "";
  /* Откуда запущен бинарник — запоминается здесь и только здесь: библиотеку,
     поставленную рядом с ним, ищет `repl_library_places`, а до неё довод
     `self` не доходит (`check` его не получает). */
  repl_self_kept = self;
  const bool named_help = human_word(command, "--help", "-h", "help");
  /* Версия отвечает РАНЬШЕ справки: `flang --help --version` — это вопрос о
     версии, а не просьба показать справку о ней. Порядок тот же, что у свидетеля
     на Node и у эталона на flang. */
  const bool asks_version =
      human_word(command, "--version", "-v", "version") || human_flag(argc, argv, "--version", "-v");
  const bool asks_help = named_help || human_flag(argc, argv, "--help", "-h");
  int code = 0;

  /*
   * «Кто я» спрашивается ПЕРВЫМ, раньше даже справки, и стоит это нисколько
   * (проба — разбор пустой строки). Иначе программа «Списки», собранная с этим
   * файлом, на `--help` рассказывала бы про язык flang и называла бы его
   * версию — то есть врала бы о себе там, где вопрос как раз о ней.
   */
  fl_arena_init(&repl_arena);
  fl_ctx_init(&repl_ctx, &repl_arena);
  if (!repl_is_compiler()) {
    fputs("человеческие команды есть только у компилятора flang, а эта программа — не он:\n"
          "«--help», «--version», «check» и «repl» ей делать нечего. Прогонщик по-прежнему\n"
          "читает JSON со стандартного ввода.\n",
          stderr);
    fl_arena_release(&repl_arena);
    return 2;
  }

  if (asks_version) {
    printf("flang %s\n", FLANG_VERSION);
  } else if (asks_help) {
    /* О ЧЁМ спрашивают: у `flang help check` тема стоит третьим словом, у
       `flang check --help` темой служит сама команда, у голого `flang --help`
       темы нет вовсе. */
    human_help(named_help ? (argc > 2 ? argv[2] : NULL) : command);
  } else if (argc <= 1) {
    /* Сюда приходит голая команда с терминала: прогонщик уступил дорогу
       человеку, а человеку без доводов нужна оболочка. */
    code = repl_loop(0, argv, self);
  } else if (strcmp(command, "check") == 0) {
    code = check_command(argc, argv);
  } else if (strcmp(command, "test") == 0) {
    code = test_file(argc, argv);
  } else if (strcmp(command, "run") == 0) {
    code = run_file(argc, argv);
  } else if (strcmp(command, "emit") == 0) {
    code = emit_file(argc, argv, self);
  } else if (strcmp(command, "ast") == 0) {
    code = ast_file(argc, argv);
  } else if (strcmp(command, "tokens") == 0) {
    code = tokens_file(argc, argv);
  } else if (strcmp(command, "facts") == 0) {
    code = facts_file(argc, argv);
  } else if (strcmp(command, "io") == 0) {
    code = io_file(argc, argv);
  } else if (strcmp(command, "lock") == 0) {
    code = lock_file(argc, argv);
  } else if (strcmp(command, "package") == 0) {
    code = package_file(argc, argv);
  } else if (strcmp(command, "new") == 0) {
    code = new_project(argc, argv, self);
  } else if (strcmp(command, "lsp") == 0) {
    code = lsp_serve(argc, argv);
  } else if (strcmp(command, "--mcp-mode") == 0) {
    code = mcp_serve(argc, argv);
  } else if (strcmp(command, "--машина") == 0 || strcmp(command, "--machine") == 0) {
    code = machine_command(argc, argv);
  } else if (strcmp(command, "repl") == 0) {
    code = repl_loop(argc - 1, argv + 1, self);
  } else {
    const char *elsewhere = human_elsewhere(command);
    if (elsewhere != NULL) {
      fprintf(stderr,
              "flang %s (%s) есть в полном инструментарии, а в этом двоичном — нет.\n"
              "Что умеет двоичный, скажет «flang --help». Полный ставится с Node:\n"
              "npm install -g @digitable-lol/flang\n",
              command, elsewhere);
    } else {
      fprintf(stderr, "flang: неизвестная команда «%s». «flang --help» — что умеет бинарник.\n", command);
    }
    code = 2;
  }
  fl_arena_release(&repl_arena);
  return code;
}
